Object.assign(window.TEM8_DICTIONARY, {"wide":{"media":{"uk":"media/uk/wide__gb_1.mp3","us":"media/us/wide__us_1.mp3"},"oxford":{"phon":"waɪd","pos":"adjective","senses":[{"en":"measuring a large distance from one side to the other","cn":"宽的；宽阔的","sc":"from one side to the other","ex":{"en":"It's a wide, fast-flowing river.","cn":"这是一条宽阔、水流湍急的河流。"}},{"en":"measuring a particular distance from one side to the other","cn":"…宽的；宽度为…的","sc":"from one side to the other","ex":{"en":"How wide is that stream?","cn":"那条小溪有多宽？"}},{"en":"including a large number or variety of different people or things; covering a large area","cn":"大量的；广泛的；范围大的","g":"[usually before noun]","sc":"large number/amount","ex":{"en":"a wide range/choice/variety/selection of goods","cn":"各种各样的商品"}},{"en":"very big","cn":"很大的；巨大的","sc":"difference/gap","ex":{"en":"The Australians won by a wide margin.","cn":"澳大利亚队以大比分获胜。"}},{"en":"general; not only looking at details","cn":"一般的；广泛的","sc":"general","ex":{"en":"the wider aims of the project","cn":"该计划更广义的宗旨"}},{"en":"fully open","cn":"睁大的；全张开的","sc":"eyes","ex":{"en":"She stared at him with wide eyes.","cn":"她睁大了眼睛瞪着他。"}},{"en":"far from the point aimed at","cn":"远离目标","sc":"not close","ex":{"en":"Her shot was wide (of the target).","cn":"她打的枪脱了靶。"}},{"en":"happening or existing in the whole of a country, etc.","cn":"全（国等）范围的","sc":"-wide","ex":{"en":"a nationwide search","cn":"全国性的搜查"}},{"en":"as far or fully as possible","cn":"尽可能远地；充分地","ex":{"en":"The door was wide open.","cn":"门四敞大开。"},"pos":"adverb"},{"en":"a ball that has been bowled (= thrown) where the batsman cannot reach it","cn":"宽球（因太偏导致击球手无法击打的球）","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"宽的;宽阔的;宽广的","en":"Something that is wide measures a large distance from one side or edge to the other.","ex":{"en":"All worktops should be wide enough to allow plenty of space for food preparation.","cn":"所有的厨房操作台都应该足够宽大，为制作食物提供足够的空间。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（笑容）大大的，灿烂的","en":"A wide smile is one in which your mouth is stretched because you are very pleased or amused.","ex":{"en":"It brought a wide smile to his face and laughter to his eyes","cn":"这让他眉开眼笑。"}},{"pos":"ADJ 形容词","cn":"张开很大的;完全张开的","en":"If you open or spread something wide, you open or spread it as far as possible or to the fullest extent.","ex":{"en":"Open your mouth wide","cn":"张大你的嘴。"}},{"pos":"ADJ 形容词","cn":"…宽的;宽度为…的","en":"You use wide to talk or ask about how much something measures from one side or edge to the other.","ex":{"en":"...a corridor of land 10 kilometres wide","cn":"10公里宽的陆地走廊"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"范围广的;包容的;广泛的","en":"You use wide to describe something that includes a large number of different things or people.","ex":{"en":"The brochure offers a wide choice of hotels, apartments and holiday homes","cn":"这本小册子提供了很多宾馆、公寓、度假屋供选择。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"广泛的;广为流传的;广为人知的","en":"You use wide to say that something is found, believed, known, or supported by many people or throughout a large area.","ex":{"en":"The case has attracted wide publicity","cn":"这个案子吸引了广泛的关注。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(差距等)巨大的","en":"A wide difference or gap between two things, ideas, or qualities is a large difference or gap.","ex":{"en":"Research shows a wide difference in tastes around the country","cn":"研究表明全国各地的口味大有不同。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"更大的;更多的;更广泛的","en":"Wider is used to describe something which relates to the most important or general parts of a situation, rather than to the smaller parts or to details.","ex":{"en":"He emphasised the wider issue of superpower cooperation","cn":"他强调了超级大国合作这一更重要的议题。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"未击中目标的;未打中的","en":"If something such as a shot or punch is wide, it does not hit its target but lands to the right or left of it.","ex":{"en":"The shot was wide anyway","cn":"不管怎样，这枪没打中。"}},{"pos":"","cn":"","en":"wide awake→see: ; far and wide→see: ; wide of the mark→see: ; wide open→see: ;"}]},"examples":[{"en":"The road was just wide enough for two vehicles to pass.","cn":"这条路的宽度刚好能让两辆车开过。"},{"en":"Their predictions turned out to be wide of the mark.","cn":"后来发现他们的预测结果太离谱了。"}]},"witness":{"media":{"uk":"media/uk/witness__gb_1.mp3","us":"media/us/witness__us_1.mp3"},"oxford":{"phon":"ˈwɪtnəs","pos":"noun","senses":[{"en":"a person who sees something happen and is able to describe it to other people","cn":"目击者；见证人","g":"[countable]","sc":"person who sees something","ex":{"en":"He failed to interview a key witness.","cn":"他没能采访关键的目击证人。"}},{"en":"a person who gives evidence in court","cn":"证人","g":"[countable]","sc":"in court","ex":{"en":"a defence/prosecution witness","cn":"被告的／控方的证人"}},{"en":"a person who is present when an official document is signed and who also signs it to prove that they saw this happen","cn":"见证人；联署人","g":"[countable]","sc":"of signature","ex":{"en":"He was one of the witnesses at our wedding.","cn":"他是我们婚礼的证婚人之一。"}},{"en":"evidence of a person’s strong religious beliefs, that they show by what they say and do in public","cn":"见证（以言行证实信仰）","g":"[uncountable]","sc":"of religious beliefs"},{"en":"to see something happen (typically a crime or an accident)","cn":"当场看到，目击（尤指罪行或事故）","g":"[transitive]","sc":"see something","ex":{"en":"to witness an accident/a murder/an attack","cn":"目击一场事故／谋杀／袭击"},"pos":"verb"},{"en":"to be the place, period, organization, etc. in which particular events take place","cn":"是发生…的地点（或时间、组织等）；见证","g":"[transitive]","sc":"of time/place","ex":{"en":"Recent years have witnessed a growing social mobility.","cn":"近年来人们的社会流动性越来越大。"},"pos":"verb"},{"en":"to be present when an official document is signed and sign it yourself to prove that you saw this happen","cn":"（为正式文件的签署）作证，联署","g":"[transitive]","sc":"signature","ex":{"en":"to witness a signature","cn":"联署作证"},"pos":"verb"},{"en":"to be a sign or proof of something","cn":"是…的迹象；为…的证据","g":"[intransitive, transitive, usually passive]","sc":"be sign/proof","ex":{"en":"The huge attendance figures for the exhibition witness to a healthy interest in modern art.","cn":"从展览会参观人数之多可以看出，人们对现代艺术具有浓厚兴趣。"},"pos":"verb"},{"en":"used when giving an example that proves something you have just said","cn":"（摆证据）…就是证据，看…就知道","g":"[transitive]","lab":"formal","sc":"be sign/proof","ex":{"en":"Authentic Italian cooking is very healthy—witness the low incidence of heart disease in Italy.","cn":"正宗的意大利烹饪对健康非常有益，在意大利心脏病发病率低就是证据。"},"pos":"verb"},{"en":"to speak to people about your strong religious beliefs","cn":"（为宗教信仰）做见证","g":"[intransitive]","lab":"especially North American English","sc":"to religious beliefs","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"见证人;目击者","en":"A witness to an event such as an accident or crime is a person who saw it.","ex":{"en":"Witnesses to the crash say they saw an explosion just before the disaster","cn":"空难目击者称，就在灾难发生之前他们看见飞机发生了爆炸。"}},{"pos":"VERB 动词","cn":"目击;目睹","en":"If you witness something, you see it happen.","ex":{"en":"Anyone who witnessed the attack should call the police","cn":"目睹这次袭击的人都应向警方报告。"}},{"pos":"N-COUNT 可数名词","cn":"(出庭的)证人","en":"A witness is someone who appears in a court of law to say what they know about a crime or other event.","ex":{"en":"In the next three or four days, eleven witnesses will be called to testify.","cn":"接下来的三四天里，将传唤11名证人出庭作证。"}},{"pos":"N-COUNT 可数名词","cn":"见证人;连署人","en":"A witness is someone who writes their name on a document that you have signed, to confirm that it really is your signature."},{"pos":"VERB 动词","cn":"为(文件的签署)作证;连署","en":"If someone witnesses your signature on a document, they write their name after it, to confirm that it really is your signature.","ex":{"en":"Ask a friend to witness your signature.","cn":"请一位朋友给你的签名作证。"}},{"pos":"VERB 动词","cn":"见证，经历(事件、变化等)","en":"If you say that a place, period of time, or person witnessed a particular event or change, you mean that it happened in that place, during that period of time, or while that person was alive.","ex":{"en":"India has witnessed many political changes in recent years","cn":"印度近年来经历了很多政治变动。"}},{"pos":"VERB 动词","cn":"以…为证;…便是明证","en":"You use witness to introduce an example of what you have just been talking about.","ex":{"en":"Americans are a generous people: witness the increase in charitable giving, even during the recession.","cn":"美国人是个慷慨的民族：即使是在经济萧条时期，慈善捐赠也在不断增加，这便是明证。"}},{"pos":"PHRASE 短语","cn":"是…的见证人;是…的目击者","en":"If you are witness to something, you see it happen.","ex":{"en":"Too often children are witness to a disturbing amount of violence.","cn":"孩子们经常会目睹暴力事件,其数量之多令人不安。"}},{"pos":"PHRASE 短语","cn":"证明;为…作证","en":"If a person or thing bears witness to something, they show or say that it exists or happened.","ex":{"en":"Many of these poems bear witness to his years spent in India and China","cn":"这些诗中有很多见证了他在印度和中国度过的岁月。"}}]},"examples":[{"en":"Authentic Italian cooking is very healthy — witness the low incidence of heart disease in Italy.","cn":"正宗的意大利烹饪对健康非常有益，在意大利心脏病发病率低就是证据。"},{"en":"There has been increasing interest in her life and work, as witnessed by the publication of two new biographies.","cn":"从两部新传记的出版可以看出，人们对她的生活和工作越来越感兴趣。"}]},"wifely":{"media":{"uk":"media/uk/wifely__gb_1.mp3","us":"media/us/wifely__us_1.mp3"},"oxford":{"phon":"ˈwaɪfli","pos":"adjective","senses":[{"en":"typical or expected of a wife","cn":"妻子特有（或应有）的；作为人妻的；已婚妇女的","ex":{"en":"wifely duties","cn":"妻子的责任"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"贤妻的;贤妇特有的","en":"Wifely is used to describe things that are supposed to be typical of a good wife.","ex":{"en":"She strove to perform all her wifely functions perfectly.","cn":"她努力做一个无可挑剔的贤妻。"}}]},"examples":[{"en":"wifely duties","cn":"妻子的责任"}]},"winners":{"oxford":{"phon":"ˈwɪnə(r)","pos":"noun","senses":[{"en":"a person, a team, an animal, etc. that wins sth","cn":"获胜的人（或队、动物等）；优胜者"},{"en":"( informal ) a thing or person that is successful or likely to be successful","cn":"成功者；可能成功的人（或事物）"}]}},"width":{"oxford":{"phon":"wɪdθ","pos":"noun","senses":[{"en":"the measurement from one side of something to the other; how wide something is","cn":"宽度；广度","g":"[uncountable, countable]","ex":{"en":"The terrace runs the full width of the house.","cn":"露台和房子一般宽。"}},{"en":"a piece of material of a particular width","cn":"某一宽度的材料","g":"[countable]","ex":{"en":"You'll need two widths of fabric for each curtain.","cn":"每个窗帘你需要两块这样宽的布料。"}},{"en":"the distance between the two long sides of a swimming pool","cn":"（游泳池两长边之间的）池宽","g":"[countable]","ex":{"en":"How many widths can you swim?","cn":"你在游泳池里横向能游几个来回？"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"宽度;广度","en":"The width of something is the distance it measures from one side or edge to the other.","ex":{"en":"Measure the full width of the window","cn":"测量一下窗户的全宽。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"宽阔；宽大","en":"The width of something is its quality of being wide.","ex":{"en":"The best utensil for steaming is a wok because its width easily accommodates a whole fish.","cn":"锅是蒸鱼的最好器具，因为它很宽，可以轻松放下一整条鱼。"}},{"pos":"N-COUNT 可数名词","cn":"（游泳池的）池宽","en":"A width is the distance from one side of a swimming pool to the other.","ex":{"en":"We swam several widths.","cn":"我们游了好几个来回。"}}]},"media":{"uk":"media/uk/width__gb_1.mp3","us":"media/us/width__us_1.mp3"},"examples":[{"en":"You'll need two widths of fabric for each curtain.","cn":"每个窗帘你需要两块这样宽的布料。"},{"en":"How many widths can you swim?","cn":"你在游泳池里横向能游几个来回？"}]},"widespread":{"media":{"uk":"media/uk/widespread__gb_1.mp3","us":"media/us/widespread__us_1.mp3"},"oxford":{"phon":"ˈwaɪdspred","pos":"adjective","senses":[{"en":"existing or happening over a large area or among many people","cn":"分布广的；普遍的；广泛的","ex":{"en":"The storm caused widespread damage.","cn":"暴风雨造成大范围的破坏。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"普遍的;广泛的","en":"Something that is widespread exists or happens over a large area, or to a great extent.","ex":{"en":"There is widespread support for the new proposals","cn":"新提议获得了广泛的支持。"}}]},"examples":[{"en":"The plan received widespread support throughout the country.","cn":"这项计划得到了全国的普遍支持。"},{"en":"widespread damage","cn":"广泛的损坏"}]},"wisdom":{"oxford":{"phon":"ˈwɪzdəm","pos":"noun","senses":[{"en":"the ability to make sensible decisions and give good advice because of the experience and knowledge that you have","cn":"智慧；才智；精明","ex":{"en":"She was known to be a woman of great wisdom.","cn":"众所周知，她是一位具有大智慧的女性。"}},{"en":"how sensible something is","cn":"明智","ex":{"en":"I question the wisdom of giving a child so much money.","cn":"我对给孩子这么多钱是否明智怀有疑问。"}},{"en":"the knowledge that a society or culture has gained over a long period of time","cn":"（社会或文化长期积累的）知识，学问","ex":{"en":"the collective wisdom of our people","cn":"我们人民的集体智慧"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"智慧;才智","en":"Wisdom is the ability to use your experience and knowledge in order to make sensible decisions or judgments.","ex":{"en":"...the patience and wisdom that comes from old age.","cn":"历尽岁月沧桑而形成的耐心与智慧"}},{"pos":"N-VAR 可变名词","cn":"(社会或文化长期积累的)知识，学问","en":"Wisdom is the store of knowledge that a society or culture has collected over a long period of time.","ex":{"en":"...a folksy piece of wisdom.","cn":"一种民间的智慧"}},{"pos":"N-SING 单数名词","cn":"明智","en":"If you talk about the wisdom of a particular decision or action, you are talking about how sensible it is.","ex":{"en":"Many Lithuanians have expressed doubts about the wisdom of the decision.","cn":"很多立陶宛人对该决定是否明智表示了怀疑。"}},{"pos":"N-VAR 可变名词","cn":"一般观点;普遍看法","en":"You can use wisdom to refer to ideas that are accepted by a large number of people.","ex":{"en":"Health education wisdom in the UK differs from that of the United States","cn":"英国的健康教育理念与美国的不同。"}}]},"media":{"uk":"media/uk/wisdom__gb_1.mp3","us":"media/us/wisdom__us_1.mp3"},"examples":[{"en":"I question the wisdom of giving a child so much money.","cn":"我对给孩子这么多钱是否明智怀有疑问。"},{"en":"Conventional wisdom has it that riots only ever happen in cities.","cn":"人们普遍认为，只有城市里才发生暴乱。"}]},"willingness":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the state of being prepared to do something","cn":"愿意，乐意"}]},"examples":[{"en":"He has shown no willingness to compromise.","cn":"他不愿意妥协。","src":"ld"}],"media":{"uk":"media/uk/willingness__gb_1.mp3","us":"media/us/willingness__us_1.mp3"},"oxford":{"phon":"ˈwɪlɪŋnəs","pos":"noun","senses":[{"en":"the quality of being happy and ready to do something","cn":"愿意；乐意；自愿","ex":{"en":"Success in studying depends on a willingness to learn.","cn":"乐于学习才能学业有成。"}}]}},"withdraw":{"media":{"uk":"media/uk/withdraw__gb_1.mp3","us":"media/us/withdraw__us_1.mp3"},"oxford":{"phon":"wɪðˈdrɔː","pos":"verb","senses":[{"en":"to take money out of a bank account","cn":"提（款）；取（钱）","g":"[transitive]","lab":"informal","ex":{"en":"With this account, you can withdraw up to £300 a day.","cn":"这个账户每天最多可提取 300 英镑。"}},{"en":"to move back or away from a place or situation; to make somebody/something do this","cn":"（使）撤回，撤离","g":"[intransitive, transitive]","ex":{"en":"Government troops were forced to withdraw.","cn":"政府部队被迫撤走了。"}},{"en":"to stop taking part in an activity or being a member of an organization; to stop somebody/something from doing these things","cn":"（使）退出","g":"[intransitive, transitive]","ex":{"en":"In 2016 Britain voted to withdraw from the EU.","cn":"英国于 2016 年投票退出欧盟。"}},{"en":"to stop giving or offering something to somebody","cn":"停止提供；不再给予","g":"[transitive]","ex":{"en":"Workers have threatened to withdraw their labour (= go on strike).","cn":"工人扬言要罢工。"}},{"en":"to say that you no longer believe that something you previously said is true","cn":"收回，撤回，撤销（说过的话）","g":"[transitive]","lab":"formal","ex":{"en":"The newspaper withdrew the allegations the next day.","cn":"这家报纸第二天收回了这些说法。"}},{"en":"to become quieter and spend less time with other people","cn":"脱离（社会）；不与人交往","g":"[intransitive]","ex":{"en":"She's beginning to withdraw into herself.","cn":"她开始变得不爱与人交往了。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"撤走;拿走","en":"If you withdraw something from a place, you remove it or take it away.","ex":{"en":"He reached into his pocket and withdrew a sheet of notepaper","cn":"他把手伸进口袋，掏出一张便签。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)撤退;(使)撤回;(使)撤离","en":"When groups of people such as troops withdraw or when someone withdraws them, they leave the place where they are fighting or where they are based and return nearer home.","ex":{"en":"He stated that all foreign forces would withdraw as soon as the crisis ended","cn":"他声明危机一结束，所有外国军队都将撤离。"}},{"pos":"VERB 动词","cn":"提，取(款)","en":"If you withdraw money from a bank account, you take it out of that account.","ex":{"en":"Open a savings account that does not charge ridiculous fees to withdraw money","cn":"开一个取款时不会乱收费的储蓄账户。"}},{"pos":"VERB 动词","cn":"退出，返回(至另一个房间)","en":"If you withdraw to another room, you go there.","ex":{"en":"He and the others withdrew to their rented rooms","cn":"他和其他人回到了他们租住的房间。"}},{"pos":"VERB 动词","cn":"退出(活动或组织)","en":"If you withdraw from an activity or organization, you stop taking part in it.","ex":{"en":"The African National Congress threatened to withdraw from the talks.","cn":"非洲国民大会威胁要退出会谈。"}},{"pos":"VERB 动词","cn":"收回，撤回(所说的话或声明)","en":"If you withdraw a remark or statement that you have made, you say that you want people to ignore it.","ex":{"en":"He withdrew his remarks and explained what he had meant to say.","cn":"他收回所说的话，然后又解释他本来想说什么。"}}]},"examples":[{"en":"The drug was withdrawn from sale after a number of people suffered serious side effects.","cn":"这药因许多人服后产生严重副作用而被停止销售。"},{"en":"Both powers withdrew their forces from the region.","cn":"两个大国都把部队撤离了这个地区。"}]},"without":{"media":{"uk":"media/uk/without__gb_1.mp3","us":"media/us/without__us_1.mp3"},"oxford":{"phon":"wɪˈðaʊt","pos":"preposition","senses":[{"en":"not having, experiencing or showing something","cn":"没有；缺乏","ex":{"en":"They had gone two days without food.","cn":"他们两天没吃东西了。"}},{"en":"not in the company of somebody","cn":"不和…在一起；无…相伴","ex":{"en":"Don't go without me.","cn":"别甩下我就走。"}},{"en":"not using or taking something","cn":"不用；不拿；不带","ex":{"en":"Can you see without your glasses?","cn":"你不戴眼镜能看见吗？"}},{"en":"not doing the action mentioned","cn":"不（做某事）；无；没","ex":{"en":"He left without saying goodbye.","cn":"他不辞而别。"}},{"en":"not having or showing something","cn":"没有；缺乏","ex":{"en":"Do you want a room with a bath or one without?","cn":"你要不要带洗澡间的房间？"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"缺乏；没有;不用","en":"You use without to indicate that someone or something does not have or use the thing mentioned.","ex":{"en":"I don't like myself without a beard","cn":"我不喜欢自己没胡子的样子。"}},{"pos":"PREP 介词","cn":"在没有(发生或做某事)的情况下","en":"If one thing happens without another thing, or if you do something without doing something else, the second thing does not happen or occur.","ex":{"en":"He was offered a generous pension provided he left without a fuss","cn":"他如果一声不吭地离开，就会获得一笔丰厚的养老金。"}},{"pos":"PREP 介词","cn":"没有，不带(某种感情)","en":"If you do something without a particular feeling, you do not have that feeling when you do it.","ex":{"en":"Janet Magnusson watched his approach without enthusiasm","cn":"珍妮特·马格努森冷冷地看着他走过来。"}},{"pos":"PREP 介词","cn":"…不在场;没有…参加","en":"If you do something without someone else, they are not in the same place as you are or are not involved in the same action as you.","ex":{"en":"I told Franklin he would have to start dinner without me","cn":"我告诉富兰克林吃晚饭不必等我。"}}]},"examples":[{"en":"Without wanting to criticize, I think you could have done better. (= used before you make a critical comment)","cn":"我不是想要批评谁，只是认为你本可以做得更好一些。"},{"en":"You can't make an omelette without breaking eggs.","cn":"你不可能不打破鸡蛋就做成煎蛋卷。"}]},"wins":{"oxford":{"phon":"wɪn","pos":"verb","senses":[{"en":"to be the most successful in a competition, race, battle, etc. （","cn":"在比赛、赛跑、战斗等中）获胜，赢"},{"en":"to get sth as the result of a competition, race, election, etc. （","cn":"在比赛、赛跑、选举等中）赢得，夺取，获得，挣得"}]},"media":{"uk":"media/uk/win__gb_1.mp3","us":"media/us/win__us_1.mp3"}},"witless":{"media":{"uk":"media/uk/witless__gb_1.mp3","us":"media/us/witless__us_1.mp3"},"oxford":{"phon":"ˈwɪtləs","pos":"adjective","senses":[{"en":"silly or stupid; not sensible","cn":"愚蠢的；不明事理的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"愚蠢的;笨的;傻的","en":"If you describe something or someone as witless, you mean that they are very foolish or stupid.","ex":{"en":"...a witless, nasty piece of journalism.","cn":"极为肤浅、令人作呕的新闻报道"}}]}},"wind":{"media":{"uk":"media/uk/wind__gb_1.mp3","us":"media/us/wind__us_1.mp3"},"oxford":{"phon":"wɪnd","pos":"noun","senses":[{"en":"air that moves quickly as a result of natural forces","cn":"风；气流","g":"[countable, uncountable]","lab":"North American English","ex":{"en":"strong/high winds","cn":"强劲的风；大风"}},{"en":"air that you swallow with food or drink; gas that is produced in your stomach or intestines that makes you feel uncomfortable","cn":"（随食物或饮料）吞下的气；胃气；肠气","g":"[uncountable]","lab":"British English","ex":{"en":"I can't eat beans—they give me wind.","cn":"我不能吃豆子，吃了肚子就胀气。"}},{"en":"breath that you need when you do exercise or blow into a musical instrument","cn":"（运动或吹奏乐器时的）呼吸","g":"[uncountable]","ex":{"en":"I need time to get my wind back after that run.","cn":"我跑过之后需要时间喘口气。"}},{"en":"the group of musical instruments in an orchestra that produce sounds when you blow into them, especially woodwind instruments; the musicians who play those instruments","cn":"（尤指管弦乐团的）木管乐器；管乐器组","g":"[uncountable + singular or plural verb]","ex":{"en":"music for wind and strings","cn":"管弦乐"}},{"en":"to make somebody unable to breathe easily for a short time","cn":"使喘不过气来；使喘大气","g":"[usually passive]","ex":{"en":"He was momentarily winded by the blow to his stomach.","cn":"他的肚子上挨了一击，一时喘不过气来。"},"pos":"verb"},{"en":"to gently hit or rub a baby’s back to make it burp (= release gas from its stomach through its mouth)","cn":"（轻拍婴儿后背）使嗳气","lab":"British English","pos":"verb"},{"en":"an act of turning, wrapping or twisting something around itself or in a circle","cn":"卷缠；缠绕；绕成团","ex":{"en":"Give the handle another couple of winds.","cn":"再转动两下手柄。"}},{"en":"to have many bends and twists","cn":"蜿蜒；曲折而行；迂回","g":"[intransitive, transitive]","ex":{"en":"The path wound down to the beach.","cn":"这条小路弯弯曲曲通向海滩。"},"pos":"verb"},{"en":"to wrap or twist something around itself or something else","cn":"卷缠；缠绕；绕成团","g":"[transitive]","ex":{"en":"He wound the wool into a ball.","cn":"他把毛线缠绕成一团。"},"pos":"verb"},{"en":"to operate a tape, film, etc. so that it moves nearer to its ending or starting position","cn":"卷绕，倒（磁带、胶卷等）","g":"[transitive, intransitive]","ex":{"en":"He wound the tape back to the beginning.","cn":"他把磁带倒到了开头。"},"pos":"verb"},{"en":"to make a clock or a machine work by turning a knob, handle, etc. several times; to be able to be made to work in this way","cn":"给（钟表等）上发条；（通过转动把手等）操作；可上发条；可通过转动把手（等）操作","g":"[transitive, intransitive]","ex":{"en":"He had forgotten to wind his watch.","cn":"他忘了给表上发条了。"},"pos":"verb"},{"en":"to turn a handle several times","cn":"转动（把手）","g":"[transitive]","ex":{"en":"You operate the trapdoor by winding this handle.","cn":"你要转动这个手柄来操纵活动天窗。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"风","en":"A wind is a current of air that is moving across the earth's surface.","ex":{"en":"There was a strong wind blowing","cn":"狂风肆虐。"}},{"pos":"N-COUNT 可数名词","cn":"(影响事件的)趋势（或因素）（常作新闻用语）","en":"Journalists often refer to a trend or factor that influences events as a wind of a particular kind.","ex":{"en":"The winds of change are blowing across the country","cn":"改革之风吹遍全国。"}},{"pos":"VERB 动词","cn":"使气急;使呼吸困难","en":"If you are winded by something such as a blow, the air is suddenly knocked out of your lungs so that you have difficulty breathing for a short time.","ex":{"en":"He was winded and shaken","cn":"他呼吸困难，身体发抖。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（胃肠中的）气","en":"Wind is the air that you sometimes swallow with food or drink, or gas that is produced in your intestines, which causes an uncomfortable feeling."},{"pos":"VERB 动词","cn":"给(婴儿）拍嗝儿","en":"If you wind a baby, you hit its back gently in order to help it to release air from its stomach.","ex":{"en":"If he cries when you put him down after a feed, try winding him.","cn":"如果你喂完后把他放下时他哭，给他拍拍嗝儿。"}},{"pos":"ADJ 形容词","cn":"管乐的","en":"The wind section of an orchestra or band is the group of people who produce musical sounds by blowing into their instruments."},{"pos":"PHRASE 短语","cn":"放屁","en":"If someone breaks wind, they release gas from their intestines through their anus."},{"pos":"PHRASE 短语","cn":"听到…的风声","en":"If you get wind of something, you hear about it, especially when someone else did not want you to know about it.","ex":{"en":"I don't want the public, and especially not the press, to get wind of it at this stage.","cn":"我不想让公众，尤其是新闻界，在这个阶段听到什么风声。"}},{"pos":"PHRASE 短语","cn":"可能发生","en":"If something is in the wind, it is likely to happen.","ex":{"en":"By the mid-1980s, change was in the wind again.","cn":"20世纪80年代中期，变革又呈山雨欲来之势。"}},{"pos":"PHRASE 短语","cn":"吓唬;使焦虑","en":"If something or someone puts the wind up you, they frighten or worry you.","ex":{"en":"'I heard you had some funny phone calls.' — 'Yeah, that's why yours rather put the wind up me.'","cn":"“我听说你接到了一些骚扰电话。”——“没错儿，所以你的电话把我吓坏了。”"}},{"pos":"PHRASE 短语","cn":"冒险做事(或说话)","en":"If you sail close to the wind, you take a risk by doing or saying something that may get you into trouble.","ex":{"en":"Max warned her she was sailing dangerously close to the wind and risked prosecution.","cn":"马克斯警告她说她这是在玩火，有被起诉的危险。"}},{"pos":"PHRASE 短语","cn":"给…泼冷水（或当头一棒）","en":"If something takes the wind out of your sails, it suddenly makes you much less confident in what you are doing or saying."},{"pos":"PHRASE 短语","cn":"可能发生何事;事态的发展","en":"If you realize or find out which way the wind is blowing or how the wind is blowing, you realize or find out what is likely to happen, for example whether something is likely to succeed.","ex":{"en":"He didn't like to make pronouncements before he was sure which way the wind was blowing.","cn":"在没有弄清事态的走向前，他不想发表声明。"}},{"pos":"","cn":"","en":"to throw caution to the wind→see: ;"},{"pos":"VERB 动词","cn":"(道路、河流或一队人)蜿蜒向前，曲折而行，迂回","en":"If a road, river, or line of people winds in a particular direction, it goes in that direction with a lot of bends or twists in it.","ex":{"en":"The Moselle winds through some 160 miles of tranquil countryside","cn":"摩泽尔河在宁静的乡间蜿蜒穿行约160英里。"}},{"pos":"VERB 动词","cn":"卷绕;缠绕","en":"When you wind something flexible around something else, you wrap it around it several times.","ex":{"en":"The horse jumped forwards and round her, winding the rope round her waist.","cn":"那匹马围着她向前跳，把绳子绕在了她腰上。"}},{"pos":"VERB 动词","cn":"给(钟表等)上发条;给…上弦","en":"When you wind a mechanical device, for example a watch or a clock, you turn a knob, key, or handle on it several times in order to make it operate.","ex":{"en":"I still hadn't wound my watch so I didn't know the time.","cn":"我还没有给表上发条，所以不知道时间。"}},{"pos":"VERB 动词","cn":"倒/进(磁带或胶卷)","en":"To wind a tape or film back or forward means to make it move towards its starting or ending position.","ex":{"en":"The camcorder winds the tape back or forward at high speed.","cn":"这款便携式摄像机可以使录像带快速倒回或前进。"}},{"pos":"","cn":"","en":"相关词组：wind down wind up"}]},"examples":[{"en":"He kicked Gomez in the stomach, knocking the wind out of him.","cn":"他踢了戈梅斯的肚子，把他踢得喘不上气来。"},{"en":"We eventually wound up staying in a little hotel a few miles from town.","cn":"我们最后在离城几英里的一家小旅馆里落脚。"}]},"willing":{"media":{"uk":"media/uk/willing__gb_1.mp3","us":"media/us/willing__us_1.mp3"},"oxford":{"phon":"ˈwɪlɪŋ","pos":"adjective","senses":[{"en":"not objecting to doing something; having no reason for not doing something","cn":"愿意；乐意","g":"[not usually before noun]","ex":{"en":"Many consumers are willing to pay more for organic food","cn":"很多消费者愿意多花钱购买有机食品。"}},{"en":"ready or pleased to help and not needing to be persuaded; done or given in an enthusiastic way","cn":"自愿的；乐于相助的；积极肯干的","g":"[usually before noun]","ex":{"en":"a willing participant/accomplice","cn":"主动参加的人；自愿的帮凶"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"乐意的;愿意的","en":"If someone is willing to do something, they are fairly happy about doing it and will do it if they are asked or required to do it.","ex":{"en":"The military now say they're willing to hold talks with the political parties","cn":"军方现在说，他们愿意与政党进行谈判。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自愿的;愿意的;积极肯干的","en":"Willing is used to describe someone who does something fairly enthusiastically and because they want to do it rather than because they are forced to do it.","ex":{"en":"Have the party on a Saturday, when you can get your partner and other willing adults to help","cn":"把聚会安排在周六，这样你就可以找自己的搭档和其他愿意帮把手的成年人来帮忙了。"}},{"pos":"","cn":"","en":"God willing→see: ;"}]},"examples":[{"en":"People would willingly pay more for better services.","cn":"有好一些的服务，人们是愿意多花钱的。"},{"en":"They keep a list of people (who are) willing to work nights.","cn":"他们有一份愿意夜间工作的人的名单。"}]},"win":{"media":{"uk":"media/uk/win__gb_1.mp3","us":"media/us/win__us_1.mp3"},"oxford":{"phon":"wɪn","pos":"verb","senses":[{"en":"to be the most successful in a competition, race, battle, etc.","cn":"（在比赛、赛跑、战斗等中）获胜，赢","g":"[intransitive, transitive]","ex":{"en":"Which team won?","cn":"哪个队赢了？"}},{"en":"to get something as the result of a competition, race, election, etc.","cn":"（在比赛、赛跑、选举等中）赢得，夺取，获得，挣得","g":"[transitive]","ex":{"en":"Britain won five gold medals.","cn":"英国夺取了五块金牌。"}},{"en":"to achieve or get something that you want, especially by your own efforts","cn":"（尤指通过自己的努力）取得，获得","g":"[transitive]","ex":{"en":"They are trying to win support for their proposals.","cn":"他们在努力争取人们支持他们的建议。"}},{"en":"a victory in a game, contest, etc.","cn":"（在比赛、竞赛等中的）胜利","lab":"figurative","ex":{"en":"two wins and three defeats","cn":"两胜三负"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"赢；赢得","en":"If you win something such as a competition, battle, or argument, you defeat those people you are competing or fighting against, or you do better than everyone else involved.","ex":{"en":"He does not have any realistic chance of winning the election","cn":"他没有一点儿赢得选举的现实机会。"}},{"pos":"VERB 动词","cn":"使…赢得;使…获得","en":"If something wins you something such as an election, competition, battle, or argument, it causes you to defeat the people competing with you or fighting you, or to do better than everyone else involved.","ex":{"en":"That sort of gain for Labour is nothing like good enough to win them the general election","cn":"工党那点斩获远不足以让他们赢得大选。"}},{"pos":"VERB 动词","cn":"赢得，获得(奖项或奖牌)","en":"If you win something such as a prize or medal, you get it because you have defeated everyone else in something such as an election, competition, battle, or argument, or have done very well in it.","ex":{"en":"The first correct entry wins the prize","cn":"第一个答对者将获得奖品。"}},{"pos":"VERB 动词","cn":"获得，赢得(想要或需要之物)","en":"If you win something that you want or need, you succeed in getting it.","ex":{"en":"...moves to win the support of the poor","cn":"赢得穷人支持的举措"}},{"pos":"VERB 动词","cn":"为…赢得","en":"If something wins you a prize or wins you something else that you want, it causes you to get it.","ex":{"en":"The feat won them a prize of £85,000","cn":"这一业绩为他们赢得了85,000英镑的奖金。"}},{"pos":"PHRASE 短语","cn":"注定失败;怎么做都不好","en":"If you say that someone can't win in a particular situation, you mean that they are certain to fail or to suffer whatever they do.","ex":{"en":"If you're too assertive they regard you as an aggressive hysterical woman. I mean, you can't win!","cn":"如果你太坚定自信，他们就会把你看作是咄咄逼人、歇斯底里的女人。我是说，你怎么做都不对。"}},{"pos":"CONVENTION 惯用语","cn":"(与人稍稍争论后，虽然不情愿，但同意按对方说的做，或接受其建议)听你的，按你说的做","en":"You say 'you win' when you have been having a slight argument with someone and you are indicating that you agree to do what they want or that you accept their suggestion, even though you do not really want to.","ex":{"en":"'All right', I said. 'You win'.","cn":"“好吧，”我说道，“听你的。”"}},{"pos":"","cn":"","en":"to lose the battle but win the war→see: ; to win the day→see: ; to win hands down→see: ;"},{"pos":"","cn":"","en":"相关词组：win back win out win over win round win through win through to"}]},"examples":[{"en":"The party is struggling to win back voters who have been alienated by recent scandals.","cn":"这个政党正尽力把最近因丑闻而疏远的选民争取回来。"},{"en":"The Conservatives won the seat from Labour in the last election.","cn":"在上次选举中保守党从工党手中夺得了这个议席。"}]},"wi":{"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"West Indies","cn":"西印度群岛"},{"en":"Women’s Institute (a British women’s organization in which groups of women meet regularly to take part in various activities)","cn":"（英国）妇女协会"}]},"media":{"uk":"media/uk/wi__gb_1.mp3","us":"media/us/wi__us_1.mp3"}},"winning":{"oxford":{"phon":"ˈwɪnɪŋ","pos":"adjective","senses":[{"en":"that wins or has won something, for example a race or competition","cn":"获胜的；赢的","g":"[only before noun]","ex":{"en":"the winning horse","cn":"获胜的马"}},{"en":"attractive in a way that makes other people like you","cn":"吸引人的；动人的；迷人的；可爱的","g":"[usually before noun]","ex":{"en":"‘I'm sorry I'm so late,’ she said, flashing us a winning smile.","cn":"“很抱歉我来晚了，”她说道，向我们露出了迷人的微笑。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"获胜的;赢的","en":"You can use winning to describe a person or thing that wins something such as a competition, game, or election.","ex":{"en":"...the leader of the winning party","cn":"获胜党的领导人"}},{"pos":"ADJ 形容词","cn":"迷人的;可爱的","en":"You can use winning to describe actions or qualities that please other people and make them feel friendly towards you.","ex":{"en":"She gave him another of her winning smiles","cn":"她又给了他一个动人的微笑。"}}]},"media":{"uk":"media/uk/winning__gb_1.mp3","us":"media/us/winning__us_1.mp3"},"examples":[{"en":"the winning goal","cn":"制胜的一记入球"},{"en":"a winning smile","cn":"动人的微笑"}]},"wit":{"media":{"uk":"media/uk/wit__gb_1.mp3","us":"media/us/wit__us_1.mp3"},"oxford":{"phon":"wɪt","pos":"noun","senses":[{"en":"the ability to say or write things that are both clever and humorous","cn":"措辞巧妙的能力；风趣；才思","g":"[uncountable, singular]","ex":{"en":"to have a quick/sharp/dry/ready wit","cn":"才思敏捷；敏锐机智；假装正经的诙谐；头脑机敏"}},{"en":"a person who has the ability to say or write things that are both clever and humorous","cn":"才思敏捷说话诙谐的人；机智幽默的人","g":"[countable]","ex":{"en":"a well-known wit and raconteur","cn":"一位闻名遐迩、妙语连珠的故事大王"}},{"en":"your ability to think quickly and clearly and to make good decisions","cn":"理解力；颖悟力；头脑；智力","g":"[plural]","ex":{"en":"He needed all his wits to find his way out.","cn":"他需要绞尽脑汁找到出路。"}},{"en":"having the type of intelligence mentioned","cn":"有…智慧的；头脑…的","ex":{"en":"a quick-witted group of students","cn":"一群头脑聪明的学生"}},{"en":"the intelligence or good sense to know what is the right thing to do","cn":"（正确判断的）能力，智力；明智","g":"[uncountable]","ex":{"en":"At least you had the wit to ask for help.","cn":"你起码还能意识到要求救。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（说话的）风趣，机智，巧妙","en":"Wit is the ability to use words or ideas in an amusing, clever, and imaginative way.","ex":{"en":"Boulding was known for his biting wit","cn":"博尔丁爱说尖酸的俏皮话是出了名的。"}},{"pos":"N-COUNT 可数名词","cn":"风趣的人;机智的人","en":"If you describe someone as a wit, you mean that they have the ability to use words or ideas in an amusing, clever, and imaginative way.","ex":{"en":"Holmes was gregarious, a great wit, a man of wide interests.","cn":"福尔摩斯爱交际,非常风趣，兴趣广泛。"}},{"pos":"N-SING 单数名词","cn":"头脑；智慧","en":"If you say that someone has the wit to do something, you mean that they have the intelligence and understanding to make the right decision or take the right action in a particular situation.","ex":{"en":"The information is there and waiting to be accessed by anyone with the wit to use it.","cn":"资料就摆在那儿，等着有头脑的人去利用。"}},{"pos":"N-PLURAL 复数名词","cn":"机智","en":"You can refer to your ability to think quickly and cleverly in a difficult situation as your wits .","ex":{"en":"She has used her wits to progress to the position she holds today.","cn":"她凭借个人才智升到了今天的职位。"}},{"pos":"N-PLURAL 复数名词","cn":"把…吓得魂不附体","en":"You can use wits in expressions such as frighten someone out of their wits and scare the wits out of someone to emphasize that a person or thing worries or frightens someone very much.","ex":{"en":"You scared us out of our wits. We heard you had an accident.","cn":"你把我们吓坏了，我们听说你出事了。"}},{"pos":"PHRASE 短语","cn":"时刻保持警惕;随机应变","en":"If you have your wits about you or keep your wits about you, you are alert and ready to act in a difficult situation.","ex":{"en":"Travellers need to keep their wits about them.","cn":"旅行者需要随机应变。"}},{"pos":"PHRASE 短语","cn":"智穷才尽;黔驴技穷;无计可施","en":"If you say that you are at your wits' end, you are emphasizing that you are so worried and exhausted by problems or difficulties that you do not know what to do next.","ex":{"en":"We row a lot and we never have time on our own. I'm at my wit's end.","cn":"我们经常争吵，从无在一起的时间，我真是没有办法了。"}},{"pos":"PHRASE 短语","cn":"与…斗智;与…比学问","en":"If you pit your wits against someone, you compete against them in a test of knowledge or intelligence.","ex":{"en":"He has to pit his wits against an adversary who is cool, clever and cunning.","cn":"他不得不与一个冷静、聪明而又狡猾的对手斗智。"}},{"pos":"PHRASE 短语","cn":"（用于更准确地描述）亦即，也就是","en":"To wit is used to indicate that you are about to state or describe something more precisely.","ex":{"en":"He'd like 'happiness' to be given a new and more scientifically descriptive label, to wit 'Major affective disorder, pleasant type'.","cn":"他想给“幸福”一个更为科学的新称谓，准确地说即“愉悦型重度情感障碍”。"}},{"pos":"","cn":"","en":"battle of wits→see: ;"}]},"examples":[{"en":"Pilot error, to wit failure to follow procedures, was the cause of the accident.","cn":"飞行员的失误，即没有遵守操作程序，是事故的原因。"},{"en":"a chance to pit your wits against (= compete with, using your intelligence) our quiz champion","cn":"利用你的智慧同我们的知识竞赛冠军进行较量的机会"}]},"wilderness":{"media":{"uk":"media/uk/wilderness__gb_1.mp3","us":"media/us/wilderness__us_1.mp3"},"oxford":{"phon":"ˈwɪldənəs","pos":"noun","senses":[{"en":"a large area of land that has never been developed or used for growing crops because it is difficult to live there","cn":"未开发的地区；荒无人烟的地区；荒野","lab":"North American English","ex":{"en":"The Antarctic is the world's last great wilderness.","cn":"南极洲是世界上最后一个大荒原。"}},{"en":"a place that people do not take care of or control","cn":"荒芜的地方；杂草丛生处","ex":{"en":"Their garden is a wilderness of grass and weeds.","cn":"他们的花园杂草丛生。"}},{"en":"a position that is no longer important, especially in politics","cn":"闲职；不再掌权","ex":{"en":"the man who brought the party back from the political wilderness","cn":"使该党重获执政地位的人"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"荒野;荒漠;原野","en":"A wilderness is a desert or other area of natural land which is not used by people.","ex":{"en":"...the icy Canadian wilderness","cn":"冰封的加拿大旷野"}},{"pos":"PHRASE 短语","cn":"在野;不掌权；不活跃；坐冷板凳","en":"If politicians or other well-known people spend time in the wilderness, they are not in an influential position or very active in their profession for that time.","ex":{"en":"...a party released from 12 years in the wilderness","cn":"摆脱了12年在野状态的政党"}}]},"examples":[{"en":"( NAmE ) a wilderness area (= one where it is not permitted to build houses or roads) （","cn":"政府划定的）保留自然环境面貌地区"},{"en":"The Antarctic is the world's last great wilderness.","cn":"南极洲是世界上最后一个大荒原。"}]},"within":{"media":{"uk":"media/uk/within__gb_1.mp3","us":"media/us/within__us_1.mp3"},"oxford":{"phon":"wɪˈðɪn","pos":"preposition","senses":[{"en":"before a particular period of time has passed; during a particular period of time","cn":"不出（某段时间）；在（某段时间）之内","ex":{"en":"You should receive a reply within seven days.","cn":"你会在七天之内收到答复。"}},{"en":"not further than a particular distance from something","cn":"不出（某段距离）；在（某段距离）之间","ex":{"en":"a house within a mile of the station","cn":"离车站不到一英里的一所房子"}},{"en":"inside the range or limits of something","cn":"不出（某范围或限度）；在（某范围）之内","ex":{"en":"That question is not within the scope of this talk.","cn":"那个问题不在本次会谈范围之内。"}},{"en":"inside something/somebody","cn":"在…里；在…内部","lab":"formal","ex":{"en":"The noise seems to be coming from within the building.","cn":"吵闹声像是从楼房里传出来的。"}},{"en":"inside","cn":"在里面；在内部","ex":{"en":"Cleaner required. Apply within. (= on a sign)","cn":"招聘清洁工。应聘者请进。"},"pos":"adverb"}]},"examples":[{"en":"Two elections were held within the space of a year.","cn":"在一年的时间之内举行了两次选举。"},{"en":"We are now within range of enemy fire.","cn":"我们现在处于敌人的火力射程以内。"}]},"will":{"media":{"uk":"media/uk/will__gb_1.mp3","us":"media/us/will__us_1.mp3"},"oxford":{"phon":"wɪl","pos":"verb","senses":[{"en":"to want or like","cn":"想要；希望；愿意；喜欢","ex":{"en":"Call it what you will, it's still a problem.","cn":"不管怎么说，这仍然是个问题。"}},{"en":"to use the power of your mind to do something or to make something happen","cn":"立定志向；决心；决意","ex":{"en":"As a child he had thought he could fly, if he willed it enough.","cn":"他小时候曾经以为，只要有足够的决心，想要飞就能飞起来。"}},{"en":"to intend or want something to happen","cn":"想要（某事发生）","lab":"old use","ex":{"en":"They thought they had been victorious in battle because God had willed it.","cn":"他们以为自己打了胜仗是上帝的旨意。"}},{"en":"to formally give your property or possessions to somebody after you have died, by means of a will","cn":"立遗嘱将（财产等）赠与（某人）；立遗嘱赠与","ex":{"en":"Joe had willed them everything he possessed.","cn":"乔把自己拥有的一切都遗赠给了他们。"}},{"en":"used for talking about or predicting the future","cn":"（谈及将来）","ex":{"en":"You'll be in time if you hurry.","cn":"你要是抓紧一点儿就会来得及。"},"pos":"modal verb"},{"en":"used for asking somebody to do something","cn":"（烦劳别人做事时用）","ex":{"en":"Will you send this letter for me, please?","cn":"请你替我把这封信寄出去行吗？"},"pos":"modal verb"},{"en":"used for inviting somebody to do something","cn":"（请别人做事时用）","ex":{"en":"Will you join us for lunch?","cn":"和我们一起吃午饭好吗？"},"pos":"modal verb"},{"en":"used for showing that somebody is willing to do something","cn":"（表示愿意）愿，要，会，定要","ex":{"en":"I'll check this letter for you, if you want.","cn":"你要是愿意，我会给你查查这封信的。"},"pos":"modal verb"},{"en":"used for ordering somebody to do something","cn":"（命令时用）","ex":{"en":"You'll do it this minute!","cn":"你现在就要做这事！"},"pos":"modal verb"},{"en":"used for stating what you think is probably true","cn":"（含有肯定的意思）","ex":{"en":"That'll be the doctor now.","cn":"这会儿准是医生来了。"},"pos":"modal verb"},{"en":"used for stating what is generally true","cn":"（叙述一般真理）","ex":{"en":"If it's made of wood it will float.","cn":"这要是木材做的就能浮在水面上。"},"pos":"modal verb"},{"en":"used for stating what is true or possible in a particular case","cn":"（叙述在某种情况下是真实或可能的事）","ex":{"en":"This jar will hold a kilo.","cn":"这个罐子能盛一千克。"},"pos":"modal verb"},{"en":"used for talking about habits","cn":"（谈及习惯）","ex":{"en":"She'll listen to music, alone in her room, for hours.","cn":"她总是独自一个人在屋里听音乐，一听就是几个小时。"},"pos":"modal verb"},{"en":"used in questions with I for making offers or suggestions","cn":"（用于带有 I 的问题中，表示主动提议或建议）","lab":"Irish English, New Zealand English，，","ex":{"en":"Will I call back later?","cn":"我回头再打电话好吗？"},"pos":"modal verb"},{"en":"the ability to control your thoughts and actions in order to achieve what you want to do; a strong and determined desire to do something that you want to do","cn":"意志；毅力；自制力","g":"[countable, uncountable]","ex":{"en":"to have a strong will","cn":"有坚强的意志"},"pos":"noun"},{"en":"what somebody wants to happen in a particular situation","cn":"意愿；心愿","g":"[singular]","lab":"formal","ex":{"en":"They governed according to the will of the people.","cn":"他们顺应民意执政。"},"pos":"noun"},{"en":"a legal document that says what is to happen to somebody’s money and property after they die","cn":"遗嘱","g":"[countable]","lab":"also formal","ex":{"en":"I ought to make a will.","cn":"我应该立份遗嘱。"},"pos":"noun"},{"en":"having the type of will mentioned","cn":"有…意志的；…毅力的","ex":{"en":"a strong-willed young woman","cn":"意志坚强的年轻女子"},"pos":"noun"},{"en":"a first name for boys, short for William","cn":"维尔（男子名，William 缩写）","pos":""}]},"collins":{"senses":[{"pos":"MODAL 情态动词","cn":"将;将会;将要","en":"You use will to indicate that you hope, think, or have evidence that something is going to happen or be the case in the future.","ex":{"en":"The Prime Minister is now 64 years old and in all probability this will be the last election that he is likely to contest","cn":"首相现年64岁，这多半将会是他可能参加的最后一次选举了。"}},{"pos":"MODAL 情态动词","cn":"(表示将来的正式安排)","en":"You use will in order to make statements about official arrangements in the future.","ex":{"en":"The show will be open to the public at 2pm; admission will be 50p","cn":"演出下午两点开始，入场费50便士。"}},{"pos":"MODAL 情态动词","cn":"(表示承诺或威胁)会，要","en":"You use will in order to make promises and threats about what is going to happen or be the case in the future.","ex":{"en":"I'll call you tonight","cn":"我晚上会给你打电话。"}},{"pos":"MODAL 情态动词","cn":"(指某人的打算)想要，将","en":"You use will to indicate someone's intention to do something.","ex":{"en":"I will say no more on these matters, important though they are","cn":"虽然这些事很重要，我也不想再说什么了。"}},{"pos":"MODAL 情态动词","cn":"(用于问句，表示礼貌地邀请或提议)愿否，…好吗","en":"You use will in questions in order to make polite invitations or offers.","ex":{"en":"Will you stay for supper?","cn":"你愿意留下吃晚饭吗？"}},{"pos":"MODAL 情态动词","cn":"(用于问句中，表示请求或让某人做某事)…好吗，…行吗","en":"You use will in questions in order to ask or tell someone to do something.","ex":{"en":"Will you drive me home?","cn":"你开车送我回家好吗？"}},{"pos":"MODAL 情态动词","cn":"(用于命令)","en":"You can use will in statements to give an order to someone.","ex":{"en":"You will do as I request, if you please","cn":"请按我的要求做。"}},{"pos":"MODAL 情态动词","cn":"愿意/不愿","en":"You use will to say that someone is willing to do something. You use will not or won't to indicate that someone refuses to do something.","ex":{"en":"All right, I'll forgive you","cn":"好吧，我愿意原谅你。"}},{"pos":"MODAL 情态动词","cn":"（表示将来能做某事）将,能","en":"You use will to say that a person or thing is able to do something in the future.","ex":{"en":"How the country will defend itself in the future has become increasingly important","cn":"国家将来如何能自卫已经变得越来越重要了。"}},{"pos":"MODAL 情态动词","cn":"(表示行为发生的经常性、习惯性)经常，惯于，总是","en":"You use will to indicate that an action usually happens in the particular way mentioned.","ex":{"en":"The thicker the material, the less susceptible the garment will be to wet conditions","cn":"布料越厚实，衣服就越不容易浸湿。"}},{"pos":"MODAL 情态动词","cn":"(用于含有 if 和 unless 的句子的主句中，表示非常可能发生)会，就","en":"You use will in the main clause of some 'if' and 'unless' sentences to indicate something that you consider to be fairly likely to happen.","ex":{"en":"If you overcook the pancakes they will be difficult to roll","cn":"如果薄饼烙久了，就很难卷起来。"}},{"pos":"MODAL 情态动词","cn":"一定要;非…不可","en":"You use will to say that someone insists on behaving or doing something in a particular way and you cannot change them. You emphasize will when you use it in this way.","ex":{"en":"He will leave his socks lying all over the place and it drives me mad.","cn":"他非要把袜子扔得到处都是，这简直要让我疯掉了。"}},{"pos":"MODAL 情态动词","cn":"(与过去分词连用，表示非常肯定将来会发生某事)定会","en":"You use will have with a past participle when you are saying that you are fairly certain that something will be true by a particular time in the future.","ex":{"en":"As many as ten-million children will have been infected with the virus by the end of the decade","cn":"到这个十年结束时，多达千万的儿童将会感染上这种病毒。"}},{"pos":"MODAL 情态动词","cn":"(与过去分词连用，表示相当肯定)会，将","en":"You use will have with a past participle to indicate that you are fairly sure that something is the case.","ex":{"en":"If someone has been in captivity for a long time, he will have changed as a result of his experience","cn":"如果某人遭到长时间囚禁，他会因为他的经历而有所改变。"}},{"pos":"N-VAR 可变名词","cn":"意志;决心","en":"Will is the determination to do something.","ex":{"en":"He was said to have lost his will to live.","cn":"据说他已经失去了生存的意志。"}},{"pos":"N-SING 单数名词","cn":"意愿;意志","en":"If something is the will of a person or group of people with authority, they want it to happen.","ex":{"en":"He has submitted himself to the will of God","cn":"他让自己听从上帝的意志。"}},{"pos":"VERB 动词","cn":"想要(某事发生)","en":"If you will something to happen, you try to make it happen by using mental effort rather than physical effort.","ex":{"en":"I looked at the telephone, willing it to ring","cn":"我看着电话，希望它响起来。"}},{"pos":"N-COUNT 可数名词","cn":"遗嘱","en":"A will is a document in which you declare what you want to happen to your money and property when you die.","ex":{"en":"Attached to his will was a letter he had written to his wife just days before his death.","cn":"和遗嘱附在一起的是一封他去世前几天写给妻子的信。"}},{"pos":"VERB 动词","cn":"将…遗赠","en":"If you will something to someone, you say in your will that they should have it when you die.","ex":{"en":"The large sum of money that came to him when she died was a shock, and he had not spent a penny of it on himself. He had, however, willed it to Frank.","cn":"她去世时他继承的那一大笔钱数额惊人，但他在自己身上未花分文，而是将其遗赠给了弗兰克。"}},{"pos":"PHRASE 短语","cn":"违背…的意志;违背…的愿望","en":"If something is done against your will, it is done even though you do not want it to be done.","ex":{"en":"No doubt he was forced to leave his family against his will.","cn":"无疑，他是不情愿地被迫离家的。"}},{"pos":"PHRASE 短语","cn":"任意;随意","en":"If you can do something at will, you can do it when you want and as much as you want.","ex":{"en":"...scientists who can adjust their experiments at will.","cn":"可以任意对实验进行调整的科学家"}},{"pos":"PHRASE 短语","cn":"热情地;劲头十足地","en":"If you do something with a will, you do it with a lot of enthusiasm and energy.","ex":{"en":"Set to work with a will and be pleased with the amount you get done","cn":"干活时卖力干，干了多少都满意。"}}]},"examples":[{"en":"As a child he had thought he could fly, if he willed it enough.","cn":"他小时候曾经以为，只要有足够决心，想要飞就能飞起来。"},{"en":"With the best will in the world I could not describe him as a good father.","cn":"尽管我心里极想美言几句，却怎么也不能说他是位好父亲。"}]},"wisely":{"oxford":{"phon":"ˈwaɪzli","pos":"adverb","senses":[{"en":"in a way that shows you have a lot of experience and knowledge","cn":"明智地：以某种方式表明您有很多经验和知识","ex":{"en":"She nodded wisely.","cn":"她睿智地点点头。"}},{"en":"in a way that shows you have good judgement","cn":"明智地：以某种方式表明您有良好的判断力","ex":{"en":"He wisely decided to tell the truth.","cn":"他明智地决定说出真相。"}}]},"media":{"uk":"media/uk/wisely__gb_1.mp3","us":"media/us/wisely__us_1.mp3"},"examples":[{"en":"He wisely decided to tell the truth.","cn":"他明智地决定实话实说。"},{"en":"She nodded wisely.","cn":"她聪明地点了点头。"}]},"wired":{"media":{"uk":"media/uk/wired__gb_1.mp3","us":"media/us/wired__us_1.mp3"},"oxford":{"phon":"ˈwaɪəd","pos":"adjective","senses":[{"en":"connected to a device or computer network by wires","cn":"（与设备或计算机系统）联网的，连线的","ex":{"en":"wired headphones/headsets","cn":"有线头戴式耳机"}},{"en":"containing wires that make it strong or stiff","cn":"（为使坚挺或坚固）内含金属丝的，夹丝的"},{"en":"excited or nervous; not relaxed","cn":"兴奋的；紧张不安的","lab":"informal"},{"en":"under the influence of alcohol or an illegal drug","cn":"（受酒精或毒品影响而）迷醉的","lab":"informal, especially North American English，，"},{"en":"a US magazine published every month in print and digital form containing news and opinions on computer technology. It reports on how technology and the internet affect culture, the economy and politics. It is published in San Francisco and was started in 1993. There is also a British edition, Wired UK and a website, which publishes blogs on a wide variety of technology-related topics.","cn":"有线：每个月以印刷和数字形式出版的美国杂志，其中包含有关计算机技术的新闻和观点。它报告了技术和互联网如何影响文化，经济和政治。它在旧金山出版，始于1993年。还有英国版Wired UK和一个网站，该网站发布有关各种与技术相关主题的博客。","pos":""}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"紧张的;不安的;神经紧绷的","en":"If someone is wired, they are tense, nervous, and unable to relax.","ex":{"en":"Tonight he is manic, wired and uptight.","cn":"今晚，他躁动不安，紧张兮兮的。"}},{"pos":"ADJ 形容词","cn":"联网的;有上网设备的","en":"A computer, organization, or person that is wired has the equipment that is necessary to use the Internet.","ex":{"en":"Once more people are wired, the potential to change the mainstream media will be huge.","cn":"一旦更多人能上网，网络改变主流媒体的潜力将十分巨大。"}},{"pos":"ADJ 形容词","cn":"(材料或衣服)内带金属丝的，夹丝的","en":"Wired is used to describe material or clothing that has wires sewn into it in order to keep it stiff.","ex":{"en":"...a length of wired ribbon.","cn":"一段夹丝的丝带"}}]},"examples":[{"en":"Many colleges now have wired dormitories.","cn":"现在许多大学的学生宿舍已经联网。"},{"en":"wired ribbon","cn":"夹丝丝带"}]},"wiry":{"media":{"uk":"media/uk/wiry__gb_1.mp3","us":"media/us/wiry__us_1.mp3"},"oxford":{"phon":"ˈwaɪəri","pos":"adjective","senses":[{"en":"thin but strong","cn":"瘦而结实的","ex":{"en":"a wiry little man","cn":"清瘦结实的小个男子"}},{"en":"stiff and strong; like wire","cn":"硬而结实的；像金属丝的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"瘦而结实的","en":"Someone who is wiry is rather thin but is also strong.","ex":{"en":"His body is wiry and athletic.","cn":"他长得清瘦而结实，体格健美。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（毛发、草等）粗硬的","en":"Something such as hair or grass that is wiry is stiff and rough to touch.","ex":{"en":"Her wiry hair was pushed up on top of her head in an untidy bun.","cn":"她粗硬的头发向上梳起，在头顶乱糟糟地盘成了个发髻。"}}]},"examples":[{"en":"a wiry little man","cn":"清瘦结实的小个男子"}]},"wire":{"oxford":{"phon":"ˈwaɪə(r)","pos":"noun","senses":[{"en":"metal in the form of thin thread; a piece of this","cn":"金属丝；金属线；一段金属丝（或线）","g":"[uncountable, countable]","ex":{"en":"a coil of copper wire","cn":"一卷铜丝"}},{"en":"a piece of wire that is used to carry an electric current or signal","cn":"电线；导线","g":"[countable, uncountable]","ex":{"en":"electrical wires","cn":"电线"}},{"en":"an electronic listening device that can be hidden on a person","cn":"（藏在身上的）窃听器","ex":{"en":"an undercover police informer who was wearing a wire","cn":"一名戴着电线的便衣警察线人"}},{"en":"a wire fence","cn":"金属丝编制的栅栏；铁丝网","g":"[singular]","ex":{"en":"Three prisoners escaped by crawling under the wire.","cn":"三个囚犯从铁丝网栅栏下钻出去越狱了。"}},{"en":"a telegram (= a message sent by telegraph and then printed and given to somebody)","cn":"给（某人）打电报","g":"[countable]","lab":"informal, especially North American English，，","ex":{"en":"We sent a wire asking him to join us.","cn":"我们给他发了一份电报请他加入我们的行列。"}},{"en":"to connect a building, piece of equipment, etc. to an electricity supply using wires","cn":"用导线给（建筑物、设备等）接通电源","ex":{"en":"Make sure the plug is wired up correctly.","cn":"插头一定要接对。"},"pos":"verb"},{"en":"to connect somebody/something to a piece of equipment","cn":"将…连接到（某设备）","ex":{"en":"In the test, volunteers were wired up to brain monitors.","cn":"在测试中，志愿参与者被连接到脑监测器上。"},"pos":"verb"},{"en":"to put a special device somewhere in order to listen secretly to other people’s conversations","cn":"给…安装窃听器","ex":{"en":"The room had been wired for sound.","cn":"这个房间已经装上了窃听器。"},"pos":"verb"},{"en":"to send somebody a message by telegram","cn":"给（某人）打电报","lab":"especially North American English","ex":{"en":"He wired the news to us.","cn":"他打电报把这个消息通知了我们。"},"pos":"verb"},{"en":"to send money from one bank to another using an electronic system","cn":"给（某人）电汇","ex":{"en":"The bank wired the money to her.","cn":"银行将钱电汇给了她。"},"pos":"verb"},{"en":"to join things together using wire","cn":"用金属丝把…连在一起","ex":{"en":"The components have to be wired together in a certain way.","cn":"这些元件必须以某种方式连接在一起。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"金属丝;金属线","en":"A wire is a long thin piece of metal that is used to fasten things or to carry electric current.","ex":{"en":"...fine copper wire.","cn":"细铜丝"}},{"pos":"N-COUNT 可数名词","cn":"电线;导线;电缆","en":"A wire is a cable which carries power or signals from one place to another.","ex":{"en":"I ripped out the telephone wire that ran through to his office.","cn":"我把通到他办公室的电话线拔掉了。"}},{"pos":"VERB 动词","cn":"在…里装电线;给…布线","en":"If you wire something such as a building or piece of equipment, you put wires inside it so that electricity or signals can pass into or through it.","ex":{"en":"...learning to wire and plumb the house herself","cn":"她学着自己给房子布线走管"}},{"pos":"N-COUNT 可数名词","cn":"同 telegram","en":"A wire is the same as a telegram ."},{"pos":"VERB 动词","cn":"给…发电报","en":"If you wire a person, you send them a telegram.","ex":{"en":"He wired the chairman immediately","cn":"他马上给主席发了电报。"}},{"pos":"VERB 动词","cn":"电汇(款)","en":"If you wire an amount of money to a person or place, you tell a bank to send it to the person or place using a telegram message.","ex":{"en":"I'm wiring you some money","cn":"我要给你汇些钱。"}},{"pos":"PHRASE 短语","cn":"到最后一刻","en":"If something goes to the wire, it continues until the last possible moment.","ex":{"en":"Negotiators again worked right down to the wire to reach an agreement.","cn":"谈判人员又是直到最后时刻才达成了协议。"}},{"pos":"","cn":"","en":"相关词组：wire up"}]},"media":{"uk":"media/uk/wire__gb_1.mp3","us":"media/us/wire__us_1.mp3"},"examples":[{"en":"We sent a wire asking him to join us.","cn":"我们给他发了一份电报请他加入我们的行列。"},{"en":"Three prisoners escaped by crawling under the wire.","cn":"三个囚犯从铁丝网栅栏下钻出去越狱了。"}]},"wintry":{"media":{"uk":"media/uk/wintry__gb_1.mp3","us":"media/us/wintry__us_1.mp3"},"oxford":{"phon":"ˈwɪntri","pos":"adjective","senses":[{"en":"typical of winter; cold","cn":"冬天的；冬令的；寒冷的","ex":{"en":"wintry weather","cn":"冬季的天气"}},{"en":"not friendly","cn":"冷漠的；冷冰冰的","ex":{"en":"a wintry smile","cn":"冷冷一笑"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冬天的;冬令的;寒冷的","en":"Wintry weather is cold and has features that are typical of winter.","ex":{"en":"Wintry weather continues to sweep across Britain","cn":"寒冷的天气继续席卷整个英国。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(态度或行为)冷冰冰的，冷淡的","en":"If you describe someone's attitude or behaviour as wintry, you mean that they seem very unfriendly.","ex":{"en":"He was, according to witnesses, extremely wintry with Her Royal Highness.","cn":"据目击者称，他对女王殿下极其冷淡。"}}]},"examples":[{"en":"wintry weather","cn":"冬季的天气"},{"en":"wintry showers (= of snow)","cn":"冬季的阵雪"}]},"willingly":{"oxford":{"phon":"ˈwɪlɪŋli","pos":"adverb","senses":[{"en":"in a way that shows you are happy or pleased to do something or that you do not object to doing something","cn":"愿意：以某种方式表明您对某件事感到高兴或高兴，或者您不反对做某事","ex":{"en":"People would willingly pay more for better services.","cn":"有好一些的服务，人们是愿意多花钱的。"}},{"en":"used to say that you are happy or pleased to do something","cn":"乐于：曾经说过您对某事感到高兴或高兴","ex":{"en":"‘Will you help me?’ ‘Willingly.’","cn":"“你愿意帮我个忙吗？”“当然愿意。”"}}]},"media":{"uk":"media/uk/willingly__gb_1.mp3","us":"media/us/willingly__us_1.mp3"},"examples":[{"en":"People would willingly pay more for better services.","cn":"有好一些的服务，人们是愿意多花钱的。"},{"en":"‘Will you help me?’ ‘Willingly.’ “","cn":"请帮帮我好吗？” “当然可以。”"}]},"wield":{"media":{"uk":"media/uk/wield__gb_1.mp3","us":"media/us/wield__us_1.mp3"},"oxford":{"phon":"wiːld","pos":"verb","senses":[{"en":"to have and use power, authority, etc.","cn":"拥有，运用，行使，支配（权力等）","ex":{"en":"She wields enormous power within the party.","cn":"她操纵着党内大权。"}},{"en":"to hold something, ready to use it as a weapon or tool","cn":"挥，操，使用（武器、工具等）","ex":{"en":"He was wielding a large knife.","cn":"他挥舞着一把大刀。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使用,挥,操（武器、工具等）","en":"If you wield a weapon, tool, or piece of equipment, you carry and use it.","ex":{"en":"...a lone assailant wielding a kitchen knife.","cn":"孤身一人、手持菜刀的袭击者"}},{"pos":"VERB 动词","cn":"掌握，运用，行使(权利)","en":"If someone wields power, they have it and are able to use it.","ex":{"en":"He remains chairman, but wields little power at the company.","cn":"他还是主席，但在公司没有什么实权了。"}}]},"examples":[{"en":"She wields enormous power within the party.","cn":"她操纵着党内大权。"},{"en":"He was wielding a large knife.","cn":"他挥舞着一把大刀。"}]},"wines":{"oxford":{"phon":"wɪn","pos":"verb","senses":[{"en":"to be the most successful in a competition, race, battle, etc. （","cn":"在比赛、赛跑、战斗等中）获胜，赢"},{"en":"to get sth as the result of a competition, race, election, etc. （","cn":"在比赛、赛跑、选举等中）赢得，夺取，获得，挣得"}]},"media":{"uk":"media/uk/win__gb_1.mp3","us":"media/us/win__us_1.mp3"}},"window":{"media":{"uk":"media/uk/window__gb_1.mp3","us":"media/us/window__us_1.mp3","img":["media/ldoce/img/window.jpg"]},"oxford":{"phon":"ˈwɪndəʊ","pos":"noun","senses":[{"en":"an opening in the wall or roof of a building, car, etc., usually covered with glass, that allows light and air to come in and people to see out; the glass in a window","cn":"窗；窗户；窗口；窗玻璃","ex":{"en":"She looked out of the window.","cn":"她向窗外看去。"}},{"en":"the glass at the front of a shop and the area behind it where goods are shown to the public","cn":"商店橱窗","ex":{"en":"I saw the dress I wanted in the window.","cn":"我在橱窗里看到了我想买的连衣裙。"}},{"en":"a small area of something that you can see through, for example to talk to somebody or read something on the other side","cn":"墙上（或信封等上）开的窗形的口；透明窗口","ex":{"en":"There was a long line of people at the box-office window.","cn":"在售票处窗口外排了一长队人。"}},{"en":"an area within a frame on a computer screen, in which a particular program is operating or in which information of a particular type is shown","cn":"（计算机屏幕的）窗口，视窗","lab":"computing","ex":{"en":"to create/open a window","cn":"新建／打开窗口"}},{"en":"a way of seeing and learning about something","cn":"了解信息的渠道；窗口","g":"[singular]","ex":{"en":"Television is a sort of window on the world.","cn":"电视是了解世界的窗口。"}},{"en":"a time when there is an opportunity to do something, although it may not last long","cn":"一丝机会；短暂的时机","ex":{"en":"We now have a small window of opportunity in which to make our views known.","cn":"我们现在有一线机会使人了解我们的观点。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"窗;窗户","en":"A window is a space in the wall of a building or in the side of a vehicle, which has glass in it so that light can come in and you can see out.","ex":{"en":"He stood at the window, moodily staring out","cn":"他站在窗前，忧郁地凝视着外面。"}},{"pos":"N-COUNT 可数名词","cn":"(商店的)玻璃橱窗，陈列窗","en":"A window is a large piece of glass along the front of a shop, behind which some of the goods that the shop sells are displayed.","ex":{"en":"I stood for a few moments in front of the nearest shop window.","cn":"我在最近的一家商店的橱窗前站了一会儿。"}},{"pos":"N-COUNT 可数名词","cn":"(银行、邮局、火车站、博物馆等处柜台的)窗口","en":"A window is a glass-covered opening above a counter, for example in a bank, post office, railway station, or museum, which the person serving you sits behind.","ex":{"en":"The woman at the ticket window told me that the admission fee was $17.50.","cn":"售票窗口那个女的告诉我入场费是17.50美元。"}},{"pos":"N-COUNT 可数名词","cn":"窗口;视窗","en":"On a computer screen, a window is one of the work areas that the screen can be divided into."},{"pos":"N-COUNT 可数名词","cn":"(日程安排等中的)空当，空隙","en":"If you have a window in your diary for something, or if you can make a window for it, you are free at a particular time and can do it then.","ex":{"en":"Tell her I've got a window in my diary later on this week.","cn":"告诉她我这周晚些时候有空儿。"}},{"pos":"PHRASE 短语","cn":"消失殆尽;烟消云散;化为乌有","en":"If you say that something such as a plan or a particular way of thinking or behaving has gone out of the window or has flown out of the window, you mean that it has disappeared completely.","ex":{"en":"By now all logic had gone out of the window","cn":"到这时根本就不讲什么逻辑了。"}},{"pos":"PHRASE 短语","cn":"转瞬即逝的机会;稍纵即逝的机会","en":"If you say that there is a window of opportunity for something, you mean that there is an opportunity to do something but that this opportunity will only last for a short time and so it needs to be taken advantage of quickly.","ex":{"en":"The king said there was now a window of opportunity for peace.","cn":"国王说现在有寻求和平的短暂机会。"}}]},"examples":[{"en":"It gave me an intriguing window into the way people live.","cn":"这为我提供了一个了解人们的生活方式的有趣窗口。"},{"en":"We now have a small window of opportunity in which to make our views known.","cn":"我们现在有一线机会使人了解我们的观点。"}]},"winner":{"oxford":{"phon":"ˈwɪnə(r)","pos":"noun","senses":[{"en":"a person, a team, an animal, etc. that wins something","cn":"获胜的人（或队、动物等）；优胜者","ex":{"en":"The lucky winner gets an all-expenses-paid trip to Sydney.","cn":"幸运的优胜者可获得一次悉尼全免费游。"}},{"en":"a thing or person that is successful or likely to be successful","cn":"成功者；可能成功的人（或事物）","g":"[usually singular]","lab":"informal","ex":{"en":"I think your idea is a winner.","cn":"我认为你的想法能够成功。"}},{"en":"a goal or point that causes a team or a person to win a game","cn":"制胜的一记入球；赢得比赛的一分","g":"[singular]","lab":"sport","ex":{"en":"Morgan scored the winner after 20 minutes.","cn":"摩根在 20 分钟后射入了制胜的一球。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"获胜者;优胜者","en":"The winner of a prize, race, or competition is the person, animal, or thing that wins it.","ex":{"en":"She will present the trophies to the award winners","cn":"她将给获奖者颁奖。"}},{"pos":"N-COUNT 可数名词","cn":"成功者;可能成功的人(或事物)","en":"If you say that something or someone is a winner, you mean that they are popular and successful, or that they are likely to be popular and successful.","ex":{"en":"They think the appeal is a winner","cn":"他们认为上诉能够成功。"}},{"pos":"N-COUNT 可数名词","cn":"获益者;得利者;赢家","en":"The winners in a particular situation are the people who have benefited from it and are in a better position than they previously were because of it.","ex":{"en":"There are clear winners when a dam is built. Farmers get irrigation water, businesses get electricity","cn":"大坝若是建成，会有一些明显的受益者：农民将得到灌溉用水，企业将得到电力。"}},{"pos":"N-SING 单数名词","cn":"(足球、网球等比赛中的)制胜球","en":"In games such as football or tennis, the winner is the goal or shot that wins a particular match or point.","ex":{"en":"Gough scored the winner in extra time.","cn":"高夫在加时赛中攻入制胜球。"}}]},"media":{"uk":"media/uk/winner__gb_1.mp3","us":"media/us/winner__us_1.mp3"},"examples":[{"en":"Rooney scored the winner after 20 minutes","cn":"鲁尼在 20 分钟后射入了致胜的一球。"},{"en":"The design is very good. We could be onto a winner (= we may do or produce sth successful).","cn":"这设计很好。我们的产品可能会成功。"}]},"wine":{"media":{"uk":"media/uk/wine__gb_1.mp3","us":"media/us/wine__us_1.mp3"},"oxford":{"phon":"waɪn","pos":"noun","senses":[{"en":"an alcoholic drink made from the juice of grapes that has been left to ferment. There are many different kinds of wine.","cn":"葡萄酒","g":"[uncountable, countable]","ex":{"en":"sparkling wine","cn":"汽酒"}},{"en":"an alcoholic drink made from plants or fruits other than grapes","cn":"（用植物或除葡萄以外的水果酿制的）酒，果酒","g":"[uncountable, countable]","ex":{"en":"elderberry/rice wine","cn":"接骨木果酒；米酒"}},{"en":"a dark red colour","cn":"紫红色；深红色","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"葡萄酒;果蔬酒","en":"Wine is an alcoholic drink which is made from grapes. You can also refer to alcoholic drinks made from other fruits or vegetables as wine .","ex":{"en":"...a bottle of white wine","cn":"一瓶白葡萄酒"}},{"pos":"COLOUR 颜色词","cn":"深红色;紫红色;酒红色","en":"Wine is used to describe things that are very dark red in colour.","ex":{"en":"She wore her wine-coloured gaberdine raincoat.","cn":"她穿着深红色华达呢雨衣。"}},{"pos":"PHR-ERG","cn":"大吃大喝；盛宴款待","en":"If you wine and dine, or if someone wines and dines you, you go out, for example to expensive restaurants, and spend a lot of money.","ex":{"en":"Colleagues were furious at doing her work while she wined and dined","cn":"同事们干着她的活儿，而她却在外面大吃大喝，这让大家都气坏了。"}}]},"examples":[{"en":"The firm spent thousands wining and dining potential clients.","cn":"这家公司成千上万地花费在大摆酒宴款待潜在的客户上。"},{"en":"red/rosé/white wine","cn":"红/玫瑰红/白葡萄酒"}]},"wife":{"media":{"uk":"media/uk/wife__gb_1.mp3","us":"media/us/wife__us_1.mp3"},"oxford":{"phon":"waɪf","pos":"noun","senses":[{"en":"the woman that somebody is married to; a married woman","cn":"妻子","lab":"especially North American English","ex":{"en":"I met my wife at university.","cn":"我和妻子是上大学时认识的。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"妻子；太太；夫人","en":"A man's wife is the woman he is married to.","ex":{"en":"He married his wife Jane 37 years ago","cn":"他37年前娶了妻子简。"}}]},"examples":[{"en":"an increase in the number of working wives","cn":"已婚职业妇女人数的增加"},{"en":"She's his second wife.","cn":"她是他的第二个妻子。"}]},"wish":{"media":{"uk":"media/uk/wish__gb_1.mp3","us":"media/us/wish__us_1.mp3"},"oxford":{"phon":"wɪʃ","pos":"verb","senses":[{"en":"to want something to happen or to be true even though it is unlikely or impossible","cn":"希望（不大可能的事）发生；怀着（不可能实现的）愿望","g":"[transitive]","lab":"British English also","ex":{"en":"I wish I were taller.","cn":"我要是个子高一些就好了。"}},{"en":"to want to do something; to want something to happen","cn":"希望（做某事）；想要（某事发生）","g":"[intransitive, transitive]","lab":"especially British English, formal，，","ex":{"en":"You may stay until morning, if you wish.","cn":"如果你愿意，你可以一直待到早晨。"}},{"en":"to think very hard that you want something, especially something that can only be achieved by good luck or magic","cn":"盼望；企求；想要","g":"[intransitive]","ex":{"en":"If you wish really hard, maybe you'll get what you want.","cn":"心诚则灵。"}},{"en":"to say that you hope that somebody will be happy, lucky, etc.","cn":"祝；祝愿","g":"[transitive]","ex":{"en":"I wished her a happy birthday.","cn":"我祝她生日快乐。"}},{"en":"used especially in a letter, email or card to say that you hope that somebody will be happy, well or successful","cn":"（书信、电邮或贺卡等中的）祝愿，祝福","g":"[plural]","ex":{"en":"Give my good wishes to the family.","cn":"请替我向全家致意。"},"pos":"noun"},{"en":"an attempt to make something happen by thinking hard about it, especially in stories when it often happens by magic","cn":"愿；心愿","g":"[countable]","ex":{"en":"Throw some money in the fountain and make a wish.","cn":"往喷泉里扔些钱，许个愿。"},"pos":"noun"},{"en":"a desire or a feeling that you want to do something or have something","cn":"愿望；希望","g":"[countable]","ex":{"en":"She expressed a wish to be alone.","cn":"她表示希望一个人待着。"},"pos":"noun"},{"en":"a thing that you want to have or to happen","cn":"想要的东西；希望的事","g":"[countable]","ex":{"en":"He refused to carry out her wishes.","cn":"他拒绝按她的意愿行事。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"愿望;希望","en":"A wish is a desire or strong feeling that you want to have something or do something.","ex":{"en":"She was sincere and genuine in her wish to make amends for the past","cn":"她真诚地希望弥补从前的过失。"}},{"pos":"VERB 动词","cn":"想要，希望(做…)","en":"If you wish to do something or to have it done for you, you want to do it or have it done.","ex":{"en":"If you wish to go away for the weekend, our office will be delighted to make hotel reservations","cn":"如果您想外出度周末，我们办事处将很乐意为您预订旅馆。"}},{"pos":"VERB 动词","cn":"(用于要说的话可能使人不快或担心等时)不想，无意","en":"Wish is used in expressions such as I don't wish to be rude or without wishing to be rude as a way of apologizing or warning someone when you are going to say something which might upset, annoy, or worry them.","ex":{"en":"I don't wish to sound callous, but I am glad I wasn't here","cn":"我不想让自己的话听上去麻木不仁，但我真的很庆幸我当时没在这儿。"}},{"pos":"VERB 动词","cn":"希望(不可能或可能性很小的事发生)","en":"If you wish something were true, you would like it to be true, even though you know that it is impossible or unlikely.","ex":{"en":"I wish I could do that","cn":"我希望我能做那件事。"}},{"pos":"VERB 动词","cn":"祈求;企求;默默期盼","en":"If you wish for something, you express the desire for that thing silently to yourself. In fairy stories, when a person wishes for something, the thing they wish for often happens by magic.","ex":{"en":"We have all wished for men who are more considerate","cn":"我们都曾祈求能找到更加体贴的男人。"}},{"pos":"VERB 动词","cn":"这是再好不过的;没有比这更好的了","en":"Wish is used in sentences such as I could not wish for anything better to indicate that you are very pleased with what you have and could not imagine anything better.","ex":{"en":"I really could not have wished for a better teacher","cn":"这个老师对我来说是再好不过的了。"}},{"pos":"VERB 动词","cn":"希望…发生在…身上","en":"If you say that you would not wish a particular thing on someone, you mean that the thing is so unpleasant that you would not want them to be forced to experience it.","ex":{"en":"It's a horrid experience and I wouldn't wish it on my worst enemy.","cn":"这种经历太痛苦了，我甚至都不希望它发生在死对头身上。"}},{"pos":"VERB 动词","cn":"祝;祝愿","en":"If you wish someone something such as luck or happiness, you express the hope that they will be lucky or happy.","ex":{"en":"I wish you both a very good journey","cn":"我祝愿你们两人旅途愉快。"}},{"pos":"N-PLURAL 复数名词","cn":"祝愿;祝福","en":"If you express your good wishes towards someone, you are politely expressing your friendly feelings towards them and your hope that they will be successful or happy.","ex":{"en":"I found George's story very sad. Please give him my best wishes","cn":"我觉得乔治的经历很悲惨，请向他转达我最诚挚的祝福。"}}]},"examples":[{"en":"‘Where is he now?’ ‘ I only wish I knew!’ “","cn":"他现在在哪儿？” “我要是知道就好了！”"},{"en":"‘I'd rather not talk now.’ ‘ (Just) as you wish. ’ “","cn":"现在我最好还是不说话。” “悉听尊便。”"}]},"wildlife":{"media":{"uk":"media/uk/wildlife__gb_1.mp3","us":"media/us/wildlife__us_1.mp3"},"oxford":{"phon":"ˈwaɪldlaɪf","pos":"noun","senses":[{"en":"animals, birds, insects, etc. that are wild and live in a natural environment","cn":"野生动物","ex":{"en":"policies designed to protect wildlife","cn":"为保护野生动物制定的政策"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"野生动物;野生物种","en":"You can use wildlife to refer to the animals and other living things that live in the wild.","ex":{"en":"People were concerned that pets or wildlife could be affected by the pesticides.","cn":"人们担心宠物或野生动物可能受到杀虫剂影响。"}}]},"examples":[{"en":"Development of the area would endanger wildlife.","cn":"开发这一地区将会危及到野生生物。"},{"en":"a wildlife habitat/sanctuary","cn":"野生动物栖息地/保护区"}]},"wireless":{"media":{"uk":"media/uk/wireless__gb_1.mp3","us":"media/us/wireless__us_1.mp3"},"oxford":{"phon":"ˈwaɪələs","pos":"noun","senses":[{"en":"any system of sending electronic information, such as the internet, phone signals, etc. without using wires for the receiving equipment","cn":"无线电发射和接收系统（如互联网、手机信号等）；无线电报","g":"[uncountable]","ex":{"en":"a message sent by wireless","cn":"用无线电报发出的信息"}},{"en":"a radio","cn":"无线电收音机","g":"[countable]","lab":"especially British English, old-fashioned，，","ex":{"en":"I heard it on the wireless.","cn":"我是从无线电收音机里听到的。"}},{"en":"not using wires","cn":"无线的","ex":{"en":"wireless communications","cn":"无线通信"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无线的;用无线电波传送的","en":"Wireless technology uses radio waves rather than electricity and therefore does not require any wires.","ex":{"en":"...the fast-growing wireless communication market.","cn":"迅速扩张的无线通讯市场"}},{"pos":"N-UNCOUNT 不可数名词","cn":"无线电;无线电收发系统","en":"Wireless is a system by which messages are sent over a distance by radio signals.","ex":{"en":"...the development of wireless and radar","cn":"无线电与雷达的发展"}},{"pos":"N-COUNT 可数名词","cn":"无线电收音机","en":"A wireless or wireless set is a radio."}]},"examples":[{"en":"I heard it on the wireless.","cn":"我是从无线电收音机里听到的。"},{"en":"a message sent by wireless","cn":"用无线电报发出的信息"}]},"widow":{"media":{"uk":"media/uk/widow__gb_1.mp3","us":"media/us/widow__us_1.mp3"},"oxford":{"phon":"ˈwɪdəʊ","pos":"noun","senses":[{"en":"a woman whose husband or wife has died and who has not married again","cn":"寡妇；遗孀","ex":{"en":"She gets a widow’s pension.","cn":"她领取寡妇抚恤金。"}},{"en":"if somebody is widowed, their husband or wife has died","cn":"使丧偶；使成为寡妇（或鳏夫）","ex":{"en":"She was widowed when she was 35.","cn":"她 35 岁时就守了寡。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"寡妇;遗孀","en":"A widow is a woman whose husband has died and who has not married again."}]},"examples":[{"en":"She was widowed when she was 35.","cn":"她 35 岁时就守了寡。"},{"en":"his widowed father","cn":"他鳏居的父亲"}]},"windmill":{"media":{"uk":"media/uk/windmill__gb_1.mp3","us":"media/us/windmill__us_1.mp3","img":["media/ldoce/img/windmill.jpg"]},"oxford":{"phon":"ˈwɪndmɪl","pos":"noun","senses":[{"en":"a building with equipment for grinding grain into flour that is driven by the power of the wind turning long arms (called sails)","cn":"风车磨房"},{"en":"a tall, thin structure with parts that turn round, used to change the power of the wind into electricity","cn":"（通过转动将风能转化为电能的）风车"},{"en":"a toy with curved plastic parts that form the shape of a flower that turns round on the end of a stick when you blow on it","cn":"玩具风车","lab":"British English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"风车磨坊；（风力发电的）风车","en":"A windmill is a building with long pieces of wood on the outside which turn around as the wind blows and provide energy for a machine that crushes grain. A windmill is also a similar structure that is used to convert the power of the wind into electricity."}]}},"wildly":{"media":{"uk":"media/uk/wildly__gb_1.mp3","us":"media/us/wildly__us_1.mp3"},"oxford":{"phon":"ˈwaɪldli","pos":"adverb","senses":[{"en":"in a way that is not controlled","cn":"失控地；紊乱地","ex":{"en":"She looked wildly around for an escape.","cn":"她环顾四周，拼命寻找逃路。"}},{"en":"extremely; very","cn":"极其；非常","ex":{"en":"The story had been wildly exaggerated.","cn":"这件事被过分地夸大了。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"非常;极其","en":"You use wildly to emphasize the degree, amount, or intensity of something.","ex":{"en":"Reports of his drinking have been wildly exaggerated","cn":"有关他酗酒的报道极尽夸张。"}}]},"examples":[{"en":"She looked wildly around for an escape.","cn":"她环顾四周，拼命寻找逃路。"},{"en":"It is not a wildly funny play.","cn":"这并不是一出太滑稽的戏剧。"}]},"winter":{"media":{"uk":"media/uk/winter__gb_1.mp3","us":"media/us/winter__us_1.mp3"},"oxford":{"phon":"ˈwɪntə(r)","pos":"noun","senses":[{"en":"the coldest season of the year, between autumn and spring","cn":"冬天；冬季","ex":{"en":"a cold/mild/harsh winter","cn":"寒冬；暖冬；严冬"}},{"en":"to spend the winter somewhere","cn":"过冬","ex":{"en":"Many British birds winter in Africa.","cn":"许多英国的鸟在非洲过冬。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"冬天;冬季","en":"Winter is the season between autumn and spring. In the winter the weather is usually cold.","ex":{"en":"In winter the nights are long and cold.","cn":"冬夜漫长而寒冷。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）(动植物)过冬","en":"If an animal or plant winters somewhere or is wintered there, it spends the winter there.","ex":{"en":"The birds will winter outside in an aviary","cn":"鸟儿们将在外面的大鸟笼里过冬。"}},{"pos":"VERB 动词","cn":"(人)过冬","en":"If you winter somewhere, you spend the winter there.","ex":{"en":"The family decided to winter in Nice again.","cn":"一家人决定还是到尼斯过冬。"}}]},"examples":[{"en":"Our house can be very cold in (the) winter.","cn":"我们的房子到了冬天有时会非常冷。"},{"en":"They worked on the building all through the winter.","cn":"他们整个冬天都在建这座大楼。"}]},"wires":{"oxford":{"phon":"ˈwaɪə(r)","pos":"noun","senses":[{"en":"metal in the form of thin thread; a piece of this","cn":"金属丝；金属线；一段金属丝（或线）"},{"en":"a piece of wire that is used to carry an electric current or signal","cn":"电线；导线"}]}},"willful":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/uk/willful__gb_1.mp3","us":"media/us/willful__us_1.mp3"},"oxford":{"phon":"ˈwɪlfl","pos":"adjective","senses":[{"en":"done deliberately, although the person doing it knows that it is wrong","cn":"故意的；有意的；成心的","g":"[usually before noun]","lab":"formal, disapproving or law，，","ex":{"en":"willful damage","cn":"故意损坏"}},{"en":"determined to do what you want; not caring about what other people want","cn":"任性的；固执的；倔强的","ex":{"en":"a willful child","cn":"任性的孩子"}}]}},"wicker":{"oxford":{"phon":"ˈwɪkə(r)","pos":"noun","senses":[{"en":"thin sticks of wood twisted together to make baskets, furniture, etc.","cn":"（编制筐篮、家具等用的）柳条，枝条","ex":{"en":"a wicker chair","cn":"柳条椅"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(编制篮子、家具等的)柳条，枝条","en":"Wicker is long thin sticks, stems, or reeds that have been woven together to make things such as baskets and furniture.","ex":{"en":"...a wicker basket.","cn":"柳条编成的篮子"}}]},"media":{"uk":"media/uk/wicker__gb_1.mp3","us":"media/us/wicker__us_1.mp3","img":["media/ldoce/img/wicker_basket.jpg"]},"examples":[{"en":"a wicker chair","cn":"柳条椅"},{"en":"a wicker basket","cn":"柳条筐"}]},"witty":{"oxford":{"phon":"ˈwɪti","pos":"adjective","senses":[{"en":"clever and humorous","cn":"诙谐的；巧妙的；妙趣横生的；机智的","ex":{"en":"He was much in demand as a witty public speaker.","cn":"作为一个机智幽默的演说家，他非常抢手。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"机智幽默的;妙趣横生的;诙谐的","en":"Someone or something that is witty is amusing in a clever way.","ex":{"en":"His plays were very good, very witty","cn":"他的剧作非常精彩，妙趣横生。"}}]},"media":{"uk":"media/uk/witty__gb_1.mp3","us":"media/us/witty__us_1.mp3"},"examples":[{"en":"a witty speaker","cn":"幽默的演讲人"},{"en":"a witty remark","cn":"机智的话"}]},"wives":{"media":{"uk":"media/uk/wives__gb_1.mp3","us":"media/us/wives__us_1.mp3"},"collins":{"senses":[{"pos":"","cn":"（wife的复数）","en":"Wives is the plural of wife ."}]}},"widely":{"media":{"uk":"media/uk/widely__gb_1.mp3","us":"media/us/widely__us_1.mp3"},"oxford":{"phon":"ˈwaɪdli","pos":"adverb","senses":[{"en":"by a lot of people; in or to many places","cn":"普遍地；广泛地；范围广地","ex":{"en":"The term is widely used in everyday speech.","cn":"这个词在日常口语中使用广泛。"}},{"en":"to a large degree; a lot","cn":"很大程度上；大大地","ex":{"en":"Standards vary widely.","cn":"程度参差不齐。"}}]},"examples":[{"en":"The idea is now widely accepted.","cn":"这个思想现在已获得普遍接受。"},{"en":"He's an educated, widely-read man (= he has read a lot of books).","cn":"他这个人有教养，博览群书。"}]},"wild":{"media":{"uk":"media/uk/wild__gb_1.mp3","us":"media/us/wild__us_1.mp3"},"oxford":{"phon":"waɪld","pos":"adjective","senses":[{"en":"living or growing in natural conditions; not kept in a house or on a farm","cn":"自然生长的；野的；野生的","sc":"animals/plants","ex":{"en":"wild animals/birds/flowers","cn":"野生动物／鸟类；野花"}},{"en":"in its natural state; not changed by people","cn":"天然的；荒凉的；荒芜的","sc":"scenery/land","ex":{"en":"the destruction of forests and other wild lands","cn":"对森林和其他荒野地带的破坏"}},{"en":"having no discipline or control","cn":"缺乏管教的；无法无天的；放荡的","sc":"out of control","ex":{"en":"The boy is wild and completely out of control.","cn":"这男孩缺乏管教，简直是无法无天。"}},{"en":"full of very strong feeling","cn":"感情炽烈的","sc":"feelings","ex":{"en":"The crowd went wild.","cn":"群情激昂。"}},{"en":"not carefully planned; not sensible or accurate","cn":"盲目的；瞎抓的","sc":"not sensible","ex":{"en":"He made a wild guess at the answer.","cn":"他胡乱猜了个答案。"}},{"en":"very good, pleasant or exciting","cn":"很棒的；高兴的；令人激动的","lab":"informal","sc":"exciting","ex":{"en":"We had a wild time in New York.","cn":"我们在纽约玩得痛快极了。"}},{"en":"very enthusiastic about somebody/something","cn":"热衷于…；狂热","lab":"informal","sc":"enthusiastic","ex":{"en":"She's totally wild about him.","cn":"她对他简直是着了迷。"}},{"en":"affected by storms and strong winds","cn":"狂暴的；暴风雨的","sc":"weather/sea","ex":{"en":"a wild night","cn":"暴风雨之夜"}},{"en":"a natural environment that is not controlled by people","cn":"自然环境；野生状态","g":"[singular]","ex":{"en":"The bird is too tame now to survive in the wild.","cn":"这只鸟养得太温驯了，现在很难在野生环境中生存。"},"pos":"noun"},{"en":"areas of a country far from towns or cities, where few people live","cn":"偏远地区；人烟稀少的地区","g":"[plural]","lab":"humorous","ex":{"en":"wandering through the wilds of Alaska","cn":"漫步在阿拉斯加的荒野"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（动植物）自然生长的，野生的，野的","en":"Wild animals or plants live or grow in natural surroundings and are not looked after by people.","ex":{"en":"We saw two more wild cats creeping towards us in the darkness","cn":"我们看见又有两只野猫在黑暗中悄悄向我们靠近。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（土地）天然的，荒芜的，荒凉的","en":"Wild land is natural and is not used by people.","ex":{"en":"Elmley is one of the few wild areas remaining in the South East.","cn":"埃尔姆利是东南部仅存的几块荒地之一。"}},{"pos":"N-PLURAL 复数名词","cn":"荒野;远离城镇的地区","en":"The wilds of a place are the natural areas that are far away from towns.","ex":{"en":"They went canoeing in the wilds of Canada.","cn":"他们到加拿大的荒野之地去划独木舟。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有暴风雨的;多风暴的;狂风暴雨的","en":"Wild is used to describe the weather or the sea when it is stormy.","ex":{"en":"The wild weather did not deter some people from swimming in the sea.","cn":"尽管风雨交加，一些人还是会下海游泳。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"疯狂的;狂热的","en":"Wild behaviour is uncontrolled, excited, or energetic.","ex":{"en":"The children are wild with joy","cn":"孩子们欣喜若狂。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难以约束的;不受控制的;放荡的;无节制的","en":"If you describe someone or their behaviour as wild, you mean that they behave in a very uncontrolled way.","ex":{"en":"When angry or excited, however, he could be wild, profane, and terrifying","cn":"但愤怒或激动的时候，他也会发狂、会骂人、令人生畏。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愤怒的;狂怒的","en":"If someone is wild, they are very angry.","ex":{"en":"For a long time I daren't tell him I knew, and when I did he went wild.","cn":"很长时间我都不敢告诉他我知道了，但当我告诉他时，他简直气疯了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(因恐惧、愤怒或精神失常而)双目圆睁的，眼睛瞪大的","en":"If you say that someone has wild eyes or a wild look, you mean that their eyes are wide open and staring because they are frightened, angry, or insane.","ex":{"en":"She could see his face now, his eyes wild and his skin glistening with perspiration","cn":"她现在可以看见他的脸了，他的眼睛瞪得溜圆，皮肤上闪着汗水。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（想法）非同寻常的，极端的;(猜测)未经思索的，胡乱的","en":"A wild idea is unusual or extreme. A wild guess is one that you make without much thought.","ex":{"en":"I was just a kid and full of all sorts of wild ideas","cn":"我不过是个孩子，充满各种奇异的想法。"}},{"pos":"PHRASE 短语","cn":"狂热地迷恋;极为喜欢","en":"If you are wild about someone or something, you like them very much.","ex":{"en":"I'm just wild about Peter, and he's just wild about me","cn":"我为彼得疯狂，他对我也一样。"}},{"pos":"PHRASE 短语","cn":"在自然环境中；处于野生状态","en":"Animals that live in the wild live in a free and natural state and are not looked after by people.","ex":{"en":"Fewer than a thousand giant pandas still live in the wild.","cn":"只有不到1,000只大熊猫仍然在野外生活。"}},{"pos":"PHRASE 短语","cn":"（事物）疯狂发展；（尤指小孩）恣意妄为，失去控制","en":"If something or someone, especially a child, runs wild, they behave in a natural, free, or uncontrolled way.","ex":{"en":"Everything that could grow was running wild for lack of attention","cn":"凡是能长的都因为缺乏照管而疯长一气。"}},{"pos":"","cn":"","en":"beyond your wildest dreams→see: ; in your wildest dreams→see: ; to sow your wild oats→see: ;"}]},"examples":[{"en":"The bird is too tame now to survive in the wild.","cn":"这只鸟养得太温驯了，现在很难在野生环境中生存。"},{"en":"The boy is wild and completely out of control.","cn":"这男孩缺乏管教，简直是完全失控。"}]},"widowed":{"collins":{"senses":[{"pos":"V-PASSIVE 被动动词","cn":"使丧偶","en":"If someone is widowed, their husband or wife dies.","ex":{"en":"More and more young men are widowed by cancer","cn":"越来越多的青年男子被癌症夺去了妻子。"}}]},"media":{"uk":"media/uk/widowed__gb_1.mp3","us":"media/us/widowed__us_1.mp3"},"examples":[{"en":"his widowed father","cn":"他鳏居的父亲"},{"en":"She was widowed at the age of 25.","cn":"她25岁时成了寡妇。"}],"oxford":{"phon":"ˈwɪdəʊd","pos":"adjective","senses":[{"en":"used to describe somebody whose husband or wife has died and who has not married again","cn":"寡妇；遗孀","ex":{"en":"his widowed father","cn":"他鳏居的父亲"}}]}},"with":{"media":{"uk":"media/uk/with__gb_1.mp3","us":"media/us/with__us_1.mp3"},"oxford":{"phon":"wɪð","pos":"preposition","senses":[{"en":"in the company or presence of somebody/something","cn":"和…在一起；和；同；跟","ex":{"en":"She lives with her parents.","cn":"她同父母住在一起。"}},{"en":"having or carrying something","cn":"有；具有；带有","ex":{"en":"a girl with (= who has) red hair","cn":"一位红发女郎"}},{"en":"using something","cn":"用；使用；以；借","ex":{"en":"Cut it with a knife.","cn":"用刀把它切开。"}},{"en":"used to say what fills, covers, etc. something","cn":"（表示以某物填充、覆盖等）","ex":{"en":"The bag was stuffed with dirty clothes.","cn":"袋子里塞满了脏衣服。"}},{"en":"in opposition to somebody/something; against somebody/something","cn":"与…对立；反对","ex":{"en":"to fight with somebody","cn":"与某人打架"}},{"en":"in connection with; in the case of","cn":"关于；对于；对…来说","ex":{"en":"Be careful with the glasses.","cn":"小心这些玻璃杯。"}},{"en":"used to show the way in which somebody does something","cn":"（表示行为方式）","ex":{"en":"He behaved with great dignity.","cn":"他举止庄重威严。"}},{"en":"used when considering one fact in relation to another","cn":"（涉及一事与另一事的关系）","ex":{"en":"She won't be able to help us with all the family commitments she has.","cn":"她有这么多家务事，帮不了我们。"}},{"en":"including","cn":"包括；还有","ex":{"en":"The meal with wine came to $20 each.","cn":"包括酒这顿饭每人 20 美元。"}},{"en":"used to show who has possession of or responsibility for something","cn":"由…持有；由…负责","ex":{"en":"The keys are with reception.","cn":"钥匙在服务台。"}},{"en":"employed by; using the services of","cn":"为…工作；受雇于；利用…的服务","ex":{"en":"She acted with a touring company for three years.","cn":"她在一个巡回剧团里演出了三年。"}},{"en":"because of; as a result of","cn":"因为；由于；作为…的结果","ex":{"en":"She blushed with embarrassment.","cn":"她难为情得脸红了。"}},{"en":"because of something and as it happens","cn":"由于；随着","ex":{"en":"The shadows lengthened with the approach of sunset.","cn":"随着太阳西沉，影子越来越长。"}},{"en":"in the same direction as something","cn":"与…方向一致；顺着","ex":{"en":"Marine mammals generally swim with the current.","cn":"海洋哺乳动物一般顺水而游。"}},{"en":"showing that something/somebody has been separated from something/somebody","cn":"（表示分离）","ex":{"en":"I could never part with this ring.","cn":"我永远也不摘掉这枚戒指。"}},{"en":"despite something","cn":"虽然；尽管","ex":{"en":"With all her faults I still love her.","cn":"尽管她有种种缺点，我依然爱着她。"}},{"en":"used in exclamations","cn":"（用于感叹）","ex":{"en":"Off to bed with you!","cn":"你给我睡觉去！"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"(人)与…在一起,同…一道，和，跟","en":"If one person is with another, they are together in one place.","ex":{"en":"With her were her son and daughter-in-law","cn":"和她在一起的是她的儿子和儿媳。"}},{"pos":"PREP 介词","cn":"和…(放在)一起","en":"If something is put with or is with something else, they are used at the same time.","ex":{"en":"Serve hot, with pasta or rice and French beans","cn":"趁热和意大利面或米饭以及四季豆一起端上桌。"}},{"pos":"PREP 介词","cn":"与…一起(做或参与某事)","en":"If you do something with someone else, you both do it together or are both involved in it.","ex":{"en":"Parents will be able to discuss their child's progress with their teacher","cn":"家长将可以和老师交流谈论子女的进步情况。"}},{"pos":"PREP 介词","cn":"和，与，同(…打斗、争论或竞争)","en":"If you fight, argue, or compete with someone, you oppose them.","ex":{"en":"About a thousand students fought with riot police in the capital","cn":"大约1,000名学生在首都与防暴警察发生了冲突。"}},{"pos":"PREP 介词","cn":"用，使用(某种工具、物品或材料)","en":"If you do something with a particular tool, object, or substance, you do it using that tool, object, or substance.","ex":{"en":"Remove the meat with a fork and divide it among four plates","cn":"用餐叉把肉叉走，分到4个盘里。"}},{"pos":"PREP 介词","cn":"拿着;带着;扛着","en":"If someone stands or goes somewhere with something, they are carrying it.","ex":{"en":"A man came round with a tray of chocolates","cn":"一名男子端着一托盘巧克力走过来。"}},{"pos":"PREP 介词","cn":"有，拥有(某种特征或所有物)","en":"Someone or something with a particular feature or possession has that feature or possession.","ex":{"en":"He was in his early forties, tall and blond with bright blue eyes","cn":"他40出头儿，高高的个子，金黄头发，一双天蓝色眼睛。"}},{"pos":"PREP 介词","cn":"患(病)","en":"Someone with an illness has that illness.","ex":{"en":"I spent a week in bed with flu.","cn":"我得了流感，一星期都卧病在床。"}},{"pos":"PREP 介词","cn":"由…，用…(填充、覆盖)","en":"If something is filled or covered with a substance or with things, it has that substance or those things in it or on it.","ex":{"en":"His legs were caked with dried mud","cn":"他腿上结着干泥巴。"}},{"pos":"PREP 介词","cn":"对…(怀有某种感情)","en":"If you are, for example, pleased or annoyed with someone or something, you have that feeling towards them.","ex":{"en":"He was still a little angry with her","cn":"他还有点儿生她的气。"}},{"pos":"PREP 介词","cn":"在…方面, 针对","en":"You use with to indicate what a state, quality, or action relates to, involves, or affects.","ex":{"en":"Our aim is to allow student teachers to become familiar with the classroom","cn":"我们的目标就是让实习教师熟悉课堂。"}},{"pos":"PREP 介词","cn":"用(某种方式)；带着(某种感情)","en":"You use with when indicating the way that something is done or the feeling that a person has when they do something.","ex":{"en":"...teaching her to read music with skill and sensitivity","cn":"教她熟练而敏锐地识乐谱"}},{"pos":"PREP 介词","cn":"伴着(声音或手势);带着(表情)","en":"You use with when indicating a sound or gesture that is made when something is done, or an expression that a person has on their face when they do something.","ex":{"en":"With a sigh, she leant back and closed her eyes","cn":"她叹了口气，身体向后倚靠，闭上了眼睛。"}},{"pos":"PREP 介词","cn":"由于，因为(某种感情而使某人有某种表现或行为)","en":"You use with to indicate the feeling that makes someone have a particular appearance or type of behaviour.","ex":{"en":"Gil was white and trembling with anger","cn":"吉尔气得脸色煞白，浑身发抖。"}},{"pos":"PREP 介词","cn":"（表示以某姿势、外表或伴随某事件做某事）与…同时，随着","en":"You use with when mentioning the position or appearance of a person or thing at the time that they do something, or what someone else is doing at that time.","ex":{"en":"Joanne stood with her hands on the sink, staring out the window","cn":"乔安妮站着，两手放在水槽上，眼睛定定地望着窗外。"}},{"pos":"PREP 介词","cn":"由于;因为","en":"You use with to introduce a current situation that is a factor affecting another situation.","ex":{"en":"With all the night school courses available, there is no excuse for not getting some sort of training","cn":"夜校课程一应俱全，没理由不去接受一些培训。"}},{"pos":"PREP 介词","cn":"同，与，跟(…相比或对照)","en":"You use with when making a comparison or contrast between the situations of different people or things.","ex":{"en":"We're not like them. It's different with us","cn":"我们和他们不一样,我们不那么做。"}},{"pos":"PREP 介词","cn":"随着，跟着(…的变化而变化)","en":"If something increases or decreases with a particular factor, it changes as that factor changes.","ex":{"en":"The risk of developing heart disease increases with the number of cigarettes smoked","cn":"吸食香烟的数量越多，患心脏病的风险就越大。"}},{"pos":"PREP 介词","cn":"与(风、水流等)方向一致；顺着…","en":"If something moves with a wind or current, it moves in the same direction as the wind or current.","ex":{"en":"...a piece of driftwood carried down with the current","cn":"顺流而下的一块浮木"}},{"pos":"PREP 介词","cn":"理解;明白;懂得","en":"If someone says that they are with you, they mean that they understand what you are saying.","ex":{"en":"Yes, I know who you mean. Yes, now I'm with you","cn":"是的，我知道你说的是谁。是的，我现在明白你的意思了。"}},{"pos":"PREP 介词","cn":"赞成;支持","en":"If someone says that they are with you, they mean that they support or approve of what you are doing.","ex":{"en":"'I'm with you all the way.' — 'Thank you.'","cn":"“我会一直支持你。”——“谢谢！”"}}]},"examples":[{"en":"With all the lesson preparation I have to do I work 12 hours a day.","cn":"加上必须的备课在内，我每天工作 12 个小时。"},{"en":"He muttered a few words of apology and with that he left.","cn":"他低声叽咕了几句道歉的话，然后就走了。"}]},"wise":{"oxford":{"phon":"waɪz","pos":"adjective","senses":[{"en":"able to make sensible decisions and give good advice because of the experience and knowledge that you have","cn":"充满智慧的；明智的；英明的；明察善断的","ex":{"en":"a wise man","cn":"智者"}},{"en":"sensible; based on good judgement","cn":"明智的；高明的；有判断力的","ex":{"en":"a wise decision/move/choice/investment","cn":"明智的决定／行动／选择／投资"}},{"en":"in the manner or direction of","cn":"以…方式；朝…方向","ex":{"en":"likewise","cn":"同样"},"pos":"suffix"},{"en":"relating to","cn":"关于；在…方面","lab":"informal","ex":{"en":"Things aren't too good businesswise.","cn":"业务方面的情况不太好。"},"pos":"suffix"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）充满智慧的，英明的，睿智的","en":"A wise person is able to use their experience and knowledge in order to make sensible decisions and judgments.","ex":{"en":"She has the air of a wise woman","cn":"她有才女气质。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行动或决定)明智的，高明的","en":"A wise action or decision is sensible.","ex":{"en":"It's never wise to withhold evidence","cn":"藏匿证据绝非明智之举。"}},{"pos":"PHRASE 短语","cn":"(做…)是明智的；最好（做…）","en":"If someone says to you that it would be wise to do something, they are advising you to do it, because it is the most sensible and reasonable action or decision in a particular situation.","ex":{"en":"It would be wise to get his eyes checked to ensure there is no problem.","cn":"最好检查一下他的眼睛，确保没有问题。"}},{"pos":"PHRASE 短语","cn":"明白，察觉(尤指他人试图保密之事)","en":"If you get wise to something, you find out about it, especially when someone has been trying to keep it secret.","ex":{"en":"Dealers have already got wise to the trend and increased their prices accordingly.","cn":"交易商已经摸清了动向，相应提高了价格。"}},{"pos":"PHRASE 短语","cn":"（在事后或作出解释后）仍然不明白，仍旧不完全知晓","en":"If you say that someone is none the wiser after an event or an explanation, or that nobody is any the wiser after it, you mean that they have failed to understand it, or are not fully aware of what happened.","ex":{"en":"The brewers are still none the wiser about the shape the Government envisages for the industry","cn":"啤酒公司对政府对该行业的构想仍然不甚明了。"}},{"pos":"","cn":"","en":"相关词组：wise up"}]},"media":{"uk":"media/uk/wise__gb_1.mp3","us":"media/us/wise__us_1.mp3"},"examples":[{"en":"He thought he could fool me but I got wise to him.","cn":"他以为能耍得了我，其实我清楚他是怎么一号人。"},{"en":"I'm older and wiser after ten years in the business.","cn":"在商界混了十年之后，我变得老成聪明了。"}]},"wider":{"oxford":{"phon":"waɪd","pos":"adj.","senses":[{"en":"measuring a lot from one side to the other","cn":"宽的；宽阔的"},{"en":"measuring a particular distance from one side to the other …","cn":"宽的；宽度为 … 的"}]}},"wishing":{"oxford":{"phon":"wɪʃ","pos":"verb","senses":[{"en":"( not usually used in the present progressive tense","cn":"通常不用于现在进行时 ) to want sth to happen or to be true even though it is unlikely or impossible 希望（不大可能的事）发生；怀着（不可能实现的）愿望"},{"en":"‘That’ is nearly always left out, especially in speech.","cn":""}]}},"winked":{"oxford":{"phon":"wɪŋk","pos":"verb","senses":[{"en":"to close one eye and open it again quickly, especially as a private signal to sb, or to show sth is a joke","cn":"眨一只眼，眨眼示意（尤指使眼色或表示开玩笑）"},{"en":"to shine with an unsteady light; to flash on and off","cn":"闪烁；明灭"}]}},"winters":{"oxford":{"phon":"ˈwɪntə(r)","pos":"noun","senses":[{"en":"the coldest season of the year, between autumn/fall and spring","cn":"冬天；冬季"},{"en":"to spend the winter somewhere","cn":"过冬"}]}},"withdrew":{"oxford":{"phon":"wɪðˈdrɔː","pos":"verb","senses":[{"en":"to move back or away from a place or situation; to make sb/sth do this （","cn":"使）撤回，撤离"},{"en":"to stop giving or offering sth to sb","cn":"停止提供；不再给予"}]},"collins":{"senses":[{"pos":"","cn":"","en":"Withdrew is the past tense of withdraw."}]}},"winds":{"oxford":{"phon":"wɪnd","pos":"noun","senses":[{"en":"air that moves quickly as a result of natural forces","cn":"风；气流"},{"en":"air that you swallow with food or drink; gas that is produced in your stomach or intestines that makes you feel uncomfortable （","cn":"随食物或饮料）吞下的气；胃气；肠气"}]}},"wiping":{"oxford":{"phon":"waɪp","pos":"verb","senses":[{"en":"to rub sth against a surface, in order to remove dirt or liquid from it; to rub a surface with a cloth, etc. in order to clean it","cn":"擦；拭；抹；揩；蹭"},{"en":"to remove dirt, liquid, etc. from sth by using a cloth, your hand, etc. （","cn":"用布、手等）擦干净，抹掉"}]}},"widening":{"oxford":{"phon":"ˈwaɪdn","pos":"verb","senses":[{"en":"to become wider; to make sth wider （","cn":"使）变宽；加宽；拓宽；放宽"},{"en":"to become larger in degree or range; to make sth larger in degree or range （","cn":"使）扩展，程度加深，范围扩大"}]}},"wishes":{"oxford":{"phon":"wɪʃ","pos":"verb","senses":[{"en":"( not usually used in the present progressive tense","cn":"通常不用于现在进行时 ) to want sth to happen or to be true even though it is unlikely or impossible 希望（不大可能的事）发生；怀着（不可能实现的）愿望"},{"en":"‘That’ is nearly always left out, especially in speech.","cn":""}]}},"wiped":{"oxford":{"phon":"waɪp","pos":"verb","senses":[{"en":"to rub sth against a surface, in order to remove dirt or liquid from it; to rub a surface with a cloth, etc. in order to clean it","cn":"擦；拭；抹；揩；蹭"},{"en":"to remove dirt, liquid, etc. from sth by using a cloth, your hand, etc. （","cn":"用布、手等）擦干净，抹掉"}]}},"wings":{"oxford":{"phon":"wɪŋ","pos":"noun","senses":[{"en":"one of the parts of the body of a bird, insect or bat that it uses for flying （","cn":"鸟、昆虫或蝙蝠）翅膀，翼"},{"en":"one of the large flat parts that stick out from the side of a plane and help to keep it in the air when it is flying （","cn":"飞行器的）翅膀；机翼"}]}},"windows":{"oxford":{"phon":"ˈwɪndəʊz","pos":"","senses":[{"en":"a system developed by the US company Microsoft to operate computer programs. Each program has its own window (= area on the screen in which a particular program is operating). There have been several versions of the system since it was first produced in 1985.","cn":"Windows操作系统由美国微软公司开发的计算机操作系统，每个程序在屏幕上都有独立的窗口。自1985年问世以来已推出多个版本。"}]},"media":{"uk":"media/ldoce/hwd/bre/9/p028-000012966.mp3","us":"media/ldoce/hwd/ame/9/p028-000012966.mp3"}},"windshield":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(汽车等的)风挡，挡风玻璃","en":"The windshield of a car or other vehicle is the glass window at the front through which the driver looks."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a windscreen 〔","cn":"汽车前部的〕挡风玻璃"},{"en":"a piece of glass or clear plastic fixed at the front of a motorcycle that protects the rider from wind 〔","cn":"摩托车前面的〕挡风玻璃"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41windshield.mp3","us":"media/ldoce/hwd/ame/4/windshield.mp3"},"oxford":{"phon":"ˈwɪndʃiːld","pos":"noun","senses":[{"en":"the window across the front of a vehicle","cn":"（机动车前面的）挡风玻璃，风挡","lab":"North American English"},{"en":"a glass or plastic screen that provides protection from the wind, for example at the front of a motorcycle","cn":"（摩托车等前面的）挡风玻璃，风挡"}]}},"wiper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（挡风玻璃）刮雨器，雨刷","en":"A wiper is a device that wipes rain from a vehicle's windscreen."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment on a car, that removes rain from the windscreen 〔","cn":"汽车挡风玻璃的〕刮水器﹐雨刷"}]},"collocations":{"phrases":["ADJ. windscreen | rear","VERB + WIPER put on, switch on, turn on | switch off, turn off | be fitted with","WIPER + VERB be going, be on Cars were coming past with their wipers going."]},"media":{"uk":"media/ldoce/hwd/bre/3/wiper0205.mp3","us":"media/ldoce/hwd/ame/8/laadwiper.mp3"},"oxford":{"phon":"ˈwaɪpə(r)","pos":"noun","senses":[{"en":"a long metal part with a rubber edge that moves across a windscreen to make it clear of rain, snow, etc.","cn":"雨刮器；挡风玻璃刮水器；风挡雨雪刷","ex":{"en":"Cars were coming past with their wipers going.","cn":"汽车开着刮雨刷迎面驶过。"}}]}},"wisteria":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"紫藤","en":"Wisteria is a type of climbing plant which has pale purple or white flowers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a climbing plant with purple or white flowers","cn":"紫藤〔一种攀缘植物﹐开紫色或白色花〕"}]},"media":{"uk":"media/ldoce/hwd/bre/6/wisteria0205.mp3","us":"media/ldoce/hwd/ame/c/wisteria.mp3"},"oxford":{"phon":"wɪˈstɪəriə","pos":"noun","senses":[{"en":"a climbing plant with bunches of pale purple or white flowers that hang down","cn":"紫藤属植物"}]}},"widowhood":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"寡居;守寡","en":"Widowhood is the state of being a widow or widower, or the period of time during which someone is a widow or widower.","ex":{"en":"Nothing can prepare you for the shock and grief of widowhood.","cn":"守寡的打击和悲伤让人难以承受。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the state of being a widow or widower","cn":"守寡﹐孀居﹔鳏居"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41widowhood.mp3","us":"media/ldoce/hwd/ame/c/widowhood.mp3"},"oxford":{"phon":"ˈwɪdəʊhʊd","pos":"noun","senses":[{"en":"the state or period of being a widow or widower","cn":"寡居（期）；鳏居（期）"}]}},"windward":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(尤指船侧)迎风的，向风的，顶风的","en":"Windward is used to describe the side of something, especially a ship, which is facing the wind.","ex":{"en":"...the windward side of the quarterdeck","cn":"上层后甲板区的迎风面"}},{"pos":"PHRASE 短语","cn":"(船等)顶风，迎风","en":"If a ship sails to windward, it sails towards the place from which the wind is blowing."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"towards the direction from which the wind is blowing","cn":"迎风的[地]﹐向风的[地]"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41windward.mp3","us":"media/ldoce/hwd/ame/6/windward1.mp3"},"examples":[{"en":"the windward side of the boat","cn":"船向风的一侧"},{"en":"to sail to windward","cn":"迎风航行"}],"oxford":{"phon":"ˈwɪndwəd","pos":"adverb","senses":[{"en":"on or towards the side of something from which the wind is blowing","cn":"向风的；迎风的；顶风的；上风的"},{"en":"on the side of something from which the wind is blowing","cn":"向风的；迎风的；顶风的；上风的","ex":{"en":"the windward side of the boat","cn":"船向风的一侧"},"pos":"adjective"},{"en":"the side or direction from which the wind is blowing","cn":"向风面；迎风面；上风面","ex":{"en":"to sail to windward","cn":"迎风航行"},"pos":"noun"}]}},"wince":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(因疼痛或因看到、听到或记起不快之事而)皱起脸，皱眉蹙额","en":"If you wince, the muscles of your face tighten suddenly because you have felt a pain or because you have just seen, heard, or remembered something unpleasant.","ex":{"en":"Every time he put any weight on his left leg he winced in pain","cn":"只要左腿一受力，他就会疼得龇牙咧嘴。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to suddenly change the expression on your face as a reaction to something painful or upsetting 〔","cn":"因疼痛或不安而〕龇牙咧嘴﹐皱眉蹙额"},{"en":"to suddenly feel very uncomfortable or embarrassed because of something that happens, something you remember etc 〔","cn":"因发生或记起某事等而突然〕感到不安﹔畏缩"}]},"vocab":{"pos":"v n","senses":[{"en":"A wince is a facial or bodily expression of pain, disgust, or regret. Think of something you've done that was really, really embarrassing or dumb: now feel your face or take a look in the mirror as you wince at the uncomfortable memory."}]},"collocations":{"phrases":["ADV. a little, slightly | inwardly He winced inwardly at her harsh tone. | visibly","VERB + WINCE try not to | make sb | see sb","PREP. at She switched on the light, wincing at the sudden brightness. | in/with He winced in pain."]},"media":{"uk":"media/ldoce/hwd/bre/1/wince0205.mp3","us":"media/ldoce/hwd/ame/e/wince.mp3"},"examples":[{"en":"He winced as a sharp pain shot through his left leg.","cn":"他左腿一阵剧痛疼得他直龇牙咧嘴。"},{"en":"I still wince when I think about that stupid thing I said.","cn":"我想到我说过的蠢话时仍懊悔不已。"}],"oxford":{"phon":"wɪns","pos":"noun","senses":[{"en":"an expression on your face that shows that you are embarrassed or feeling pain","cn":"（因痛苦或尴尬）龇牙咧嘴，皱眉蹙额","ex":{"en":"a wince of pain","cn":"痛得龇牙咧嘴"}},{"en":"to suddenly make an expression with your face that shows that you are embarrassed or feeling pain","cn":"（因尴尬或痛苦）龇牙咧嘴，皱眉蹙额","ex":{"en":"He winced as a sharp pain shot through his left leg.","cn":"他左腿一阵剧痛疼得他直龇牙咧嘴。"},"pos":"verb"}]}},"wiggle":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）扭动;（使）摆动","en":"If you wiggle something or if it wiggles, it moves up and down or from side to side in small quick movements.","ex":{"en":"She wiggled her finger","cn":"她扭了扭手指。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move your toes, fingers, bottom etc with a series of small movements","cn":""},{"en":"to move part of your body, especially your bottom, legs, or toes, from side to side or up and down, with fairly large movements","cn":""},{"en":"if a dog wags its tail, it moves its tail from side to side; if a person wags their finger or head, they shake it repeatedly, especially in order to show that they do not like something that someone has done","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To wiggle is to move something back and forth. When you dance, you probably wiggle your hips. If you wiggle them too much, your mother might wiggle a finger at you and say \"Settle down!\""}]},"media":{"uk":"media/ldoce/hwd/bre/f/wiggle0205.mp3","us":"media/ldoce/hwd/ame/a/wiggle.mp3"},"examples":[{"en":"Her bottom wiggled as she walked past.","cn":"她屁股一扭一扭地走了过去。"},{"en":"He removed his shoes and wiggled his toes.","cn":"他脱掉鞋子，扭动着脚趾。"}],"oxford":{"phon":"ˈwɪɡl","pos":"verb","senses":[{"en":"to move from side to side or up and down in short, quick movements; to make something move in this way","cn":"（使）扭动，摆动，摇动，起伏","ex":{"en":"Her bottom wiggled as she walked past.","cn":"她屁股一扭一扭地走了过去。"}},{"en":"a small movement from side to side or up and down","cn":"（轻微的）摆动，扭动，摇动，起伏","pos":"noun"}]}},"windless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无风的;不起风的","en":"If the air is windless, or if it is a windless day, it is very calm and still."}]},"examples":[{"en":"a windless day","cn":"风平浪静的一天"}],"oxford":{"phon":"ˈwɪndləs","pos":"adjective","senses":[{"en":"without wind","cn":"无风的；平静的","ex":{"en":"a windless day","cn":"风平浪静的一天"}}]}},"withhold":{"collins":{"senses":[{"pos":"VERB 动词","cn":"拒绝给予;扣留","en":"If you withhold something that someone wants, you do not let them have it.","ex":{"en":"Police withheld the dead boy's name yesterday until relatives could be told","cn":"警方昨天拒绝在通知亲属前透露死亡男孩的姓名。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if someone in authority denies someone something that they want, for example money, a right, or the chance to do something, they refuse to give it to them","cn":""},{"en":"to refuse to give someone something that they want - use this especially in official or legal contexts","cn":""},{"en":"to not give information, especially when you have been officially asked to do so","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you keep something back and don't share it, you withhold it. You can withhold things such as permission, emotion, or information. You might get into trouble if you withhold information from your parents or the police."}]},"collocations":{"phrases":["ADV. deliberately | reasonably, unreasonably Consent will not be unreasonably withheld.","VERB + WITHHOLD threaten to threatening to withhold future financial aid | decide to","PREP. from He was accused of deliberately withholding information from the police."]},"media":{"uk":"media/ldoce/hwd/bre/3/withhold0205.mp3","us":"media/ldoce/hwd/ame/d/withhold.mp3"},"examples":[{"en":"She was accused of withholding information from the police.","cn":"她被指控对警方知情不报。"},{"en":"I withheld payment until they had completed the work.","cn":"我扣着钱﹐直到他们完工。"}],"oxford":{"phon":"wɪðˈhəʊld","pos":"verb","senses":[{"en":"to refuse to give something to somebody","cn":"拒绝给；不给","ex":{"en":"She was accused of withholding information from the police.","cn":"她被指控对警方知情不报。"}}]}},"wide-eyed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"天真的;不懂世故的","en":"If you describe someone as wide-eyed, you mean that they are inexperienced and innocent, and may be easily impressed.","ex":{"en":"Her wide-eyed innocence soon exposes the pretensions of the art world.","cn":"她的天真无邪很快就让艺术界的自命不凡显露无遗。"}},{"pos":"ADJ 形容词","cn":"(尤指因惊讶或恐惧而)睁大眼睛的","en":"If you describe someone as wide-eyed, you mean that their eyes are more open than usual, especially because they are surprised or frightened.","ex":{"en":"She is wide-eyed with astonishment.","cn":"她吃惊地睁大了眼睛。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"with your eyes wide open, especially because you are surprised or frightened 〔","cn":"尤因惊讶或恐惧而〕睁大眼睛的[地]"},{"en":"too willing to believe, accept, or admire things because you do not have much experience of life","cn":"天真的[地]﹐单纯的[地]"}]},"media":{"uk":"media/ldoce/hwd/bre/b/wide_eyed0205.mp3","us":"media/ldoce/hwd/ame/4/wide-eyed.mp3"},"examples":[{"en":"She stared at him in wide-eyed amazement.","cn":"她睁大眼睛惊讶地注视着他。"},{"en":"He stood there wide-eyed at the appalling scene.","cn":"他站在那里睁大双眼看着那令人震惊的场面。"}],"oxford":{"phon":"ˌwaɪd ˈaɪd","pos":"adjective","senses":[{"en":"with your eyes fully open because of fear, surprise, etc.","cn":"（因恐惧、惊讶等）睁大眼睛的","ex":{"en":"She stared at him in wide-eyed amazement.","cn":"她睁大眼睛惊讶地注视着他。"}},{"en":"having little experience and therefore very willing to believe, trust or accept somebody/something","cn":"天真的"}]}},"wimpy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"懦弱的;窝囊的","en":"If you describe a person or their behaviour as wimpy, you disapprove of them because they are weak and seem to lack confidence or determination.","ex":{"en":"...a wimpy unpopular schoolboy","cn":"不合群的懦弱小男生"}}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a British type of fast food restaurant that mainly sells hamburger s","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld5_wimpy.mp3","us":"media/ldoce/hwd/ame/7/ld5_wimpy.mp3"}},"wilt":{"collins":{"senses":[{"pos":"VERB 动词","cn":"枯萎;凋谢;发蔫","en":"If a plant wilts, it gradually bends downwards and becomes weak because it needs more water or is dying.","ex":{"en":"The roses wilted the day after she bought them","cn":"她买的玫瑰第二天就凋谢了。"}},{"pos":"VERB 动词","cn":"变得萎靡不振;打蔫儿;消沉","en":"If someone wilts, they become weak or tired, or lose confidence.","ex":{"en":"She soon wilted in the morning heat","cn":"在早晨的热浪中她很快就蔫儿了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a plant or flower wilts , it becomes weak and loses its colour, freshness etc, especially because of heat or lack of water","cn":""},{"en":"if a plant or flower droops , it starts to hang down, especially because it is not getting enough water, and begins to die","cn":""},{"en":"if a plant wilts, it bends over because it is too dry or old","cn":""}]},"collocations":{"phrases":["ADV. visibly","VERB + WILT begin to Some of the leaves were beginning to wilt.","PREP. in The plants will wilt in direct sunlight. | under By half-time, the team was wilting under the pressure. | with The passengers were "]},"media":{"uk":"media/ldoce/hwd/bre/9/wilt_v0205.mp3","us":"media/ldoce/hwd/ame/8/wilt1.mp3"},"examples":[{"en":"The spectators were wilting visibly in the hot sun.","cn":"看得出观众在炎热的阳光下快支撑不住了。"},{"en":"He was wilting under the pressure of work.","cn":"他被工作压得喘不过气来。"}],"oxford":{"phon":"wɪlt","pos":"verb","senses":[{"en":"to bend towards the ground because of the heat or a lack of water","cn":"枯萎；凋谢；蔫","g":"[intransitive]","ex":{"en":"Some of the leaves were beginning to wilt.","cn":"有些叶子开始枯萎。"}},{"en":"to become weak or tired or less confident","cn":"变得萎靡不振；发蔫；变得又累又乏；失去自信","g":"[intransitive]","lab":"informal","ex":{"en":"The spectators were wilting visibly in the hot sun.","cn":"看得出观众在炙热的阳光下快支撑不住了。"}},{"en":"used to mean ‘you will’, when talking to one person","cn":"（同一个人谈话时用，即 you will）","lab":"old use"}]}},"wide-ranging":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"范围广的;广泛的","en":"If you describe something as wide-ranging, you mean it deals with or affects a great variety of different things.","ex":{"en":"...a wide-ranging debate about the party's goals.","cn":"关于该政党目标宗旨的广泛争论"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"consisting of or including many different people, things, activities etc","cn":""},{"en":"the differences within a group, set of actions etc that make it interesting","cn":""},{"en":"a diverse group of people or things contains a lot of very different types of people or things","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/wide_ranging0205.mp3","us":"media/ldoce/hwd/ame/2/wide-ranging.mp3"},"examples":[{"en":"The commission has been given wide-ranging powers.","cn":"委员会被授予的权限很广。"},{"en":"a wide-ranging discussion","cn":"广泛的讨论"}],"oxford":{"phon":"ˌwaɪd ˈreɪndʒɪŋ","pos":"adjective","senses":[{"en":"including or dealing with a large number of different subjects or areas","cn":"覆盖面广的；内容广泛的","ex":{"en":"The commission has been given wide-ranging powers.","cn":"委员会被授予的权限很广。"}}]}},"wistful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(因求而不得)失意的，伤感的，惆怅的","en":"Someone who is wistful is rather sad because they want something and know that they cannot have it.","ex":{"en":"I can't help feeling slightly wistful about the perks I'm giving up","cn":"我不禁对自己将要放弃的津贴感到有点儿不舍。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not happy","cn":""},{"en":"sad, especially for a long time – used about people and periods of time","cn":""},{"en":"sad because you are away from your home, family, and friends","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Only one letter separates the two words, but \"wishful\" is having hope for something, and wistful is having sadness or melancholy about something. \"Wist\" isn't even a word that's used anymore, but you can still be wistful."}]},"media":{"uk":"media/ldoce/hwd/bre/2/wistful0205.mp3","us":"media/ldoce/hwd/ame/6/wistful.mp3"},"examples":[{"en":"‘If only I had known you then,’ he said wistfully. “","cn":"要是我那时认识你就好了。”他向往地说道。"},{"en":"She sighed wistfully.","cn":"她伤感地叹息。"}],"oxford":{"phon":"ˈwɪstfl","pos":"adjective","senses":[{"en":"thinking sadly about something that you would like to have, especially something in the past that you can no longer have","cn":"伤感的；（对已不可能发生之事）徒然神往的","ex":{"en":"a wistful smile","cn":"伤感的微笑"}}]}},"windbreaker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"防风夹克;风衣","en":"A Windbreaker is a warm casual jacket."}]},"oxford":{"phon":"ˈwɪndbreɪkə(r)","pos":"noun","senses":[{"en":"a jacket designed to protect you from the wind","cn":"防风夹克；风衣"}]}},"widget":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小器具；小装置","en":"You can refer to any small device as a widget when you do not know exactly what it is or how it works.","ex":{"en":"The secret is a little widget in the can.","cn":"奥秘在于易拉罐中的一个小玩意儿。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small piece of equipment that you do not know the name for 〔","cn":"不知名的〕小装置﹐小设备"},{"en":"used to refer to an imaginary product that a company might produce 〔","cn":"某公司假设生产的〕产品"},{"en":"a small piece of software used as part of a webpage , or on a mobile phone , that shows information or does other things in a way that is controlled by the user","cn":"微件〔网页或手机上的一种小软件〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41widget.mp3","us":"media/ldoce/hwd/ame/f/widget.mp3"},"examples":[{"en":"Company A produces two million widgets a year. * A","cn":"公司年产 200 万件产品。"},{"en":"Company A produces two million widgets a year.","cn":""}],"oxford":{"phon":"ˈwɪdʒɪt","pos":"noun","senses":[{"en":"used to refer to any small device that you do not know the name of","cn":"（不知名的）小器物，小装置，小玩意儿","lab":"informal"},{"en":"a product that does not exist, used as an example of a typical product","cn":"（虚拟的）典型产品","lab":"business","ex":{"en":"Company A produces two million widgets a year.","cn":"A 公司年产 200 万件产品。"}},{"en":"a small box on a computer screen that delivers changing information, such as news items or weather reports, while the rest of the page remains the same","cn":"微件，挂件（电脑屏幕上显示不时更新的信息的小窗口）","lab":"computing","ex":{"en":"widgets include search boxes, weather guides, pop-up windows and drop-down lists","cn":"小部件包括搜索框、天气指南、弹出窗口和下拉列表"}}]}},"wiretap":{"collins":{"senses":[{"pos":"VERB 动词","cn":"搭线窃听(电话)","en":"If someone wiretaps your telephone, they attach a special device to the line so that they can secretly listen to your conversations.","ex":{"en":"The coach said his club had wiretapped the hotel room of a player during a road trip.","cn":"教练说他的俱乐部曾经窃听了一名开车旅行的运动员所住宾馆房间的电话。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the action of secretly listening to other people’s telephone conversations, by connecting something to the wires of their telephone","cn":""},{"en":"the action of secretly listening to other people’s telephone conversations, by connecting something to the wires of their telephone","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/wiretapping0703.mp3","us":"media/ldoce/hwd/ame/c/ld44wiretapping.mp3"},"examples":[{"en":"the use of illegal wiretaps","cn":"非法使用窃听电话"}],"oxford":{"phon":"ˈwaɪətæp","pos":"noun","senses":[{"en":"a device that can be attached to somebody's phone line in order to listen to their conversations secretly","cn":"窃听：可以连接到某人的电话线上以秘密收听其对话的设备","ex":{"en":"the use of illegal wiretaps","cn":"使用非法窃听装置"}},{"en":"to listen secretly to other people's phone conversations by attaching a device to the phone line","cn":"（用秘密连线方法）窃听电话","pos":"verb"}]}},"wisp":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（毛发的）缕，绺，小把","en":"A wisp of hair is a small, thin, untidy bunch of it.","ex":{"en":"She smoothed away a wisp of hair from her eyes.","cn":"她将眼睛上的一缕头发拨开。"}},{"pos":"N-COUNT 可数名词","cn":"(烟、云等的)缕","en":"A wisp of something such as smoke or cloud is an amount of it in a long thin shape.","ex":{"en":"A thin wisp of smoke straggled up through the trees.","cn":"一缕轻烟在林间袅袅升起。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a wisp of hair, grass, hay etc is a thin piece of it that is separate from the rest 〔","cn":"头发﹑草等的〕一缕﹐一把﹐一束"},{"en":"a wisp of smoke, cloud, mist etc is a small thin line of it that rises upwards 〔","cn":"烟﹑云﹑雾等的〕一缕"}]},"media":{"uk":"media/ldoce/hwd/bre/d/wisp0205.mp3","us":"media/ldoce/hwd/ame/4/wisp.mp3"},"examples":[{"en":"A wisp of hair had escaped from under her hat.","cn":"她的帽子下面露出一缕头发。"},{"en":"Wisps of smoke rose into the air.","cn":"缕缕轻烟袅袅升起。"}],"oxford":{"phon":"wɪsp","pos":"noun","senses":[{"en":"a small, thin piece of hair, grass, etc.","cn":"（头发、草等的）小缕，小绺，小把，小束","ex":{"en":"She brushed aside a stray wisp of hair.","cn":"她拨开一缕散乱的头发。"}},{"en":"a long, thin line of smoke or cloud","cn":"（烟、云等的）一缕","ex":{"en":"a thin wisp of smoke","cn":"一缕轻烟"}}]}},"wizened":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）干瘪的，皮肤起皱的","en":"A wizened person is old and has a lot of lines on their skin.","ex":{"en":"...a little wizened old fellow with no teeth.","cn":"掉光了牙齿的干瘪小老头"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"old - use this as a polite way of talking about old people","cn":""},{"en":"one who is becoming old, especially in an unattractive way, and seems too old to be a rock star, film star etc","cn":""},{"en":"a humorous but slightly unkind word meaning very old","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"\"You're looking quite wizened today,\" is a something you should never, ever say to your grandmother, no matter how shriveled with age she might be. Think of a caricature of a witch — not your beloved granny."}]},"media":{"uk":"media/ldoce/hwd/bre/6/wizened0205.mp3","us":"media/ldoce/hwd/ame/5/wizened.mp3"},"examples":[{"en":"a wizened little man","cn":"干瘪的小老头"},{"en":"wizened apples","cn":"皱瘪的苹果"}],"oxford":{"phon":"ˈwɪznd","pos":"adjective","senses":[{"en":"looking smaller and having many folds and lines in the skin, because of being old","cn":"（由于年老）干瘪的，多皱的，干枯的","ex":{"en":"a wizened little man","cn":"干瘪的小老头"}}]}},"withered":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人或身体部位)瘦弱的，衰老的，枯槁的","en":"If you describe a person or a part of their body as withered, you mean that they are thin and their skin looks old.","ex":{"en":"...her withered hands.","cn":"她干瘪的双手"}},{"pos":"ADJ 形容词","cn":"(四肢因疾病或受伤)瘦弱的，萎缩的","en":"Withered is used to describe someone's leg or arm when it is thin and weak because of disease or injury.","ex":{"en":"She has one slightly withered leg, noticeably thinner than the other.","cn":"她有一条腿有点儿萎缩，看上去明显比另一条腿瘦。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a withered plant has become drier and smaller and is dead or dying 〔","cn":"植物〕枯萎的﹐干枯的"},{"en":"a withered person looks thin and weak and old 〔","cn":"人〕枯槁的﹐憔悴的"},{"en":"a withered arm or leg has not developed properly and is thin and weak 〔","cn":"胳膊或腿〕发育不良的﹐萎缩的"}]},"vocab":{"pos":"adj","senses":[{"en":"If someone or something is shriveled or shrunken with age, it is withered . If your skin is looking a little withered from being out in the sun all the time, it's time for a really good moisturizer."}]},"media":{"uk":"media/ldoce/hwd/bre/a/withered0205.mp3","us":"media/ldoce/hwd/ame/8/laadwithered.mp3"},"examples":[{"en":"withered limbs","cn":"干瘪的四肢"},{"en":"withered leaves","cn":"枯叶"}],"oxford":{"phon":"ˈwɪðəd","pos":"adjective","senses":[{"en":"dried up and dead","cn":"干枯的；枯萎的","ex":{"en":"withered leaves","cn":"枯叶"}},{"en":"looking old because they are thin and weak and have very dry skin","cn":"衰老憔悴的；枯槁的；干瘪的"},{"en":"thin and weak and not fully developed because of disease","cn":"瘦弱的；发育不良的；病态的","ex":{"en":"withered limbs","cn":"干瘪的四肢"}}]}},"wiring":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"布线系统；线路系统","en":"The wiring in a building or machine is the system of wires that supply electricity to the different parts of it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the network of wires that form the electrical system in a building, vehicle, or piece of equipment 〔","cn":"建筑物﹑车辆或设备中的〕电线线路﹐线路系统"}]},"collocations":{"phrases":["ADJ. electric/electrical | dangerous, faulty, loose | mains | house","VERB + WIRING renew, replace The existing wiring will have to be replaced. | take out They took out the old wiring. | disconnect | check (ov","WIRING + NOUN diagram | system"]},"media":{"uk":"media/ldoce/hwd/bre/8/wiring0205.mp3","us":"media/ldoce/hwd/ame/4/wiring.mp3"},"examples":[{"en":"to check the wiring","cn":"检查线路"},{"en":"a wiring diagram","cn":"线路图"}],"oxford":{"phon":"ˈwaɪərɪŋ","pos":"noun","senses":[{"en":"the system of wires that is used for carrying electricity around a building or machine","cn":"（建筑物或机器的）供电线路","ex":{"en":"We'd better get an electrician to check the wiring before we start decorating.","cn":"在装修之前，我们最好找电工来检查一下线路。"}},{"en":"the connections of the brain or nervous system, especially when seen as causing behaviour that a person or animal has no control over","cn":"连线：大脑或神经系统的连接，尤其是当被视为导致人或动物无法控制的行为时","lab":"informal","ex":{"en":"the brain's internal wiring","cn":"大脑的内部线路"}}]}},"windfall":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"意外之财;横财","en":"A windfall is a sum of money that you receive unexpectedly or by luck, for example if you win a lottery."},{"pos":"N-COUNT 可数名词","cn":"被风吹落的果子（尤指苹果）","en":"A windfall is a fruit, especially an apple, that has fallen from a tree."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an amount of money that you get unexpectedly","cn":"意外之财"},{"en":"a piece of fruit that has fallen off a tree","cn":"树上掉落的果实﹐被风吹落的果实"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Lucky you! You just won the lottery and your windfall will make life very comfortable for you and your family. A windfall is a crazy bit of unexpected good fortune."}]},"collocations":{"phrases":["ADJ. unexpected","VERB + WINDFALL get, have She had an unexpected windfall of a thousand pounds when a cousin died.","WINDFALL + NOUN gains, profits | tax"]},"media":{"uk":"media/ldoce/hwd/bre/2/windfall0205.mp3","us":"media/ldoce/hwd/ame/7/windfall.mp3"},"examples":[{"en":"The hospital got a sudden windfall of £300 000.","cn":"这家医院获得了一笔 30 万英镑的意外款项。"},{"en":"The government imposed a windfall tax (= a tax on profits to be paid once only, not every year) on some industries.","cn":"政府对某些行业征收暴利税。"}],"oxford":{"phon":"ˈwɪndfɔːl","pos":"noun","senses":[{"en":"an amount of money that somebody/something wins or receives unexpectedly","cn":"意外之财；意外获得的东西","ex":{"en":"The hospital got a sudden windfall of £300 000.","cn":"这家医院获得了一笔 30 万英镑的意外款项。"}},{"en":"a fruit, especially an apple, that the wind has blown down from a tree","cn":"风吹落的果子（尤指苹果）","ex":{"en":"The ground was covered with windfalls.","cn":"地上布满了意外之财。"}}]}},"wildcat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"野猫","en":"A wildcat is a cat which is very fierce and lives especially in mountains and forests.","ex":{"en":"A giant wildcat is being hunted after 58 lambs were butchered.","cn":"一只大野猫在捕杀了58只羊羔后遭到猎捕。"}},{"pos":"ADJ 形容词","cn":"(罢工)未经工会同意的，自发进行的","en":"A wildcat strike happens suddenly, as a result of a decision by a group of workers, and is not officially approved by a trade union.","ex":{"en":"Frustration, anger and desperation have led to a series of wildcat strikes.","cn":"挫败感、愤怒和绝望引起了一系列自发性的罢工。"}},{"pos":"ADJ 形容词","cn":"(计划、项目或生意等)冒险的，计划不周详的","en":"A wildcat scheme, project, or business is risky and likely to fail, usually because there has not been enough planning.","ex":{"en":"It was a wildcat plan by some of our members.","cn":"这是我们的一些成员制订的一个冒险计划。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of cat that looks similar to a pet cat and lives in mountains, forests etc 〔","cn":"生活在山区﹑森林等中的〕野猫"},{"en":"to look for oil in a place where nobody has found any yet","cn":"勘探[钻探]石油"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41wildcat.mp3","us":"media/ldoce/hwd/ame/8/wildcat.mp3"},"oxford":{"phon":"ˈwaɪldkæt","pos":"adjective","senses":[{"en":"a wildcat strike happens suddenly and without the official support of a trade union","cn":"（罢工）未经工会同意的，突然自发进行的","ex":{"en":"Agreement was reached after several days of wildcat strikes.","cn":"经过几天的自发罢工后达成协议。"}},{"en":"that has not been carefully planned and that will probably not be successful; that does not follow normal standards and methods","cn":"（计划不周密而）不稳妥的；不按正常标准的"},{"en":"to look for oil in a place where nobody has found any yet","cn":"勘探石油","pos":"verb"},{"en":"a type of small wild cat that lives in mountains and forests","cn":"野猫（生活在山区或森林里）","pos":"noun"}]}},"windbreak":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"风障;防风林;挡风篱","en":"A windbreak is something such as a line of trees or a fence which gives protection against the wind."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a fence, line of trees, or wall that is intended to protect a place from the wind","cn":"挡风篱[墙]﹔防风林"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41windbreak.mp3","us":"media/ldoce/hwd/ame/9/windbreak.mp3"},"oxford":{"phon":"ˈwɪndbreɪk","pos":"noun","senses":[{"en":"a row of trees, a fence, etc. that provides protection from the wind","cn":"防风林；挡风篱；挡风墙；风障"}]}},"withdrawn":{"collins":{"senses":[{"pos":"","cn":"","en":"Withdrawn is the past participle of withdraw ."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"沉默寡言的;孤僻的;内向的","en":"Someone who is withdrawn is very quiet, and does not want to talk to other people.","ex":{"en":"Her husband had become withdrawn and moody.","cn":"她丈夫变得沉默寡言、喜怒无常。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"shy and not willing to say very much","cn":""},{"en":"worried and embarrassed about what you look like or what other people think of you","cn":""},{"en":"not brave or confident","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Quiet loners are withdrawn — that's a word for people who keep to themselves to such an extent that it seems a little unhealthy."}]},"media":{"uk":"media/ldoce/hwd/bre/f/withdrawn0205.mp3","us":"media/ldoce/hwd/ame/a/withdrawn.mp3"},"examples":[{"en":"After his wife’s death he became more and more withdrawn .","cn":"妻子去世后﹐他变得越来越自闭。"}],"oxford":{"phon":"wɪðˈdrɔːn","pos":"adjective","senses":[{"en":"not wanting to talk to other people; extremely quiet and shy","cn":"沉默寡言的；怕羞的；内向的","ex":{"en":"He was not the self-absorbed, withdrawn person he was sometimes portrayed as.","cn":"他并不像人们有时描绘的那样自私、孤僻。"}}]}},"winery":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"葡萄酒厂;酿酒厂","en":"A winery is a place where wine is made."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place where wine is made and stored","cn":"酿酒厂"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41winery.mp3","us":"media/ldoce/hwd/ame/2/laadwinery.mp3"},"oxford":{"phon":"ˈwaɪnəri","pos":"noun","senses":[{"en":"a place where wine is made","cn":"葡萄酒厂；酿酒厂"}]}},"winsome":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"迷人的;动人的；有魅力的","en":"If you describe a person or their actions or behaviour as winsome, you mean that they are attractive and charming.","ex":{"en":"...a winsome young screen star","cn":"迷人的年轻影视明星"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving in a pleasant and attractive way","cn":"迷人的﹔令人喜欢的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you are described as winsome , take it as a compliment. It means you are attractive or charming in an open and delightful way. It doesn't mean you win some and you lose some."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41winsome.mp3","us":"media/ldoce/hwd/ame/9/winsome.mp3"},"examples":[{"en":"a winsome smile","cn":"莞尔一笑"}],"oxford":{"phon":"ˈwɪnsəm","pos":"adjective","senses":[{"en":"pleasant and attractive","cn":"讨人喜欢的；惹人喜爱的；楚楚动人的","ex":{"en":"a winsome smile","cn":"莞尔一笑"}}]}},"wither":{"collins":{"senses":[{"pos":"VERB 动词","cn":"衰弱;凋敝","en":"If someone or something withers, they become very weak.","ex":{"en":"When he went into retirement, he visibly withered","cn":"他到退休年龄时已老态毕现。"}},{"pos":"VERB 动词","cn":"(花朵、植物)枯萎，凋谢","en":"If a flower or plant withers, it dries up and dies.","ex":{"en":"The flowers in Isabel's room had withered","cn":"伊莎贝尔房间里的花已经枯萎了。"}},{"pos":"N-PLURAL 复数名词","cn":"甲；马肩隆","en":"The highest part of a horse's back, behind its neck, is referred to as its withers ."},{"pos":"","cn":"","en":"相关词组：wither away"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if plants wither, or if something withers them, they become drier and smaller and start to die （","cn":"使）〔植物〕枯萎﹐干枯"},{"en":"to gradually become weaker or less successful and then end","cn":"逐渐疲弱﹐每况愈下"},{"en":"if something withers on the vine, it gradually ends because it is not given enough support 〔","cn":"因缺乏支持而〕中途夭折﹐未能成功"}]},"vocab":{"pos":"v","senses":[{"en":"Wither means to shrivel up or shrink. If you forget to water your plants for six weeks, they'll wither — they'll dry up and you probably won't be able to bring them back to life."}]},"collocations":{"phrases":["ADV. simply Their support had simply withered away. | away","PREP. under The grass withered under a scorching sun.","PHRASES wither and die The business withered and eventually died."]},"media":{"uk":"media/ldoce/hwd/bre/f/wither0205.mp3","us":"media/ldoce/hwd/ame/9/whither.mp3"},"examples":[{"en":"The grass had withered in the warm sun.","cn":"这些草在温暖的阳光下枯死了。"},{"en":"All our hopes just withered away.","cn":"我们所有的希望都渐渐破灭了。"}],"oxford":{"phon":"ˈwɪðə(r)","pos":"verb","senses":[{"en":"if a plant withers or something withers it, it dries up and dies","cn":"（使）枯萎，凋谢","g":"[intransitive, transitive]","ex":{"en":"The grass had withered in the warm sun.","cn":"这些草在温暖的阳光下枯死了。"}},{"en":"to become less or weaker, especially before disappearing completely","cn":"萎缩；（尤指渐渐）破灭，消失","g":"[intransitive]","ex":{"en":"All our hopes just withered away.","cn":"我们所有的希望都渐渐破灭了。"}}]}},"willy-nilly":{"collins":{"senses":[{"pos":"ADV 副词","cn":"不管喜欢不喜欢;无可奈何地","en":"If something happens to you willy-nilly, it happens whether you like it or not.","ex":{"en":"The government were dragged willy-nilly into the confrontation.","cn":"政府不管情愿不情愿，也被拖进了这场冲突。"}},{"pos":"ADV 副词","cn":"随意地;胡乱地","en":"If someone does something willy-nilly, they do it in a careless and disorganized way, without planning it in advance.","ex":{"en":"Clerks bundled papers into files willy-nilly.","cn":"职员们随意地将文件塞进文件夹里。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"if something happens willy-nilly, it happens whether you want it to or not","cn":"不管愿不愿意﹔无论想不想要"},{"en":"without planning, organization, or control","cn":"乱糟糟地﹐杂乱地﹐随意地"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41willy-nilly.mp3","us":"media/ldoce/hwd/ame/0/willy-nilly.mp3"},"examples":[{"en":"She was forced willy-nilly to accept the company's proposals.","cn":"她被迫无奈接受了公司的提议。"},{"en":"Don't use your credit card willy-nilly.","cn":"别拿着你的信用卡随便花。"}],"oxford":{"phon":"ˌwɪli ˈnɪli","pos":"adverb","senses":[{"en":"whether you want to or not","cn":"不管愿意不愿意；无论想要不想要","ex":{"en":"She was forced willy-nilly to accept the company's proposals.","cn":"她被迫无奈接受了公司的提议。"}},{"en":"in a careless way without planning","cn":"随意地；乱糟糟地","ex":{"en":"Don't use your credit card willy-nilly.","cn":"别拿着你的信用卡随便花。"}}]}},"wispy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(头发)稀疏的，稀稀拉拉的","en":"If someone has wispy hair, their hair does not grow thickly on their head.","ex":{"en":"Grey wispy hair straggled down to her shoulders.","cn":"稀疏的灰白头发披散在她肩头。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(云)一缕缕的，虚无缥缈的","en":"A wispy cloud is thin or faint.","ex":{"en":"The half moon is hidden behind some wispy clouds.","cn":"半轮月亮躲在淡淡的云彩之后。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a wisp of hair, grass, hay etc is a thin piece of it that is separate from the rest","cn":""},{"en":"a wisp of smoke, cloud, mist etc is a small thin line of it that rises upwards","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Wispy describes something that's vague or flimsy. If your explanation of why you didn't help your mom paint the kitchen was weak and didn't help her understand your reasons, you'd call that a wispy explanation."}]},"media":{"uk":"media/ldoce/hwd/bre/d/wisp0205.mp3","us":"media/ldoce/hwd/ame/4/wisp.mp3"},"examples":[{"en":"wispy hair/clouds","cn":"一缕缕头发/云彩"},{"en":"a wispy beard","cn":"一绺绺胡须"}],"oxford":{"phon":"ˈwɪspi","pos":"adjective","senses":[{"en":"consisting of small, thin pieces; not thick","cn":"一绺绺的；一缕缕的；成束的；纤细的","ex":{"en":"wispy hair/clouds","cn":"一缕缕头发／云彩"}}]}},"winger":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(足球、曲棍球等的)边锋","en":"In a game such as football or hockey, a winger is an attacking player who plays mainly on the far left or the far right side of the pitch."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who plays in the far left or far right of the field in games such as football 〔","cn":"足球等运动的〕边锋﹐侧翼队员"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41winger.mp3","us":"media/ldoce/hwd/ame/5/winger.mp3"},"oxford":{"phon":"ˈwɪŋə(r)","pos":"noun","senses":[{"en":"either of the attacking players who play towards the side of the playing area in sports such as football (soccer) or hockey","cn":"（足球、曲棍球等）边锋"}]}},"withstand":{"collins":{"senses":[{"pos":"VERB 动词","cn":"经受住;承受;顶住","en":"If something or someone withstands a force or action, they survive it or do not give in to it.","ex":{"en":"...armoured vehicles designed to withstand chemical attack","cn":"具有抵御化学武器袭击的设计功能的装甲车"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be strong enough to remain unharmed by something such as great heat, cold, pressure etc","cn":"耐受﹐承受〔酷热﹑严寒﹑高压等〕"},{"en":"to defend yourself successfully against people who attack, criticize, or oppose you","cn":"抵挡﹐顶住〔人们的攻击﹑批评或反对〕"}]},"vocab":{"pos":"v","senses":[{"en":"In the story of the three little pigs, only the house made of brick was able to withstand the huffing and puffing of the Big Bad Wolf. To withstand is to hold up against something strong."}]},"collocations":{"phrases":["VERB + WITHSTAND be able/unable to, can/could | manage to | be built to, be designed to The wooden boat was built to withstand just about ev","PHRASES be capable of withstanding sth"]},"media":{"uk":"media/ldoce/hwd/bre/9/withstand0205.mp3","us":"media/ldoce/hwd/ame/c/withstand.mp3"},"examples":[{"en":"The materials used have to be able to withstand high temperatures.","cn":"所使用的材料必须能够耐高温。"},{"en":"They had withstood siege, hunger and deprivation.","cn":"他们经受了围困、饥饿和贫穷。"}],"oxford":{"phon":"wɪðˈstænd","pos":"verb","senses":[{"en":"to be strong enough not to be hurt or damaged by extreme conditions, the use of force, etc.","cn":"承受；抵住；顶住；经受住","ex":{"en":"The materials used have to be able to withstand high temperatures.","cn":"所使用的材料必须能够耐高温。"}}]}},"wickerwork":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同wicker","en":"Wickerwork is the same as wicker ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"objects made from wicker","cn":"柳条编制品"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41wickerwork.mp3","us":"media/ldoce/hwd/ame/6/ld41wickerwork.mp3"},"oxford":{"phon":"ˈwɪkəwɜːk","pos":"noun","senses":[{"en":"baskets, furniture, etc. made from wicker","cn":"柳条编制品","ex":{"en":"wickerwork chairs","cn":"藤椅。"}}]}},"wintertime":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"冬季;冬天;冬令","en":"Wintertime is the period of time during which winter lasts."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the time when it is winter","cn":"冬季﹔冬天"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41wintertime.mp3","us":"media/ldoce/hwd/ame/9/wintertime.mp3"},"examples":[{"en":"The days are shorter in (the) wintertime.","cn":"冬季白天较短。"},{"en":"The hills look very bleak in wintertime.","cn":"冬季这些山坡看上去很荒凉。"}],"oxford":{"phon":"ˈwɪntətaɪm","pos":"noun","senses":[{"en":"the period of time when it is winter","cn":"冬季；冬天；冬令","ex":{"en":"The days are shorter in (the) wintertime.","cn":"冬季白天较短。"}}]}},"winch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"绞车;卷扬机","en":"A winch is a machine which is used to lift heavy objects or people who need to be rescued. It consists of a drum around which a rope or chain is wound."},{"pos":"VERB 动词","cn":"用绞车吊起","en":"If you winch an object or person somewhere, you lift or lower them using a winch.","ex":{"en":"He would attach a cable around the chassis of the car and winch it up on to the canal bank","cn":"他会把钢丝绳拴在汽车底盘上，用卷扬机把汽车吊到运河岸上。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a machine with a rope or chain for lifting heavy objects","cn":"绞车﹔起货机"},{"en":"to lift something or someone up using a winch","cn":"用绞车提起﹔用起货机吊起"}]},"media":{"uk":"media/ldoce/hwd/bre/0/winch_n0205.mp3","us":"media/ldoce/hwd/ame/6/winch1.mp3"},"examples":[{"en":"The two men were winched out of the sinking boat by an RAF helicopter.","cn":"那两名男子被皇家空军的直升机从正在下沉的小船里吊了出来。"}],"oxford":{"phon":"wɪntʃ","pos":"noun","senses":[{"en":"a machine for lifting or pulling heavy objects using a rope or chain","cn":"绞车；卷扬机；牵引机"},{"en":"to lift somebody/something up into the air using a winch","cn":"（用绞车）吊起，拉起","ex":{"en":"A helicopter winched the survivors to safety.","cn":"一架直升机将幸存者吊到安全地带。"},"pos":"verb"}]}},"wino":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指无家可归的)酒鬼","en":"Some people refer to alcoholics, especially homeless ones, as winos ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who drinks a lot of alcohol and lives on the streets 〔","cn":"露宿街头的〕醉鬼﹐酒鬼"}]},"media":{"uk":"media/ldoce/hwd/bre/f/wino0205.mp3","us":"media/ldoce/hwd/ame/d/wino.mp3"},"oxford":{"phon":"ˈwaɪnəʊ","pos":"noun","senses":[{"en":"a person who drinks a lot of cheap alcohol and who has no home","cn":"（无家可归的）酒鬼","ex":{"en":"There were a pair of winos sleeping under the bridge.","cn":"桥下睡着一对酒鬼。"}}]}},"windpipe":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"气管","en":"Your windpipe is the tube in your body that carries air into your lungs when you breathe."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the tube through which air passes from your mouth to your lungs","cn":"气管"}]},"media":{"uk":"media/ldoce/hwd/bre/4/windpipe0205.mp3","us":"media/ldoce/hwd/ame/9/windpipe.mp3"},"oxford":{"phon":"ˈwɪndpaɪp","pos":"noun","senses":[{"en":"the tube in the body that carries air from the throat to the lungs","cn":"气管","ex":{"en":"It felt as if strong fingers were squeezing his windpipe.","cn":"感觉就像有力的手指正在挤压他的气管。"}}]}},"windlass":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"绞盘;卷扬机;辘轳","en":"A windlass is a mechanical device for lifting heavy objects, which uses a motor to pull a rope or chain around a cylinder."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a machine for pulling or lifting heavy objects","cn":"绞车﹐起锚机﹐起重辘轳"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41windlass.mp3","us":"media/ldoce/hwd/ame/f/windlass.mp3"},"oxford":{"phon":"ˈwɪndləs","pos":"noun","senses":[{"en":"a type of winch (= a machine for lifting or pulling heavy objects)","cn":"绞盘；卷扬机；辘轳"}]}},"winnow":{"collins":{"senses":[{"pos":"VERB 动词","cn":"筛选;遴选","en":"If you winnow a group of things or people, you reduce its size by separating the ones that are useful or relevant from the ones that are not.","ex":{"en":"Administration officials have winnowed the list of candidates to three.","cn":"行政官员将候选名单筛减至3人。"}},{"pos":"","cn":"","en":"相关词组：winnow out"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a list, group, or quantity smaller by getting rid of the things that you do not need or want","cn":"筛选﹐遴选"},{"en":"to get rid of the things or people that you do not need or want from a group","cn":"筛除〔不想要的人或物〕"}]},"vocab":{"pos":"n v","senses":[{"en":"To winnow is to blow something away until you are left with what you want, like grain from chaff. If you only want your favorite people at the party, you will need to winnow down the guest list from 300 to 30."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41winnow.mp3","us":"media/ldoce/hwd/ame/4/winnow.mp3"},"examples":[{"en":"We need to winnow the list of candidates to three.","cn":"我们需要把名单上的候选人删减到三位。"}],"oxford":{"phon":"ˈwɪnəʊ","pos":"verb","senses":[{"en":"to blow air through grain in order to remove its outer layer (called the chaff)","cn":"簸，扬，风选（以去掉谷壳）"}]}},"windbag":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"话篓子;唠叨鬼","en":"If you call someone a windbag, you are saying in a fairly rude way that you think they talk a great deal in a boring way."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to talk for too long in a confused way, changing the subject and forgetting what you have already said","cn":""},{"en":"to talk quickly and in a confused way so that you seem slightly silly, especially because you are nervous","cn":""},{"en":"to talk for a long time without making your meaning clear and without really saying anything useful or important","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you find yourself stuck on a bus beside someone who talks endlessly about boring subjects, you might think to yourself, \"What a windbag .\" It's an informal way to describe a big talker."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41windbag.mp3","us":"media/ldoce/hwd/ame/8/windbag.mp3"},"oxford":{"phon":"ˈwɪndbæɡ","pos":"noun","senses":[{"en":"a person who talks too much, and does not say anything important or interesting","cn":"夸夸其谈的人；空话连篇的人；话匣子"}]}},"windowpane":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"窗玻璃","en":"A windowpane is a piece of glass in the window of a building."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a single whole piece of glass in a window 〔","cn":"整块〕窗玻璃"}]},"media":{"uk":"media/ldoce/hwd/bre/e/windowpane0205.mp3","us":"media/ldoce/hwd/ame/b/windowpane.mp3"},"oxford":{"phon":"ˈwɪndəʊpeɪn","pos":"noun","senses":[{"en":"a piece of glass in a window","cn":"（一块）窗玻璃","ex":{"en":"Rain was beating against the windowpanes.","cn":"雨打在窗玻璃上。"}}]}},"wingspan":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(鸟、昆虫或飞机的)翼展，翼幅","en":"The wingspan of a bird, insect, or aeroplane is the distance from the end of one wing to the end of the other wing.","ex":{"en":"...a glider with an 18-foot wingspan.","cn":"翼展18英尺的滑翔机"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the distance from the end of one wing to the end of the other","cn":"翼展﹐翼幅〔指两翼展开时的宽度〕"}]},"media":{"uk":"media/ldoce/hwd/bre/2/wingspan0205.mp3","us":"media/ldoce/hwd/ame/e/wingspan.mp3"},"examples":[{"en":"a bird with a two-foot wingspan","cn":"翼幅为两英尺的鸟"}],"oxford":{"phon":"ˈwɪŋspæn","pos":"noun","senses":[{"en":"the distance between the end of one wing and the end of the other when the wings are fully stretched","cn":"翼展","ex":{"en":"a bird with a two-foot wingspan","cn":"翼展为两英尺的鸟"}}]}},"wishbone":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(鸡、火鸡等禽类的)叉骨，如愿骨","en":"A wishbone is a V-shaped bone in chickens, turkeys, and other birds."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the V-shaped bone from a cooked chicken, duck etc, which two people pull apart to decide who will make a wish","cn":"叉骨﹐如愿骨〔煮熟的鸡﹑鸭等的胸骨﹐由两人同时拉扯﹐以决定由谁许愿〕"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41wishbone.mp3","us":"media/ldoce/hwd/ame/7/wishbone.mp3"},"oxford":{"phon":"ˈwɪʃbəʊn","pos":"noun","senses":[{"en":"a bone in the shape of a V between the neck and breast of a chicken, duck, etc. When the bird is eaten, this bone is sometimes pulled apart by two people, and the person who gets the larger part can make a wish.","cn":"叉骨，许愿骨（禽类颈与胸之间的 V 形骨，吃禽肉时两人将其拉开，得较大块者可许愿）"}]}},"wick":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蜡烛芯","en":"The wick of a candle is the piece of string in it which burns when it is lit."},{"pos":"N-COUNT 可数名词","cn":"（煤油灯的）灯芯;（打火机的）棉芯","en":"The wick of a paraffin lamp or cigarette lighter is the part which supplies the fuel to the flame when it is lit."},{"pos":"PHRASE 短语","cn":"惹怒;激怒","en":"If you say that someone or something gets on your wick, you mean that they annoy and irritate you.","ex":{"en":"The Professor was beginning to get on Molly's wick.","cn":"教授快要把莫莉惹毛了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the piece of thread in a candle , that burns when you light it","cn":"蜡烛芯"},{"en":"a long piece of material in an oil lamp, that sucks up oil so that the lamp can burn 〔","cn":"油灯的〕灯芯"},{"en":"to annoy someone","cn":"使某人生气﹐使某人产生反感﹐惹怒某人"}]},"media":{"img":["media/ldoce/img/candle.jpg"],"uk":"media/ldoce/hwd/bre/2/wick0205.mp3","us":"media/ldoce/hwd/ame/a/wick.mp3"},"examples":[{"en":"Wool socks wick away sweat.","cn":"羊毛袜吸汗。"}],"oxford":{"phon":"wɪk","pos":"noun","senses":[{"en":"the piece of string in the centre of a candle that you light so that the candle burns","cn":"烛芯"},{"en":"the piece of material in an oil lamp that takes in the oil and that you light so that the lamp burns","cn":"灯芯"},{"en":"(of a material) to take small drops of liquid from an area and move them away","cn":"（指材料）吸干，吸取，吸走","ex":{"en":"Wool socks wick away sweat.","cn":"羊毛袜吸汗。"},"pos":"verb"}]}},"wink":{"collins":{"senses":[{"pos":"VERB 动词","cn":"向…眨眼；使眼色","en":"When you wink at someone, you look towards them and close one eye very briefly, usually as a signal that something is a joke or a secret.","ex":{"en":"Brian winked at his bride-to-be","cn":"布赖恩向他的准新娘使了个眼色。"}},{"pos":"VERB 动词","cn":"(灯)闪亮，闪烁","en":"If a lamp winks, it shines or reflects light in short flashes.","ex":{"en":"From the hotel window, they could see lights winking on the bay.","cn":"透过宾馆的窗子，他们能看见海湾一带灯光摇曳。"}},{"pos":"PHRASE 短语","cn":"无法入睡;没合一下眼","en":"If you say that you did not sleep a wink or did not get a wink of sleep, you mean that you tried to go to sleep but could not.","ex":{"en":"I didn't get a wink of sleep on the aeroplane.","cn":"我在飞机上没合一下眼。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a movement, especially with your hand, in order to tell someone something","cn":""},{"en":"to make a movement or sound in order to give instructions or information","cn":""},{"en":"to make a previously agreed sign that tells someone that they should start doing something","cn":""}]},"collocations":{"phrases":["ADJ. broad | little | conspiratorial, knowing","VERB + WINK direct, give sb, throw sb","PREP. with a ~ &lsquo;Know what I mean?&rsquo; he said with a wink. | ~ at He directed a conspiratorial wink at his son."]},"media":{"img":["media/ldoce/img/ldoce_352.png"],"uk":"media/ldoce/hwd/bre/e/wink_n0205.mp3","us":"media/ldoce/hwd/ame/6/wink1.mp3"},"examples":[{"en":"He winked at her and she knew he was thinking the same thing that she was.","cn":"他冲她眨了眨眼，她便知道他的想法和她一样。"},{"en":"We could see the lights of the ship winking in the distance.","cn":"我们看见船在远方忽明忽暗地闪着灯光。"}],"oxford":{"phon":"wɪŋk","pos":"verb","senses":[{"en":"to close one eye and open it again quickly, especially as a private signal to somebody, or to show something is a joke","cn":"眨一只眼，眨眼示意（尤指使眼色或表示开玩笑）","g":"[intransitive]","ex":{"en":"He winked at her and she knew he was thinking the same thing that she was.","cn":"他冲她眨了眨眼，她便知道他的想法和她一样。"}},{"en":"to shine with an unsteady light; to flash on and off","cn":"闪烁；明灭","g":"[intransitive]","ex":{"en":"We could see the lights of the ship winking in the distance.","cn":"我们看见船在远方忽明忽暗地闪着灯光。"}},{"en":"an act of winking, especially as a signal to somebody","cn":"眨一只眼；眨眼示意；眼色","ex":{"en":"He gave her a knowing wink.","cn":"他向她会意地眨了一下眼睛。"},"pos":"noun"}]}},"with-it":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"fashionable and modern in the way that you dress, think etc 〔","cn":"衣着﹑思想等〕时髦的﹐时兴的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/with_it0205.mp3","us":"media/ldoce/hwd/ame/a/with-it.mp3"}},"widen":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）变宽;（把…）加宽","en":"If you widen something or if it widens, it becomes greater in measurement from one side or edge to the other.","ex":{"en":"He had an operation last year to widen a heart artery","cn":"去年他接受了一个扩张心脏动脉的手术。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)扩大;(使)扩展;(使)增加","en":"If you widen something or if it widens, it becomes greater in range or it affects a larger number of people or things.","ex":{"en":"U.S. prosecutors have widened a securities-fraud investigation","cn":"美国检察官扩大了对一起证券欺诈案的调查范围。"}},{"pos":"VERB 动词","cn":"(眼睛)睁大","en":"If your eyes widen, they open more.","ex":{"en":"His eyes widened as he spoke the words.","cn":"他说这番话时眼睛瞪大了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(差距)拉大","en":"If a difference or gap widens or if something widens it, it becomes greater.","ex":{"en":"Wage differences in the two areas are widening","cn":"两个地区的工资差距正在拉大。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to become larger in number, amount, price, value etc","cn":""},{"en":"to increase - use this about numbers, prices, or temperatures etc, but also about the level or standard of something","cn":""},{"en":"to increase gradually over a period of time - use this about numbers or amounts, or about a total amount of business activity or trade","cn":""}]},"collocations":{"phrases":["ADV. considerably, greatly The gap between rich and poor has widened considerably. | slightly | gradually, slowly | quickly, rapidly | sudde","PREP. from, into At this point the river widens into an estuary. | to The trade deficit had widened from &pound; 26 billion to &pound; 30 bi"]},"media":{"uk":"media/ldoce/hwd/bre/8/widen0205.mp3","us":"media/ldoce/hwd/ame/1/widen.mp3"},"examples":[{"en":"We plan to widen the scope of our existing activities by offering more language courses.","cn":"我们计划通过开设更多的语言课程以扩大我们现有的活动范围。"},{"en":"They may have to widen the road to cope with the increase in traffic.","cn":"他们可能得拓宽这条道路以适应车辆的增多。"}],"oxford":{"phon":"ˈwaɪdn","pos":"verb","senses":[{"en":"to become wider; to make something wider","cn":"（使）变宽；加宽；拓宽；放宽","g":"[intransitive, transitive]","ex":{"en":"Her eyes widened in surprise.","cn":"她惊讶地睁大了眼睛。"}},{"en":"to become larger in degree or range; to make something larger in degree or range","cn":"（使）扩展，程度加深，范围扩大","g":"[intransitive, transitive]","ex":{"en":"Another concern is the widening gap between rich and poor.","cn":"另一个令人担忧的问题是贫富差距不断扩大。"}}]}},"wicket":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(板球运动中的)三柱门","en":"In cricket, a wicket is a set of three upright sticks with two small sticks on top of them at which the ball is bowled. There are two wickets on a cricket pitch."},{"pos":"N-COUNT 可数名词","cn":"(板球场中)两个三柱门之间的场地","en":"In cricket, a wicket is the area of grass in between the two wickets on the pitch."},{"pos":"N-COUNT 可数名词","cn":"（板球运动中）击球手击球的一轮，击球手的避免出局","en":"In cricket, when a wicket falls or is taken, a batsman is out."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of two sets of three wooden sticks that are stuck in the ground in a game of cricket , which the bowler tries to hit with the ball 〔","cn":"板球的〕桩门，三柱门"}]},"media":{"uk":"media/ldoce/hwd/bre/d/wicket0205.mp3","us":"media/ldoce/hwd/ame/b/wicket.mp3"},"oxford":{"phon":"ˈwɪkɪt","pos":"noun","senses":[{"en":"either of the two sets of three sticks standing in the ground (called stumps) with pieces of wood (called bails) lying across the top. The bowler tries to hit the wicket with the ball.","cn":"三柱门"},{"en":"the area of ground between the two wickets","cn":"两个三柱门之间的场地"}]}},"winkle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"滨螺，蛾螺，玉黍螺（可食用）","en":"Winkles are small sea snails that can be eaten."},{"pos":"","cn":"","en":"相关词组：winkle out"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small sea animal that lives in a shell and is eaten as food","cn":"滨螺〔一种可食用的螺〕"},{"en":"to make someone leave a place","cn":"把〔某人〕赶出来"},{"en":"to get information from someone who does not want to give it to you","cn":"搞到﹐套出〔信息等〕"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41winkle.mp3","us":"media/ldoce/hwd/ame/6/ld41winkle.mp3"},"examples":[{"en":"She always manages to winkle secrets out of people.","cn":"她总是能从别人那里探听出秘密。"},{"en":"Government critics were winkled out of their positions of influence.","cn":"批评政府的人士被解除了重要职位。"}],"oxford":{"phon":"ˈwɪŋkl","pos":"noun","senses":[{"en":"a small shellfish, like a snail, that can be eaten","cn":"滨螺（可食用）"}]}},"wisecrack":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"俏皮话;风凉话","en":"A wisecrack is a clever remark that is intended to be amusing, but is often rather unkind."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a funny story that you tell people to make them laugh","cn":""},{"en":"a short story that someone tells to make people laugh","cn":""},{"en":"a short joke, especially one told by a professional entertainer","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/wisecrack0205.mp3","us":"media/ldoce/hwd/ame/f/wisecrack1.mp3"},"examples":[{"en":"He plays a wisecracking detective.","cn":"他扮演一位满嘴俏皮话的侦探。"}],"oxford":{"phon":"ˈwaɪzkræk","pos":"noun","senses":[{"en":"a clever remark or joke","cn":"俏皮话；风凉话"},{"en":"to make a clever remark or joke","cn":"俏皮话；风凉话","ex":{"en":"He plays a wisecracking detective.","cn":"他扮演一位满嘴俏皮话的侦探。"},"pos":"verb"}]}},"windy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"多风的;大风的","en":"If it is windy, the wind is blowing a lot.","ex":{"en":"It was windy and Jake felt cold.","cn":"风很大，杰克觉得很冷。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if it is windy, there is a lot of wind","cn":"风大的﹔多风的"},{"en":"blustery weather is very windy, with sudden strong winds","cn":""},{"en":"if the weather is breezy, the wind blows fairly strongly","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/windy0205.mp3","us":"media/ldoce/hwd/ame/5/windy.mp3"},"examples":[{"en":"windy hills","cn":"当风的丘陵"},{"en":"a windy day","cn":"大风天"}],"oxford":{"phon":"ˈwɪndi","pos":"adjective","senses":[{"en":"with a lot of wind","cn":"多风的；风大的","ex":{"en":"a windy day","cn":"大风天"}},{"en":"getting a lot of wind","cn":"当风的；受大风吹的","ex":{"en":"windy hills","cn":"当风的丘陵"}},{"en":"involving speaking for longer than necessary and in a way that is complicated and not clear","cn":"夸夸其谈的；空话连篇的；空洞无物的","lab":"informal, disapproving，，"}]}},"wipe":{"collins":{"senses":[{"pos":"VERB 动词","cn":"拭;擦;揩","en":"If you wipe something, you rub its surface to remove dirt or liquid from it.","ex":{"en":"I'll just wipe the table","cn":"我就擦擦桌子。"}},{"pos":"VERB 动词","cn":"擦去;擦掉","en":"If you wipe dirt or liquid from something, you remove it, for example by using a cloth or your hand.","ex":{"en":"Gleb wiped the sweat from his face","cn":"格莱布擦去脸上的汗水。"}},{"pos":"N-COUNT 可数名词","cn":"（一次性）湿巾","en":"A wipe is a small moist cloth for cleaning things and is designed to be used only once.","ex":{"en":"...antiseptic wipes.","cn":"消毒湿巾"}},{"pos":"PHRASE 短语","cn":"让…笑容顿失;使…兴致全无;使…丧失优势","en":"If you say that something wipes the smile off someone's face, you mean that it suddenly spoils their enjoyment or removes an advantage that they had and that you are pleased about it.","ex":{"en":"Tony Holmes wiped the smile off the faces of his rivals with a solo 30-second win.","cn":"托尼·福尔摩斯以30秒的领先优势获得了这一赛段的个人胜利，使对手再也笑不起来。"}},{"pos":"","cn":"","en":"to wipe the floor with someone→see: ; to wipe the slate clean→see: ;"},{"pos":"","cn":"","en":"相关词组：wipe away wipe down wipe off wipe out wipe up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to remove dirt from something","cn":""},{"en":"to clean something with water and usually soap","cn":""},{"en":"to clean a surface with a cloth, often a wet cloth","cn":""}]},"collocations":{"phrases":["ADV. carefully, gently | hastily, quickly | easily The plastic surface can be easily wiped. | just, simply | away, down, up I wiped up the s","VERB + WIPE pause to, stop to He paused to wipe the sweat from his forehead. | try to","PREP. from She gently wiped the tears from her eyes. | off He wiped the marks off the wall. | on She wiped her hands on the towel. | with Wh","PHRASES wipe sth clean PHRASAL VERBS wipe sth out","ADV. completely, totally | almost, practically, virtually The regiment was virtually wiped out in the first battle. | effectively The diseas","VERB + WIPE threaten to pollution that threatens to wipe out 100,000 fish"]},"media":{"uk":"media/ldoce/hwd/bre/7/wipe_las3_br.mp3","us":"media/ldoce/hwd/ame/a/wipe1.mp3"},"examples":[{"en":"Billions of pounds were wiped off share prices today.","cn":"今天的股票价格下挫造成数十亿英镑的损失。"},{"en":"Somebody had wiped all the tapes.","cn":"有人把所有磁带上录制的内容都抹掉了。"}],"oxford":{"phon":"waɪp","pos":"verb","senses":[{"en":"to rub something against a surface, in order to remove dirt or liquid from it; to rub a surface with a cloth, etc. in order to clean it","cn":"擦；拭；抹；揩；蹭","ex":{"en":"Please wipe your feet on the mat.","cn":"请在垫子上蹭一蹭脚。"}},{"en":"to remove dirt, liquid, etc. from something by using a cloth, your hand, etc.","cn":"（用布、手等）擦干净，抹掉","ex":{"en":"He wiped the sweat from his forehead.","cn":"他擦去额头上的汗。"}},{"en":"to remove information, sound, images, etc. from a computer, video, etc.","cn":"消除，抹去（计算机、录像带等上的信息）","ex":{"en":"You must have wiped off that programme I recorded.","cn":"你一定是把我录制的节目给抹掉了。"}},{"en":"to deliberately forget an experience because it was unpleasant or embarrassing","cn":"抹去（旧事）","ex":{"en":"I tried to wipe the whole episode from my mind.","cn":"我设法把这整个经历从心中抹掉。"}},{"en":"an act of cleaning something using a cloth","cn":"擦；揩；拭","ex":{"en":"Can you give the table a quick wipe?","cn":"你把桌子快速擦一下行吗？"},"pos":"noun"},{"en":"a special piece of thin cloth or soft paper that has been treated with a liquid and that you use to clean away dirt and bacteria","cn":"（湿）抹布，纸巾","ex":{"en":"Remember to take nappies and baby wipes.","cn":"记住带尿布和婴儿湿巾。"},"pos":"noun"}]}},"wimp":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"软蛋;窝囊废","en":"If you call someone a wimp, you disapprove of them because they lack confidence or determination, or because they are often afraid of things."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"not brave","cn":""},{"en":"someone who is not brave enough to do something dangerous or unpleasant that they should do","cn":""},{"en":"someone who is spineless is too weak to say what they really think because they are afraid of what might happen or what other people might say -- use this to show disapproval","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/wimp_las3_br.mp3","us":"media/ldoce/hwd/ame/d/wimp1.mp3"},"examples":[{"en":"wimpish behaviour","cn":"懦弱的行为"},{"en":"Don’t be such a wimp!","cn":"别那么窝囊！"}],"oxford":{"phon":"wɪmp","pos":"noun","senses":[{"en":"a person who is not strong, brave or confident","cn":"懦夫；窝囊废","ex":{"en":"He won’t go on his own—he’s a complete wimp!","cn":"他不会自己去，他是个十足的窝囊废！"}}]}},"winnings":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"(比赛或赌博中)赢得的钱","en":"You can use winnings to refer to the money that someone wins in a competition or by gambling.","ex":{"en":"I have come to collect my winnings.","cn":"我来领我赢的钱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is given to the person who wins a competition, game, or race","cn":""},{"en":"a special silver or gold container, shaped like a large cup with two handles, that is given to the winner of a sports competition","cn":""},{"en":"a round flat piece of metal that is given to someone who has won a race, game, or competition","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdewinnings.mp3","us":"media/ldoce/hwd/ame/4/winnings.mp3"},"examples":[{"en":"lottery winnings","cn":"彩票奖金"}],"oxford":{"phon":"ˈwɪnɪŋz","pos":"noun","senses":[{"en":"money that somebody wins in a competition or game or by gambling","cn":"（比赛、赌博中）赢得的钱"}]}},"wing":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"翼;翅膀","en":"The wings of a bird or insect are the two parts of its body that it uses for flying.","ex":{"en":"The bird flapped its wings furiously","cn":"鸟儿使劲地拍打翅膀。"}},{"pos":"N-COUNT 可数名词","cn":"机翼","en":"The wings of an aeroplane are the long flat parts sticking out of its side which support it while it is flying."},{"pos":"N-COUNT 可数名词","cn":"(建筑的)侧翼，耳房","en":"A wing of a building is a part of it which sticks out from the main part.","ex":{"en":"We were given an office in the empty west wing.","cn":"给我们在空置的大楼西翼分了一间办公室。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指政治组织的)派，翼","en":"A wing of an organization, especially a political organization, is a group within it which has a particular function or particular beliefs.","ex":{"en":"...the military wing of the African National Congress.","cn":"非洲国民大会的武装派"}},{"pos":"N-PLURAL 复数名词","cn":"(舞台两侧用帘幕或布景遮住的)边厢,翼部,侧面","en":"In a theatre, the wings are the sides of the stage which are hidden from the audience by curtains or scenery.","ex":{"en":"Most nights I watched the start of the play from the wings.","cn":"大多数晚上我都是在边厢观看戏剧的开场。"}},{"pos":"N-COUNT 可数名词","cn":"(足球、曲棍球等的)边锋位置；边锋","en":"In a game such as football or hockey, the left wing and the right wing are the areas on the far left and the far right of the pitch. You can also refer to the players who play in these positions as the left wing and the right wing ."},{"pos":"N-COUNT 可数名词","cn":"(汽车的)挡泥板，翼子板","en":"A wing of a car is a part of it on the outside which is over one of the wheels."},{"pos":"N-PLURAL 复数名词","cn":"飞机驾驶资格；飞行资格","en":"When pilots get their wings, they become qualified to fly aeroplanes.","ex":{"en":"He had no sooner got his wings than the Korean conflict broke out.","cn":"他刚获得飞行资格，朝鲜战争就爆发了。"}},{"pos":"VERB 动词","cn":"(尤指乘飞机)飞速去，赶往","en":"If you say that something or someone wings their way somewhere or wings somewhere, you mean that they go there quickly, especially by plane.","ex":{"en":"A few moments later they were airborne and winging their way south","cn":"过了一会儿，他们已然搭上飞机赶往南方了。"}},{"pos":"PHRASE 短语","cn":"限制;束缚","en":"If you say that something or someone clips your wings, you mean that they restrict your freedom to do what you want.","ex":{"en":"...legislation aimed at clipping the president's political wings.","cn":"旨在从政治上限制总统的立法"}},{"pos":"PHRASE 短语","cn":"准备就绪;万事俱备","en":"If you say that someone is waiting in the wings, you mean that they are ready and waiting for an opportunity to take action.","ex":{"en":"There are now more than 20 big companies waiting in the wings to take over some of its business.","cn":"现有20多家大公司随时准备接手其部分业务。"}},{"pos":"PHRASE 短语","cn":"大展宏图;一试羽翼","en":"If you spread your wings, you do something new and rather difficult or move to a new place, because you feel more confident in your abilities than you used to and you want to gain wider experience.","ex":{"en":"I led a very confined life in my village so I suppose that I wanted to spread my wings.","cn":"我在村里生活很封闭，所以我想出去闯荡一番。"}},{"pos":"PHRASE 短语","cn":"将…置于羽翼之下；对…呵护有加","en":"If you take someone under your wing, you look after them, help them, and protect them.","ex":{"en":"Her boss took her under his wing after fully realizing her potential.","cn":"老板充分意识到她的潜力后，对她关怀备至。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to make sure someone has everything they need and is safe and happy","cn":""},{"en":"to give someone the care and help that you regularly give them, especially as part of your job","cn":""},{"en":"to start to look after a younger or less experienced person in a friendly way with the intention of helping them or protecting them while they gain experience","cn":""}]},"collocations":{"phrases":["ADJ. left, right | fore, front The beetle's fore wings are small and are not used in flight. | back, hind | broad, long, narrow, pointed, sh","QUANT. pair","VERB + WING extend, open, spread, stretch, unfold | close, fold | flap, flutter It flapped its wings and flew off. | clean | clip (often fig","WING + VERB beat, flap, flutter","WING + NOUN tip | feathers","PREP. on a/the ~ It had whit e markings on its wings. | under a/the ~ The young birds were under the mother bird's wing. (figurative) Simon'","ADJ. aircraft | left, port | right, starboard | fixed | folding","WING + VERB stick out"]},"media":{"img":["media/ldoce/img/ldoce_262.png","media/ldoce/img/butterfly.jpg"],"uk":"media/ldoce/hwd/bre/a/brelasdewing.mp3","us":"media/ldoce/hwd/ame/8/wing1.mp3"},"examples":[{"en":"I didn't know I'd have to make a speech — I just had to wing it.","cn":"我不知道还得讲话，只好临场即兴发挥说点什么。"},{"en":"A solitary seagull winged its way across the bay.","cn":"一只孤零零的海鸥飞过了海湾。"}],"oxford":{"phon":"wɪŋ","pos":"noun","senses":[{"en":"one of the parts of the body of a bird, insect or bat that it uses for flying","cn":"（鸟、昆虫或蝙蝠的）翅膀，翼","g":"[countable]","sc":"of bird/insect","ex":{"en":"The swan flapped its wings noisily.","cn":"天鹅大声地拍打着翅膀。"}},{"en":"the wing of a chicken, etc. eaten as food","cn":"（食用）禽翅","sc":"of bird/insect","ex":{"en":"We ordered the fried chicken wings.","cn":"我们点了炸鸡翅。"}},{"en":"one of the large flat parts that stick out from the side of a plane and help to keep it in the air when it is flying","cn":"（飞行器的）翅膀；机翼","g":"[countable]","sc":"of plane","ex":{"en":"Salvage teams have been able to recover part of the wing of the plane.","cn":"营救队找回了飞机的部分机翼。"}},{"en":"a part of a large building that sticks out from the main part","cn":"侧翼部分；侧厅；耳房；厢房","g":"[countable]","sc":"of building","ex":{"en":"the east wing","cn":"东翼楼"}},{"en":"a part of a car that is above a wheel","cn":"挡泥板；翼子板","g":"[countable]","lab":"British English","sc":"of car","ex":{"en":"There was a dent in the nearside wing.","cn":"左边挡泥板上有一个凹痕。"}},{"en":"one section of an organization that has a particular function or whose members share the same opinions","cn":"（起某种作用或持相同观点的）派，翼","g":"[countable]","sc":"of organization","ex":{"en":"The radical wing of the party was dissatisfied with the policies.","cn":"该党的激进派对这些政策不满。"}},{"en":"either of the attacking players who play towards the side of the playing area in sports such as football (soccer) or hockey","cn":"（足球、曲棍球等）边锋","g":"[countable]","lab":"sport","sc":"in football/hockey"},{"en":"the far left or right side of the sports field","cn":"（运动场地的左右）翼，侧翼","g":"[countable]","sc":"in football/hockey","ex":{"en":"He plays on the wing.","cn":"他踢边锋。"}},{"en":"the area at either side of the stage that cannot be seen by the audience","cn":"（舞台上观众看不到的）边厢，翼部，侧面","g":"[plural]","sc":"in theatre","ex":{"en":"She watched every performance from the wings.","cn":"她在侧翼观看每场表演。"}},{"en":"to fly somewhere","cn":"飞；飞行","g":"[transitive, intransitive]","lab":"literary","sc":"fly","ex":{"en":"A solitary seagull winged its way across the bay.","cn":"一只孤零零的海鸥飞过了海湾。"},"pos":"verb"},{"en":"to be sent somewhere very quickly","cn":"被迅速送往","g":"[transitive]","sc":"go quickly","ex":{"en":"An application form will be winging its way to you soon.","cn":"申请表不久将送达你处。"},"pos":"verb"}]}},"witch-hunt":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(针对异见群体的)迫害，搜捕，“猎巫”","en":"A witch-hunt is an attempt to find and punish a particular group of people who are being blamed for something, often simply because of their opinions and not because they have actually done anything wrong."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an attempt to find and punish people in a society or organization whose opinions are regarded as wrong or dangerous – used to show disapproval","cn":"搜捕异己﹐政治迫害〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41witch-hunt.mp3","us":"media/ldoce/hwd/ame/9/witch-hunt.mp3"},"examples":[{"en":"anti-Communist witch-hunts","cn":"反共大搜捕"}],"oxford":{"phon":"ˈwɪtʃ hʌnt","pos":"noun","senses":[{"en":"an attempt to find and punish people who hold opinions that are thought to be unacceptable or dangerous to society","cn":"（对被认为持不为社会所接受或危及社会政见者的）搜捕，政治迫害","ex":{"en":"The investigation turned into a full-scale Communist witch-hunt.","cn":"调查演变成了一场对共产主义者的大规模政治迫害。"}}]}},"winged":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(昆虫等)有翼的，带翅的","en":"A winged insect or other creature has wings.","ex":{"en":"Flycatchers feed primarily on winged insects.","cn":"鹟主要以有翅昆虫为食。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having wings","cn":"有翼的﹐有翅膀的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/winged0205.mp3","us":"media/ldoce/hwd/ame/3/winged.mp3"},"examples":[{"en":"winged insects","cn":"有翼昆虫"},{"en":"a long-winged bird","cn":"长翼鸟"}],"oxford":{"phon":"wɪŋd","pos":"adjective","senses":[{"en":"having wings","cn":"有翅膀的；有翼的","ex":{"en":"winged insects","cn":"有翼昆虫"}},{"en":"having the number or type of wings mentioned","cn":"有…只翅膀的；有…翅膀的","ex":{"en":"a long-winged bird","cn":"长翼鸟"}}]}},"witchcraft":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"巫术;(尤指)魔法，妖术","en":"Witchcraft is the use of magic powers, especially evil ones."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the power to make impossible things happen, by saying special words or doing special actions","cn":""},{"en":"the use of magic, usually to do bad things","cn":""},{"en":"a special set of words or actions that are used to make something happen by magic","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/witchcraft0205.mp3","us":"media/ldoce/hwd/ame/e/witchcraft.mp3"},"oxford":{"phon":"ˈwɪtʃkrɑːft","pos":"noun","senses":[{"en":"the use of magic powers, especially evil ones","cn":"妖术；巫术","ex":{"en":"to practise witchcraft","cn":"练习巫术"}},{"en":"religious practice that involves magic and connection with nature, usually within a pagan tradition","cn":"巫师所施的符咒；咒语"}]}},"wilful":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"故意的，有意的，成心的(尤指意在造成伤害)","en":"If you describe actions or attitudes as wilful, you are critical of them because they are done or expressed deliberately, especially with the intention of causing someone harm.","ex":{"en":"Wilful neglect of our manufacturing industry has caused this problem","cn":"故意忽略我们的制造业引起了这个问题。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"任性的;一意孤行的","en":"If you describe someone as wilful, you mean that they are determined to do what they want to do, even if it is not sensible.","ex":{"en":"...as the beautiful Lara becomes ever more wilful and irresponsible.","cn":"随着漂亮的拉拉变得越来越任性、越来越不负责任"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"refusing to change your mind, even when people think you are wrong or are being unreasonable","cn":""},{"en":"very stubborn, in way that is annoying and unreasonable","cn":""},{"en":"refusing to change your mind, even when people think that what you want to do is stupid","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/wilful0205.mp3","us":"media/ldoce/hwd/ame/7/laadwilful.mp3"},"examples":[{"en":"a wilful child","cn":"任性的孩子"},{"en":"wilful damage","cn":"蓄意破坏"}],"oxford":{"phon":"ˈwɪlfl","pos":"adjective","senses":[{"en":"done deliberately, although the person doing it knows that it is wrong","cn":"故意的；有意的；成心的","g":"[usually before noun]","lab":"formal, disapproving or law，，","ex":{"en":"wilful damage","cn":"蓄意破坏"}},{"en":"determined to do what you want; not caring about what other people want","cn":"任性的；固执的；倔强的","ex":{"en":"a wilful child","cn":"任性的孩子"}}]}},"witticism":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"妙语;俏皮话;诙谐话","en":"A witticism is a witty remark or joke."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a clever amusing remark","cn":"妙语﹔俏皮话﹔诙谐语"}]},"vocab":{"pos":"n","senses":[{"en":"Witticism describes something funny that someone says, like a pun or little joke. You may have heard that it is good to start off a speech with witticism because if you make the audience laugh, it'll help them — and you — relax."}]},"media":{"uk":"media/ldoce/hwd/bre/f/witticism0205.mp3","us":"media/ldoce/hwd/ame/9/witticism.mp3"},"oxford":{"phon":"ˈwɪtɪsɪzəm","pos":"noun","senses":[{"en":"a clever and humorous comment","cn":"妙语；俏皮话；诙谐语","ex":{"en":"He was roaring with laughter at his own witticism.","cn":"他对自己的俏皮话哈哈大笑。"}}]}},"wicked":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"缺德的;邪恶的;恶毒的","en":"You use wicked to describe someone or something that is very bad and deliberately harmful to people.","ex":{"en":"She described the shooting as a wicked attack","cn":"她称那次枪击为恶意袭击。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"淘气的;恶作剧的","en":"If you describe someone or something as wicked, you mean that they are rather naughty, but in a way that you find attractive or enjoyable.","ex":{"en":"She had a wicked sense of humour","cn":"她有种古灵精怪的幽默感。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very unkind","cn":""},{"en":"very unkind and deliberately making people feel unhappy or making them suffer physically","cn":""},{"en":"extremely unkind and behaving in a very immoral way","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Wicked has two quite contradictory meanings. If something is pure evil, then it is wicked. Think Darth Vader. On the other hand, as an informal slang term, wicked also means excellent — as in \"that DJ is wicked , man!\" Go figure."}]},"media":{"uk":"media/ldoce/hwd/bre/4/wicked0205.mp3","us":"media/ldoce/hwd/ame/3/wicked.mp3"},"examples":[{"en":"Jane has a wicked sense of humour.","cn":"简有一种恶作剧的幽默感。"},{"en":"Martin grinned wickedly.","cn":"马丁顽皮地咧嘴笑了笑。"}],"oxford":{"phon":"ˈwɪkɪd","pos":"adjective","senses":[{"en":"morally bad","cn":"邪恶的；缺德的","ex":{"en":"a wicked deed","cn":"伤天害理的行为"}},{"en":"slightly bad but in a way that is funny and/or attractive","cn":"淘气的；调皮的；恶作剧的","lab":"informal","ex":{"en":"a wicked grin","cn":"调皮的咧嘴一笑"}},{"en":"dangerous, harmful or powerful","cn":"危险的；有害的；强大的","ex":{"en":"He has a wicked punch.","cn":"他出拳凶猛。"}},{"en":"very good","cn":"极好的；很棒的","lab":"slang","ex":{"en":"This song's wicked.","cn":"这支歌太棒了。"}},{"en":"people who are wicked","cn":"恶人；邪恶的人","pos":"noun"}]}},"wildfire":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"野火","en":"A wildfire is a fire that starts, usually by itself, in a wild area such as a forest, and spreads rapidly, causing great damage.","ex":{"en":"...a wildfire in Montana that's already burned thousands of acres of rich grassland.","cn":"已经烧掉成千公顷丰饶草场的蒙大拿野火"}},{"pos":"PHRASE 短语","cn":"(消息或谣言等)迅速传播","en":"If something, especially news or a rumour, spreads like wildfire, it spreads extremely quickly.","ex":{"en":"These stories are spreading like wildfire through the city.","cn":"这些谣言迅速传遍了整座城市。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a fire that moves quickly and cannot be controlled","cn":"野火"}]},"media":{"uk":"media/ldoce/hwd/bre/a/wildfire0205.mp3","us":"media/ldoce/hwd/ame/4/wildfire.mp3"},"oxford":{"phon":"ˈwaɪldfaɪə(r)","pos":"noun","senses":[{"en":"a very big fire that spreads quickly and burns natural areas like woods, forests and grassland","cn":"野火；丛林大火","ex":{"en":"Firefighters are battling devastating wildfires in northern California.","cn":"消防队员正在与加州北部毁灭性的野火作斗争。"}}]}},"willpower":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"意志力;毅力","en":"Willpower is a very strong determination to do something.","ex":{"en":"I know I've got the willpower to do it","cn":"我知道我有毅力做这事儿。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the quality of continuing to try to do something, even when it is difficult","cn":""},{"en":"the ability to control your mind and body in order to achieve something you have decided to do","cn":""},{"en":"the determination and energy to succeed, especially in business or work","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Willpower is the ability to control or restrain yourself. If you bake brownies and can keep yourself from tasting them until after dinner, you can thank your willpower ."}]},"media":{"uk":"media/ldoce/hwd/bre/6/willpower0205.mp3","us":"media/ldoce/hwd/ame/8/willpower.mp3"},"examples":[{"en":"It took all his willpower to remain calm.","cn":"他竭尽全力才保持了镇定。"}],"oxford":{"phon":"ˈwɪlpaʊə(r)","pos":"noun","senses":[{"en":"the ability to control your thoughts and actions in order to achieve what you want to do","cn":"意志力","ex":{"en":"He’s intelligent but he’s got no willpower.","cn":"他很聪明，但没有意志力。"}}]}},"willow":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"柳;柳树","en":"A willow or a willow tree is a type of tree with long branches and long narrow leaves that grows near water.","ex":{"en":"...willow furniture.","cn":"柳木家具"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of tree that has long thin branches and grows near water, or the wood from this tree","cn":"柳树﹔柳木"}]},"media":{"uk":"media/ldoce/hwd/bre/9/willow0205.mp3","us":"media/ldoce/hwd/ame/e/willow.mp3","img":["media/thumb/willow.jpg"]},"oxford":{"phon":"ˈwɪləʊ","pos":"noun","senses":[{"en":"a tree with long, thin branches and long, thin leaves, that often grows near water","cn":"柳；柳树","g":"[countable]"},{"en":"the wood of the willow tree, used especially for making cricket bats","cn":"柳木（常用以制作板球拍）","g":"[uncountable]"},{"en":"a first name for girls","cn":"维楼，威洛，薇洛（女子名）","pos":""}]}},"windowsill":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"窗台；窗沿","en":"A windowsill is a shelf along the bottom of a window, either inside or outside a building."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a shelf fixed along the bottom of a window","cn":"窗台﹐窗沿"}]},"media":{"uk":"media/ldoce/hwd/bre/0/windowsill0205.mp3","us":"media/ldoce/hwd/ame/1/windowsill.mp3"},"examples":[{"en":"Place the plants on a sunny windowsill.","cn":"把这些植物放在阳光充足的窗台上。"}],"oxford":{"phon":"ˈwɪndəʊsɪl","pos":"noun","senses":[{"en":"a narrow shelf below a window, either inside or outside","cn":"窗沿；窗台","ex":{"en":"Place the plants on a sunny windowsill.","cn":"把这些植物放在阳光充足的窗台上。"}}]}},"wizard":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（传说或童话故事中的）魔法师","en":"In legends and fairy stories, a wizard is a man who has magic powers."},{"pos":"N-COUNT 可数名词","cn":"奇才;能手;行家","en":"If you admire someone because they are very good at doing a particular thing, you can say that they are a wizard .","ex":{"en":"...a financial wizard","cn":"金融奇才"}},{"pos":"N-COUNT 可数名词","cn":"向导程序","en":"A wizard is a computer program that guides you through the stages of a particular task.","ex":{"en":"Wizards and templates can help you create brochures, calendars, and Web pages.","cn":"向导程序和模板可以帮助你创建手册、日历和网页。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a woman who is believed to have magic power, which she uses especially to harm people or make bad things happen; in stories, witches are usually shown dressed in black with a tall, pointed hat","cn":""},{"en":"an imaginary creature like a small person with wings, who has magic powers","cn":""},{"en":"a man who is believed to have magic power; in stories, magicians and wizards are usually shown as having a long beard and a pointed hat with stars and moons on it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/wizard0205.mp3","us":"media/ldoce/hwd/ame/8/wizard.mp3"},"examples":[{"en":"a computer/financial, etc. wizard","cn":"计算机、金融等奇才"},{"en":"Ben’s a real wizard at chess.","cn":"本是个国际象棋奇才。"}],"oxford":{"phon":"ˈwɪzəd","pos":"noun","senses":[{"en":"(in stories) a man with magic powers","cn":"（传说中的）男巫，术士","ex":{"en":"There were rumours that Abbot was a wizard, practising magic and the black arts.","cn":"传言说阿博特是男巫，会施魔法行邪术。"}},{"en":"a person who is especially good at something","cn":"行家；能手；奇才","ex":{"en":"a computer/financial, etc. wizard","cn":"计算机、金融等奇才"}},{"en":"a program that makes it easy to use another program or perform a task by giving you a series of simple choices","cn":"向导（程序）","lab":"computing"}]}},"willowy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"苗条的;婀娜多姿的","en":"A person who is willowy is tall, thin, and graceful."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"thin in an attractive and graceful way","cn":""},{"en":"a woman or girl who is willowy is attractively tall and thin in a graceful way -- used especially in romantic novels","cn":""},{"en":"tall, thin, and graceful","cn":"修长苗条的﹔婀娜多姿的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/willowy0205.mp3","us":"media/ldoce/hwd/ame/c/willowy.mp3"},"examples":[{"en":"She was pale and willowy, with violet eyes.","cn":"她肤色白皙﹐身材修长﹐有一双紫罗兰色的眼睛。"}],"oxford":{"phon":"ˈwɪləʊi","pos":"adjective","senses":[{"en":"tall, thin and attractive","cn":"修长苗条的；婀娜多姿的","ex":{"en":"Dark and willowy, she has the natural grace of a ballerina.","cn":"她一头黑发，身材苗条，具有芭蕾舞演员的天然优雅气质。"}}]}},"windswept":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（地方）当风的，受大风吹的","en":"A windswept place has no shelter and is not protected against strong winds.","ex":{"en":"...the remote and windswept hillside.","cn":"偏僻的当风山坡"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if it is windy, there is a lot of wind","cn":""},{"en":"blustery weather is very windy, with sudden strong winds","cn":""},{"en":"if the weather is breezy, the wind blows fairly strongly","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/windswept0205.mp3","us":"media/ldoce/hwd/ame/a/windswept.mp3"},"examples":[{"en":"the windswept Atlantic coast","cn":"受大风侵袭的大西洋海岸"},{"en":"windswept hair","cn":"凌乱的头发"}],"oxford":{"phon":"ˈwɪndswept","pos":"adjective","senses":[{"en":"having strong winds and little protection from them","cn":"受大风吹的；当风的","ex":{"en":"the windswept Atlantic coast","cn":"受大风侵袭的大西洋海岸"}},{"en":"looking as though you have been in a strong wind","cn":"似被风吹散的；乱蓬蓬的","ex":{"en":"windswept hair","cn":"凌乱的头发"}}]}},"wig":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"假发","en":"A wig is a covering of false hair which you wear on your head, for example because you have little hair of your own or because you want to cover up your own hair."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an object covered with artificial hair that you wear on your head","cn":""},{"en":"an area of artificial hair, used to cover a bald part of your head","cn":""},{"en":"a wig or a piece of false hair that you wear on your head to make your own hair look thicker","cn":""}]},"collocations":{"phrases":["ADJ. blond, curly | powdered","VERB + WIG have on, sport, wear Do you think she was wearing a wig? | put on | remove, take off","WIG + VERB perch The wig seemed to perch on his head.","PREP. in a/the ~ Who's that man in the wig?"]},"media":{"img":["media/ldoce/img/wig.jpg"],"uk":"media/ldoce/hwd/bre/0/wig0205.mp3","us":"media/ldoce/hwd/ame/9/whig.mp3"},"oxford":{"phon":"wɪɡ","pos":"noun","senses":[{"en":"a piece of artificial hair that is worn on the head, for example to hide the fact that a person is bald, to cover somebody’s own hair, or by a judge and some other lawyers in some courts of law","cn":"假发","ex":{"en":"Do you think she was wearing a wig?","cn":"你觉得她戴着假发吗？"}}]}},"windsor":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a town in southern England on the River Thames famous for its castle","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/p028-000012968.mp3","us":"media/ldoce/hwd/ame/8/p028-000012968.mp3"},"oxford":{"phon":"ˈwɪnzə(r)","pos":"","senses":[{"en":"a town in southern England on the Thames, west of London. It is famous for its castle.","cn":"温莎（英格兰南部的一个城镇，位于泰晤士河畔，伦敦以西，以城堡闻名）"},{"en":"an industrial city and port in Ontario, Canada, located on Lake Erie opposite the US city of Detroit","cn":"温莎（加拿大安大略省的工业城市和港口，位于伊利湖畔，在美国底特律市对面）"},{"en":"the family name of the British royal family since 1917. It was changed from the German Saxe-Coburg-Gotha by George V because of the strong feelings in Britain against Germany during the First World War.","cn":"温莎（自1917年以来英国王室的家族姓氏。该家族原本的姓氏是萨克森–科堡–哥达，是源自德国的姓氏。第一次世界大战期间，鉴于英国人强烈的反德情绪，乔治五世将这个德国姓氏改为温莎）"}]}},"wishy-washy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(思想)不清楚的，不坚定的，糊涂的","en":"If you say that someone is wishy-washy, you are critical of them because their ideas are not firm or clear.","ex":{"en":"If there's anything I can't stand it's an indecisive, wishy-washy customer.","cn":"如果说我有什么不能容忍的话，那就是犹犹豫豫、挑来挑去的客户。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is wishy-washy does not have firm or clear ideas and seems unable to decide what they want – used to show disapproval 〔","cn":"人〕优柔寡断的﹐没有明确目标的〔含贬义〕"},{"en":"colours that are wishy-washy are pale and unexciting, not strong or dark – used to show disapproval 〔","cn":"色彩〕淡的﹐弱的﹐浅的〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/wishy_washy0205.mp3","us":"media/ldoce/hwd/ame/d/wishy-washy.mp3"},"examples":[{"en":"a wishy-washy liberal","cn":"不坚定的自由主义者"},{"en":"a wishy-washy blue","cn":"淡淡的蓝色"}],"oxford":{"phon":"ˈwɪʃi wɒʃi","pos":"adjective","senses":[{"en":"not having clear or definite ideas or beliefs","cn":"（思想或信仰）稀里糊涂的，不清楚的，不坚定的","ex":{"en":"a wishy-washy liberal","cn":"不坚定的自由主义者"}},{"en":"not bright in colour","cn":"（颜色）浅的，淡的","ex":{"en":"a wishy-washy blue","cn":"淡淡的蓝色"}}]}},"wildfowl":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"野禽","en":"Wildfowl are birds such as ducks, swans, and geese that live close to lakes or rivers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"birds, especially ones that live near water such as duck s 〔","cn":"尤指水边的〕野禽〔如野鸭〕"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41wildfowl.mp3","us":"media/ldoce/hwd/ame/3/wildfowl.mp3"},"oxford":{"phon":"ˈwaɪldfaʊl","pos":"noun","senses":[{"en":"birds that people hunt for sport or food, especially birds that live near water such as ducks and geese","cn":"（尤指生活在水边被人猎食的）野禽，野鸭，野鹅"}]}},"withering":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（眼神、话语）尖刻的，令人难堪的，咄咄逼人的","en":"A withering look or remark is very critical, and is intended to make someone feel ashamed or stupid.","ex":{"en":"Deborah Jane's mother gave her a withering look","cn":"德博拉·简的妈妈狠狠地瞪了她一眼。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a look, remark etc that makes someone feel stupid, embarrassed, or lose confidence","cn":"打击性的眼神/言语等﹐咄咄逼人的眼神/言语等"}]},"vocab":{"pos":"1 n adj 2 adj","senses":[{"en":"Withering is the process of becoming weaker. You can watch the withering of a flower bouquet in water — over the days and weeks, the blossoms become droopy and faded."}]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdewithering.mp3","us":"media/ldoce/hwd/ame/b/withering.mp3"},"examples":[{"en":"She gave him a withering look.","cn":"她极其蔑视地看了他一眼。"},{"en":"withering scorn","cn":"使人难堪的轻蔑"}],"oxford":{"phon":"ˈwɪðərɪŋ","pos":"adjective","senses":[{"en":"intended to make somebody feel silly or ashamed","cn":"尖刻的；使人难堪的；令人无地自容的","ex":{"en":"withering scorn","cn":"使人难堪的轻蔑"}}]}},"withdrawal":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"收回;撤回;停止","en":"The withdrawal of something is the act or process of removing it, or ending it.","ex":{"en":"...withdrawal of friendship","cn":"绝交"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（从活动或组织中）退出","en":"Someone's withdrawal from an activity or an organization is their decision to stop taking part in it.","ex":{"en":"...his withdrawal from government in 1946.","cn":"他1946年退出政府"}},{"pos":"N-COUNT 可数名词","cn":"取款;提款","en":"A withdrawal is an amount of money that you take from your bank account."},{"pos":"N-SING 单数名词","cn":"（对所说的话或声明的）撤回，收回","en":"The withdrawal of a remark or statement that you have made is the act of saying that you want people to ignore it.","ex":{"en":"The charity says it wants a withdrawal of the comments.","cn":"该慈善机构称希望收回所作评论。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"戒毒期;脱瘾过程","en":"Withdrawal is the period during which someone feels ill after they have stopped taking a drug which they were addicted to.","ex":{"en":"Withdrawal from heroin is actually like a severe attack of gastric flu.","cn":"戒断海洛因的过程实际上就像患了一场严重的胃肠型流感。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"孤僻；自闭","en":"Withdrawal is behaviour in which someone prefers to be alone and does not want to talk to other people.","ex":{"en":"...an inability to cope with emotional problems except by retreating into withdrawal.","cn":"无法应对情感问题，只能消极避世"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of moving an army, weapons etc away from the area where they were fighting","cn":"撤军﹔撤退﹔撤回"},{"en":"the removal or stopping of something such as support, an offer, or a service 〔","cn":"对支持﹑建议﹑服务等的〕取消﹐收回"},{"en":"the act of taking money from a bank account, or the amount you take out 〔","cn":"从银行账户中的〕取款﹔取款额"}]},"vocab":{"pos":"n","senses":[{"en":"Withdrawal is when you take something out, like making a withdrawal from your bank account."}]},"collocations":{"phrases":["ADJ. imminent | immediate, rapid, sudden | gradual, phased | complete, full, total, unconditional, wholesale | partial | strategic, tactical","VERB + WITHDRAWAL call for, demand The party is calling for the phased withdrawal of troops from the island. | agree to | announce | make Th","PREP. ~ by a withdrawal by government troops | ~ from the army's withdrawal from the occupied territories 2 from a bank account","ADJ. cash","VERB + WITHDRAWAL make","PREP. ~ from She made a withdrawal of &pound; 250 from her bank account. 3 stopping","ADJ. alcohol, drug","VERB + WITHDRAWAL suffer"]},"media":{"uk":"media/ldoce/hwd/bre/0/withdrawal0205.mp3","us":"media/ldoce/hwd/ame/4/withdrawal.mp3"},"examples":[{"en":"You can make withdrawals of up to $250 a day.","cn":"你一天可以从银行账户中提取最多不超过 250 元。"},{"en":"I got withdrawal symptoms after giving up smoking.","cn":"我戒烟之后出现了脱瘾症状。"}],"oxford":{"phon":"wɪðˈdrɔːəl","pos":"noun","senses":[{"en":"the act of taking an amount of money out of your bank account","cn":"（从银行账户中）提款，取款","g":"[countable]","lab":"informal","ex":{"en":"You can make withdrawals of up to $250 a day.","cn":"你一天最多可以从银行账户中提取 250 美元。"}},{"en":"the act of moving or taking something away or back","cn":"撤走；收回；取回","g":"[uncountable, countable]","ex":{"en":"the withdrawal of support","cn":"不再支持"}},{"en":"the act of no longer taking part in something or being a member of an organization","cn":"不再参加；退出（组织）","g":"[uncountable]","ex":{"en":"his withdrawal from the election","cn":"他从选举中退出"}},{"en":"the period of time when somebody is getting used to not taking a drug that they have become addicted to, and the unpleasant effects of doing this","cn":"戒毒过程；脱瘾期","g":"[uncountable]","ex":{"en":"I got withdrawal symptoms after giving up smoking.","cn":"我戒烟之后出现了脱瘾症状。"}},{"en":"the act of saying that you no longer believe that something you have previously said is true","cn":"（对说过的话的）收回，撤回","g":"[countable, usually singular, uncountable]","ex":{"en":"The newspaper published a withdrawal the next day.","cn":"报纸第二天发表了撤销声明。"}},{"en":"the behaviour of somebody who wants to be alone and does not want to communicate with other people","cn":"退缩；孤僻","g":"[uncountable]","lab":"psychology","ex":{"en":"She is showing signs of withdrawal and depression.","cn":"她表现出孤僻与消沉的现象."}}]}},"wizardry":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指不知道如何完成的)非凡的成就，杰作","en":"You can refer to a very clever achievement or piece of work as wizardry, especially when you do not understand how it is done.","ex":{"en":"...a piece of technical wizardry.","cn":"一桩技术奇迹"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"impressive ability at something or an impressive achievement","cn":"杰出才能﹔杰出成就"}]},"vocab":{"pos":"n","senses":[{"en":"Someone who possesses wizardry is someone who is amazing at what they do, especially if what they do requires creativity. You might rave about your sister's theatrical wizardry after she performs well in the school play."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41wizardry.mp3","us":"media/ldoce/hwd/ame/4/wizardry.mp3"},"examples":[{"en":"The second goal was sheer wizardry.","cn":"第二记入球真是神奇。"},{"en":"electronic wizardry","cn":"电子方面的非凡才能"}],"oxford":{"phon":"ˈwɪzədri","pos":"noun","senses":[{"en":"a very impressive and clever achievement; great skill","cn":"杰出的成就；非凡的才能","ex":{"en":"electronic wizardry","cn":"电子方面的非凡才能"}}]}},"wildebeest":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"牛羚，角马(一种大型非洲羚羊)","en":"A wildebeest is a large African antelope which has a hairy tail, short curved horns, and long hair under its neck. Wildebeest usually live in large groups."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large Southern African animal with a tail and curved horns","cn":"牛羚﹐角马〔产于南非〕"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41wildebeest.mp3","us":"media/ldoce/hwd/ame/f/wildebeest.mp3"},"examples":[{"en":"a herd of wildebeest","cn":"一群牛羚"}],"oxford":{"phon":"ˈwɪldəbiːst","pos":"noun","senses":[{"en":"a large antelope with curved horns","cn":"牛羚；角马","ex":{"en":"a herd of wildebeest","cn":"一群牛羚"}}]}},"wigwam":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同 tepee","en":"A wigwam is the same as a tepee ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a structure with a round or pointed roof used as a home by some Native American tribes in the past 〔","cn":"过去北美印第安人居住的圆顶或尖顶的〕棚屋"}]},"vocab":{"pos":"n","senses":[{"en":"A wigwam is a dome-shaped shelter, covered in bark or hides, built and used by Native Americans. It’s also a really fun word to say out loud."}]},"media":{"uk":"media/ldoce/hwd/bre/4/wigwam0205.mp3","us":"media/ldoce/hwd/ame/b/wigwam.mp3"},"oxford":{"phon":"ˈwɪɡwæm","pos":"noun","senses":[{"en":"a type of tent, like a dome in shape, used by some native North American peoples in the past","cn":"旧时印第安人使用的圆顶或锥形的）棚屋"}]}},"witch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（童话故事中的）女巫，巫婆","en":"In fairy stories, a witch is a woman, usually an old woman, who has evil magic powers. Witches often wear a pointed black hat, and have a pet black cat."},{"pos":"N-COUNT 可数名词","cn":"巫师","en":"A witch is a man or woman who claims to have magic powers and to be able to use them for good or bad purposes."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a woman who is believed to have magic power, which she uses especially to harm people or make bad things happen; in stories, witches are usually shown dressed in black with a tall, pointed hat","cn":""},{"en":"an imaginary creature like a small person with wings, who has magic powers","cn":""},{"en":"a man who is believed to have magic power; in stories, magicians and wizards are usually shown as having a long beard and a pointed hat with stars and moons on it","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A witch is a person with magical powers. Most towns have a spooky old woman with a lot of cats who all the neighborhood kids suspect of being a witch ."}]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdewitch.mp3","us":"media/ldoce/hwd/ame/6/which1.mp3"},"oxford":{"phon":"wɪtʃ","pos":"noun","senses":[{"en":"a woman who is believed to have magic powers, especially to do evil things. In stories, she usually wears a black pointed hat and flies on a broomstick.","cn":"女巫；巫婆","ex":{"en":"Many people believed her to be a witch.","cn":"许多人相信她会巫术。"}},{"en":"an offensive word for an unpleasant woman","cn":"丑老太婆，老巫婆（侮辱性用语）"}]}},"windscreen":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(汽车等的)风挡，挡风玻璃","en":"The windscreen of a car or other vehicle is the glass window at the front through which the driver looks."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the large window at the front of a car, bus etc 〔","cn":"汽车前部的〕挡风玻璃"}]},"collocations":{"phrases":["ADJ. front, rear | car","VERB + WINDSCREEN clean, scrape, wipe She scraped the windscreen free of ice. | break, chip, crack, shatter, smash | fit, put in, replace, t","WINDSCREEN + VERB mist up | crack, shatter","WINDSCREEN + NOUN wiper","PREP. on a/the ~ I came back to find a parking ticket on the windscreen. | through a/the ~ Bright evening sunlight glared through the windsc"]},"media":{"uk":"media/ldoce/hwd/bre/b/windscreen0205.mp3","us":"media/ldoce/hwd/ame/c/windscreen.mp3"},"oxford":{"phon":"ˈwɪndskriːn","pos":"noun","senses":[{"en":"the window across the front of a vehicle","cn":"（机动车前面的）挡风玻璃，风挡","lab":"British English","ex":{"en":"I came back to find a parking ticket on the windscreen.","cn":"我回来时发现挡风玻璃上有一张违章停车罚单。"}}]}},"widower":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鳏夫","en":"A widower is a man whose wife has died and who has not married again."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the man/woman you are married to","cn":""},{"en":"the person you live with and have a sexual relationship with. Partner is often used when people are not married, or when you do not know if they are married. It is also used when talking about same-sex couples","cn":""},{"en":"the man/woman you are engaged to","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If your grandmother has died, you can call your grandfather a widower , or a man whose wife is no longer living."}]},"media":{"uk":"media/ldoce/hwd/bre/8/widower0205.mp3","us":"media/ldoce/hwd/ame/4/widower.mp3"},"oxford":{"phon":"ˈwɪdəʊə(r)","pos":"noun","senses":[{"en":"a man whose wife or husband has died and who has not married again","cn":"鳏夫"}]}},"wimpish":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"同 wimpy","en":"Wimpish means the same as wimpy ."}]},"examples":[{"en":"wimpish behaviour","cn":"懦弱的行为"}],"oxford":{"phon":"ˈwɪmpɪʃ","pos":"adjective","senses":[{"en":"not strong, brave or confident","cn":"懦夫；窝囊废","ex":{"en":"wimpish behaviour","cn":"懦弱的行为"}}]}},"wily":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"诡计多端的;狡诈的;狡猾的","en":"If you describe someone or their behaviour as wily, you mean that they are clever at achieving what they want, especially by tricking people.","ex":{"en":"His appointment as prime minister owed much to the wily manoeuvring of the President.","cn":"他之所以被任命为总理，很大程度上是因为总统在阴谋操纵。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a cunning person gets what they want by thinking carefully about it, making secret plans, and deceiving people","cn":""},{"en":"a sly person secretly deceives people and is always thinking of ways to get advantages for themselves","cn":""},{"en":"a crafty person is good at getting what they want by planning carefully and secretly deceiving people, often in a way that other people admire","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Did you fall for that wily door to door salesman's pitch? He must be very slick and tricky to have convinced you to buy a set of new tires, considering you don't have a car."}]},"media":{"uk":"media/ldoce/hwd/bre/9/wily0205.mp3","us":"media/ldoce/hwd/ame/f/wily.mp3"},"examples":[{"en":"The boss is a wily old fox.","cn":"老板是个狡猾的老狐狸。"},{"en":"a wily politician","cn":"狡猾的政客"}],"oxford":{"phon":"ˈwaɪli","pos":"adjective","senses":[{"en":"clever at getting what you want, and willing to trick people","cn":"狡猾的；诡计多端的；爱捉弄人的","ex":{"en":"The boss is a wily old fox.","cn":"老板是个狡猾的老狐狸。"}}]}}});
